{"command": "mkdir -p /workspace/src && cat > /workspace/tools/gen.py <<'PYEOF'
#!/usr/bin/env python3
import os, re, subprocess, sys

BIN = "/workspace/executable"
OUT = "/workspace/src/langdata.c"

def run(*args):
    r = subprocess.run([BIN]+list(args), capture_output=True, text=True)
    return r.stdout, r.stderr

langs_raw, _ = run("--list-languages")
langs = [l.split(' ')[0] for l in langs_raw.strip().split('\n')]
disabled = set(l.split(' ')[0] for l in langs_raw.strip().split('\n') if '[disabled]' in l)

verbose, _ = run("--verbose", "-o", "/dev/null")
reg = []
m = re.search(r'^Installing parsers:(.*)$', verbose, re.M)
for nm in m.group(1).split(','):
    reg.append(nm.strip())

def mrows(opt):
    out,_ = run("--machinable","--with-list-header=no","--list-"+opt)
    return [l.split('\t') for l in out.rstrip('\n').split('\n') if l]

def rows(opt):
    out,_ = run("--list-"+opt)
    return [l for l in out.rstrip('\n').split('\n') if l]

maps_ext = mrows("map-extensions")
maps_pat = mrows("map-patterns")
maps_rex = mrows("map-rexprs")
aliases = mrows("aliases")
kinds = mrows("kinds-full")
roles = mrows("roles")
fields = mrows("fields")
extras = mrows("extras")
params = mrows("params")
subs = mrows("subparsers")
pseudo = mrows("pseudo-tags")
oforms = mrows("output-formats")
rflags = rows("regex-flags")
mflags = rows("mline-regex-flags")
excludes = rows("excludes")
features = rows("features")
nulltags = {}
for l in open('/tmp/ref/nulltags.txt'):
    nm,_,v = l.strip().partition('|')
    nulltags[nm] = 'yes' in v
versions = {}
for l in open('/tmp/ref/versions.txt'):
    nm,_,v = l.strip().partition('|')
    mm = re.search(r'version: (\S+)', v)
    versions[nm] = mm.group(1)

# group helpers
def group_by(rows, idx):
    d = {}
    for r in rows:
        d.setdefault(r[idx], []).append(r)
    return d

g_ext = group_by(maps_ext, 0)
g_pat = group_by(maps_pat, 0)
g_rex = group_by(maps_rex, 0)
g_ali = group_by(aliases, 0)
g_kin = group_by(kinds, 0)
g_rol = group_by(roles, 0)
g_fld = group_by(fields, 3)
g_exx = group_by(extras, 3)
g_par = group_by(params, 0)
g_sub = group_by(subs, 1)

def esc(s):
    return s.replace('\\','\\\\').replace('"','\\"').replace('\n','\\n').replace('\t','\\t')

# global fields (letter != -) and language fields
gfields = [f for f in fields if f[0] != '-']
lfields = [f for f in fields if f[0] == '-']
gextras = [e for e in extras if e[0] != '-']
lextras = [e for e in extras if e[0] == '-']
gpseudo = pseudo
groles_by_lang = {}
for r in roles:
    groles_by_lang.setdefault(r[0], []).append(r)

# per-language roles: rows format LANGUAGE, KIND(L/N), NAME, ENABLED, VER, DESC
# need kind letter -> look up kind name in that language
kindmap = {}
for k in kinds:
    kindmap[(k[0], k[2])] = k[1]
kindmap_by_letter = {}
for k in kinds:
    kindmap_by_letter[(k[0], k[1])] = k[2]

