				char *n2 = tokNext(&t);
				char *d2 = tokNext(&t);
				gRegexFlags[gNRegexFlags].letter = strdup0(s);
				gRegexFlags[gNRegexFlags].name = strdup0(n2);
				gRegexFlags[gNRegexFlags].desc = dstr(d2);
