				char *d2 = tokNext(&t);
				gMlineFlags[gNMlineFlags].letter = strdup0(s);
				gMlineFlags[gNMlineFlags].name = strdup0(n2);
				gMlineFlags[gNMlineFlags].desc = dstr(d2);
				gNMlineFlags++;
