/* ---------------- listing machinery ---------------- */
static int listMachinable = 0;
static int listHeader = 1;

typedef struct {
	int ncol;
	const char *label[12];
	int nrows, rcap;
	const char **vals;		/* nrows * ncol */
	int withlang;			/* whether first column is language */
} ListT;

static ListT lcur;

static void lbegin(int ncol, ...) {
	va_list_dummy:;
	/* implemented via helper macros below */
}

#include <stdarg.h>

static void lStart(int ncol, const char **labels) {
	lcur.ncol = ncol;
	for (int i = 0; i < ncol; i++) lcur.label[i] = labels[i];
	lcur.nrows = 0;
	if (lcur.vals == NULL) {
		lcur.rcap = 4096;
		lcur.vals = malloc(sizeof(char *) * 12 * lcur.rcap);
	}
	memset(lcur.vals, 0, sizeof(char *) * 12 * 4096);
}

static void lAdd(int ncol, const char **v) {
	if (lcur.nrows >= lcur.rcap) return;
	for (int i = 0; i < ncol; i++)
		lcur.vals[lcur.nrows * 12 + i] = v[i];
	lcur.nrows++;
}

static void lPrint(void) {
	int n = lcur.ncol;
	int mv[12];
	for (int i = 0; i < n; i++) {
		mv[i] = 0;
		for (int r = 0; r < lcur.nrows; r++) {
			const char *v = lcur.vals[r * 12 + i];
			if (v) {
				int l = strlen(v);
				if (l > mv[i]) mv[i] = l;
			}
		}
	}
	int w[12], rw[12];
	for (int i = 0; i < n; i++)
		w[i] = (int)strlen(lcur.label[i]) > mv[i] ? (int)strlen(lcur.label[i]) + 1 : mv[i] + 1;
	for (int i = 0; i < n; i++) rw[i] = w[i];
	rw[0] = w[0] + 1;
	if (n >= 4) {
		rw[n - 3] = w[n - 3] + 2;
		rw[n - 2] = 2;
	}
	if (listHeader) {
		if (listMachinable) {
			for (int i = 0; i < n; i++)
				printf("%s%s", i == 0 ? "#" : "", lcur.label[i]),
				       putchar(i == n - 1 ? '\n' : '\t');
		} else {
			printf("#");
			for (int i = 0; i < n; i++)
				printf("%-*s", i == n - 1 ? 0 : w[i], lcur.label[i]);
			putchar('\n');
		}
	}
	for (int r = 0; r < lcur.nrows; r++) {
		if (listMachinable) {
			for (int i = 0; i < n; i++) {
				const char *v = lcur.vals[r * 12 + i];
				fputs(v ? v : "", stdout);
				putchar(i == n - 1 ? '\n' : '\t');
			}
		} else {
			for (int i = 0; i < n; i++) {
				const char *v = lcur.vals[r * 12 + i];
				if (i == n - 1) fputs(v ? v : "", stdout);
				else printf("%-*s", rw[i], v ? v : "");
			}
			putchar('\n');
		}
	}
}

