void listKinds(const char *lang) {
	Parser *sp = NULL;
	int all = langArgParser(lang, &sp) == 1;
	if (langArgParser(lang, &sp) == -1) {
		fprintf(stderr, "executable: Unknown language \"%s\" in \"list-kinds\" option\n", lang);
		exit(1);
	}
	if (all) {
		for (int i = 0; i < gNParsers; i++) {
			Parser *p = gParsers[i];
			if (p->hidden) continue;
			if (!p->enabled) {
				printf("%s [disabled]\n", p->name);
				continue;
			}
			if (p->nkinds == 0) continue;
			printf("%s\n", p->name);
			/* lowercase letters first, then uppercase, in declaration order */
			int order[128], n = 0;
			for (int j = 0; j < p->nkinds; j++)
				if (islower((unsigned char)p->kinds[j].letter)) order[n++] = j;
			for (int j = 0; j < p->nkinds; j++)
				if (isupper((unsigned char)p->kinds[j].letter)) order[n++] = j;
			for (int j = 0; j < n; j++) {
				Kind *k = &p->kinds[order[j]];
				printf("    %c  %s%s\n", k->letter, k->desc, k->enabled ? "" : " [off]");
			}
		}
	} else {
		if (!sp->enabled) return;
		int order[128], n = 0;
		for (int j = 0; j < sp->nkinds; j++)
			if (islower((unsigned char)sp->kinds[j].letter)) order[n++] = j;
		for (int j = 0; j < sp->nkinds; j++)
			if (isupper((unsigned char)sp->kinds[j].letter)) order[n++] = j;
		for (int j = 0; j < n; j++) {
			Kind *k = &sp->kinds[order[j]];
			printf("%c  %s%s\n", k->letter, k->desc, k->enabled ? "" : " [off]");
		}
	}
}

static int kindCmpLetter(const void *a, const void *b) {
	const Kind *x = *(Kind *const *)a, *y = *(Kind *const *)b;
	return (int)(unsigned char)x->letter - (int)(unsigned char)y->letter;
}

