/* parse a roles spec: [lang][.{kindspec}]; kindspec may be letters/names with wildcards */
static int kindMatchesSpec(const Kind *k, const char *spec) {
	if (!spec || spec[0] == 0 || strcmp(spec, "*") == 0) return 1;
	/* spec is a comma separated list of letters or {names} */
	char buf[512];
	strncpy(buf, spec, sizeof(buf) - 1);
	buf[sizeof(buf) - 1] = 0;
	char *save = NULL;
	char *tok = strtok_r(buf, ",", &save);
	while (tok) {
		if (tok[0] == '{') {
			char *e = strchr(tok, '}');
			char nm[256];
			int l = 0;
			for (char *q = tok + 1; q < e && q; q++) nm[l++] = *q;
			nm[l] = 0;
			if (strcmp(nm, "*") == 0) return 1;
			if (strcmp(nm, k->name) == 0) return 1;
		} else if (strchr(tok, '*') || strchr(tok, '?')) {
			char lb[2] = { k->letter, 0 };
			if (fnmatch(tok, lb, 0) == 0) return 1;
		} else if (tok[0] == k->letter && tok[1] == 0) return 1;
		tok = strtok_r(NULL, ",", &save);
	}
	return 0;
}

void listRoles(const char *spec) {
	Parser *sp = NULL;
	char kindspec[512];
	kindspec[0] = 0;
	const char *langname = spec;
	if (spec) {
		const char *dot = strchr(spec, '.');
		if (dot) {
			size_t l = dot - spec;
			char tmp[256];
			if (l >= sizeof(tmp)) l = sizeof(tmp) - 1;
			memcpy(tmp, spec, l);
			tmp[l] = 0;
			langname = tmp;
			strncpy(kwargspec, dot + 1, sizeof(kwargspec) - 1);
			kindspec[sizeof(kwargspec) - 1] = 0;
		}
	}
	int all = !langname || strcmp(langname, "all") == 0;
	if (langname && !all) {
		sp = findParser(langname);
		if (!sp) {
			fprintf(stderr, "executable: Unknown language \"%s\" in \"list-roles\" option\n", langname);
			exit(1);
		}
	}
	char buf[8][64];
	if (all && !kindspec[0]) {
		const char *labels[6] = { "LANGUAGE", "KIND(L/N)", "NAME", "ENABLED", "VER", "DESCRIPTION" };
		lStart(6, labels);
		for (int i = 0; i < gNParsers; i++) {
			Parser *p = gParsers[i];
			if (p->hidden) continue;
			int order[128], n = 0;
			for (int j = 0; j < p->nkinds; j++) order[n++] = j;
			Kind *sorted[128];
			for (int j = 0; j < n; j++) sorted[j] = &p->kinds[order[j]];
			qsort(sorted, n, sizeof(Kind *), kindCmpLetter);
			for (int j = 0; j < n; j++) {
				Kind *k = sorted[j];
				for (int r = 0; r < p->nroles; r++) {
					Role *ro = &p->roles[r];
					if (ro->kind != k) continue;
					sprintf(buf[0], "%c/%s", k->letter, k->name);
					sprintf(buf[1], "%d", ro->ver);
					const char *v[6] = { p->name, buf[0], ro->name,
							     ro->enabled ? "on" : "off", buf[1], ro->desc };
					lAdd(6, v);
				}
			}
		}
	} else if (all && kindspec[0]) {
		const char *labels[6] = { "LANGUAGE", "KIND(L/N)", "NAME", "ENABLED", "VER", "DESCRIPTION" };
		lStart(6, labels);
		for (int i = 0; i < gNParsers; i++) {
			Parser *p = gParsers[i];
			if (p->hidden) continue;
			int order[128], n = 0;
			for (int j = 0; j < p->nkinds; j++) order[n++] = j;
			Kind *sorted[128];
			for (int j = 0; j < n; j++) sorted[j] = &p->kinds[order[j]];
			qsort(sorted, n, sizeof(Kind *), kindCmpLetter);
			for (int j = 0; j < n; j++) {
				Kind *k = sorted[j];
				if (!kindMatchesSpec(k, kindspec)) continue;
				for (int r = 0; r < p->nroles; r++) {
					Role *ro = &p->roles[r];
					if (ro->kind != k) continue;
					sprintf(buf[0], "%c/%s", k->letter, k->name);
					sprintf(buf[1], "%d", ro->ver);
					const char *v[6] = { p->name, buf[0], ro->name,
							     ro->enabled ? "on" : "off", buf[1], ro->desc };
					lAdd(6, v);
				}
			}
		}
	} else if (!all) {
		const char *labels[5] = { "KIND(L/N)", "NAME", "ENABLED", "VER", "DESCRIPTION" };
		lStart(5, labels);
		Kind *sorted[128];
		int n = sp->nkinds;
		for (int j = 0; j < n; j++) sorted[j] = &sp->kinds[j];
		qsort(sorted, n, sizeof(Kind *), kindCmpLetter);
		for (int j = 0; j < n; j++) {
			Kind *k = sorted[j];
			if (kindspec[0] && !kindMatchesSpec(k, kindspec)) continue;
			for (int r = 0; r < sp->nroles; r++) {
				Role *ro = &sp->roles[r];
				if (ro->kind != k) continue;
				sprintf(buf[0], "%c/%s", k->letter, k->name);
				sprintf(buf[1], "%d", ro->ver);
				const char *v[5] = { buf[0], ro->name, ro->enabled ? "on" : "off", buf[1], ro->desc };
				lAdd(5, v);
			}
		}
	}
	lPrint();
}

