	printf("\n");
	printf("Roles\n");
	printf("-------------------------------------------------------\n");
	printf("#KIND(L/N)  NAME        ENABLED VER DESCRIPTION\n");
	{
		Kind *sorted[128];
		int n = p->nkinds;
		for (int j = 0; j < n; j++) sorted[j] = &p->kinds[j];
		qsort(sorted, n, sizeof(Kind *), kindCmpLetter);
		for (int j = 0; j < n; j++) {
			Kind *k = sorted[j];
			for (int r = 0; r < p->nroles; r++) {
