actions.command:
cat > /workspace/src/langdb.c <<'CEOF'
#include "ctags.h"
#include "langdata.c"

Parser *gParsers[512];
int gNParsers;
GField gFields[64];
int gNFields;
GExtra gExtras[64];
int gNExtras;
PTag gPseudoTags[64];
int gNPseudoTags;
char *gExcludes[128];
int gNExcludes;
FlagRow gRegexFlags[32];
int gNRegexFlags;
FlagRow gMlineFlags[32];
int gNMlineFlags;
OutFormat gOutFormats[16];
int gNOutFormats;
SubRow gSubRows[128];
int gNSubRows;

static char *strdup0(const char *s) {
	size_t l = strlen(s) + 1;
	char *r = malloc(l);
	memcpy(r, s, l);
	return r;
}

/* simple splitter over a mutable string */
typedef struct {
	char *p;
	const char *sep;
} Tok;

static void tokInit(Tok *t, char *p, const char *sep) {
	t->p = p;
	t->sep = sep;
}
static char *tokNext(Tok *t) {
	char *r = t->p;
	if (!r) return NULL;
	char *q = strstr(r, t->sep);
	if (q) { *q = 0; t->p = q + strlen(t->sep); }
	else t->p = NULL;
	return r;
}

static const char *LANGDATA_END = NULL;

static char *nextLine(void) {
	static char *cur = NULL;
	if (!cur) {
		cur = (char *)LANGDATA;
	}
	if (cur >= LANGDATA_END) return NULL;
	char *nl = memchr(cur, '\n', LANGDATA_END - cur);
	if (!nl) { char *r = cur; cur = LANGDATA_END; return r; }
	char *r = cur;
	*nl = 0;
	cur = nl + 1;
	return r;
}

static int unescapeInto(char *dst, const char *src) {
	/* handles \t, \\ , \" and \n produced by the generator */
	int n = 0;
	while (*src) {
		if (*src == '\\' && src[1]) {
			char c = src[1];
			if (c == 't') { dst[n++] = '\t'; src += 2; }
			else if (c == 'n') { dst[n++] = '\n'; src += 2; }
			else { dst[n++] = c; src += 2; }
		} else dst[n++] = *src++;
	}
	dst[n] = 0;
	return n;
}

static char *dstr(const char *s) {
	char buf[8192];
	int n = unescapeInto(buf, s);
	char *r = malloc(n + 1);
	memcpy(r, buf, n + 1);
	return r;
}

int langdb_load(void) {
	char *data = dstr(LANGDATA);
	LANGDATA_END = data + strlen(data);
	char *ln;
	Parser *cur = NULL;
	Kind *kcur[512];
	int nkcur = 0;
	while ((ln = nextLine()) != NULL) {
		if (ln[0] == '@' && ln[1] == 'R') {
			Tok t; tokInit(&t, ln + 5, "\t");
			char *nm;
			int i = 0;
			while ((nm = tokNext(&t)) != NULL) {
				Parser *p = calloc(1, sizeof(Parser));
				p->name = strdup0(nm);
				p->regidx = i;
				if (strcmp(nm, "UniversalCtags") == 0 || strcmp(nm, "CTagsSelfTest") == 0)
					p->hidden = 1;
				gParsers[i++] = p;
			}
			gNParsers = i;
		} else if (ln[0] == '@' && ln[1] == 'L') {
			Tok t; tokInit(&t, ln + 6, "\t");
			char *nm;
			int i = 0;
			while ((nm = tokNext(&t)) != NULL) {
				Parser *p = findParser(nm);
				if (p) p->listidx = i++;
			}
		} else if (strncmp(ln, "@LANG\t", 6) == 0) {
			Tok t; tokInit(&t, ln + 6, "\t");
			char *nm = tokNext(&t);
			char *ver = tokNext(&t);
			char *en = tokNext(&t);
			char *nt = tokNext(&t);
			cur = findParser(nm);
			if (!cur) continue;
			cur->ver = strdup0(ver);
			cur->enabled = (en && en[0] == '1');
			cur->nulltag = (nt && nt[0] == '1');
			cur->maps = calloc(32, sizeof(Map));
			cur->nmaps = 0;
			cur->aliases = calloc(32, sizeof(Alias));
			cur->naliases = 0;
			cur->kinds = calloc(64, sizeof(Kind));
			cur->nkinds = 0;
			cur->roles = calloc(64, sizeof(Role));
			cur->nroles = 0;
			cur->fields = calloc(32, sizeof(LField));
			cur->nfields = 0;
			cur->extras = calloc(32, sizeof(LExtra));
			cur->nextras = 0;
			cur->params = calloc(16, sizeof(Param));
			cur->nparams = 0;
			cur->subs = calloc(16, sizeof(Sub));
			cur->nsubs = 0;
			nkcur = 0;
		} else if (ln[0] == '@') {
			Tok t; tokInit(&t, ln + 3, "\t");
			char c = ln[1];
			if (c == 'F') {
				GField *f = &gFields[gNFields++];
				f->letter = ln[3];
				char *nm = tokNext(&t);
				f->name = (strcmp(nm, "NONE") == 0) ? NULL : strdup0(nm);
				f->enabled = (strcmp(tokNext(&t), "yes") == 0);
				f->jstype = strdup0(tokNext(&t));
				f->fixed = (strcmp(tokNext(&t), "yes") == 0);
				f->op = strdup0(tokNext(&t));
				f->ver = atoi(tokNext(&t));
				f->desc = dstr(tokNext(&t));
			} else if (c == 'X') {
				GExtra *e = &gExtras[gNExtras++];
				e->letter = ln[3];
				e->name = strdup0(tokNext(&t));
				e->enabled = (strcmp(tokNext(&t), "yes") == 0);
				e->fixed = (strcmp(tokNext(&t), "yes") == 0);
				e->ver = atoi(tokNext(&t));
				e->desc = dstr(tokNext(&t));
			} else if (c == 'P') {
				PTag *p = &gPseudoTags[gNPseudoTags++];
				p->name = strdup0(tokNext(&t));
				p->enabled = (strcmp(tokNext(&t), "on") == 0);
				p->ver = atoi(tokNext(&t));
				p->desc = dstr(tokNext(&t));
			} else if (c == 'D') {
				gExcludes[gNExcludes++] = strdup0(tokNext(&t));
			} else if (c == 'C') {
				/* features: ignore here */
			} else if (c == 'r') {
				char *s = tokNext(&t);
				char *n2 = tokNext(&t);
				char *d2 = tokNext(&t);
				gRegexFlags[gNRegexFlags].letter = strdup0(s);
				gRegexFlags[gNRegexFlags].name = strdup0(n2);
				gRegexFlags[gNRegexFlags].desc = dstr(d2);
				gNRegexFlags++;
			} else if (c == 'm') {
				char *s = tokNext(&t);
				char *n2 = tokNext(&t);
				char *d2 = tokNext(&t);
				gMlineFlags[gNMlineFlags].letter = strdup0(s);
				gMlineFlags[gNMlineFlags].name = strdup0(n2);
				gMlineFlags[gNMlineFlags].desc = dstr(d2);
				gNMlineFlags++;
			} else if (c == 'O') {
				OutFormat *o = &gOutFormats[gNOutFormats++];
				o->name = strdup0(tokNext(&t));
				o->def = (strcmp(tokNext(&t), "yes") == 0);
				o->avail = (strcmp(tokNext(&t), "yes") == 0);
				o->nulltag = (strcmp(tokNext(&t), "yes") == 0);
			} else if (c == 'S') {
				SubRow *s = &gSubRows[gNSubRows++];
				s->name = strdup0(tokNext(&t));
				s->base = strdup0(tokNext(&t));
				s->dir = dstr(tokNext(&t));
			}
		} else if (cur) {
			switch (ln[0]) {
			case 'E': case 'P': case 'R': {
				Map *m = &cur->maps[cur->nmaps++];
				if (ln[0] == 'E') {
					m->type = 'e';
					m->pat = malloc(strlen(ln + 2) + 3);
					sprintf((char *)m->pat, "*.%s", ln + 2);
				} else if (ln[0] == 'P') {
					m->type = 'p';
					m->pat = strdup0(ln + 2);
				} else {
					Tok t; tokInit(&t, ln + 2, "\t");
					m->type = 'r';
					m->pat = dstr(tokNext(&t));
					m->caseflag = strdup0(tokNext(&t) ? tokNext(&t) : "sensitive");
				}
				break;
			}
			case 'A': {
				cur->aliases[cur->naliases++].pat = strdup0(ln + 2);
				break;
			}
			case 'K': {
				Tok t; tokInit(&t, ln + 2, "\t");
				Kind *k = &cur->kinds[cur->nkinds++];
				char *l = tokNext(&t);
				k->letter = l[0];
				k->name = strdup0(tokNext(&t));
				k->enabled = (strcmp(tokNext(&t), "yes") == 0);
				k->refonly = (strcmp(tokNext(&t), "yes") == 0);
				k->nroles = atoi(tokNext(&t));
				char *mst = tokNext(&t);
				k->master = (strcmp(mst, "NONE") == 0) ? NULL : strdup0(mst);
				k->ver = atoi(tokNext(&t));
				k->desc = dstr(tokNext(&t));
				break;
			}
			case 'Q': {
				Tok t; tokInit(&t, ln + 2, "\t");
				Role *r = &cur->roles[cur->nroles++];
				char *kl = tokNext(&t);
				char *kn = tokNext(&t);
				for (int i = 0; i < cur->nkinds; i++) {
					if (cur->kinds[i].letter == kl[0] && strcmp(cur->kinds[i].name, kn) == 0) {
						r->kind = &cur->kinds[i];
						break;
					}
				}
				r->name = strdup0(tokNext(&t));
				r->enabled = (strcmp(tokNext(&t), "on") == 0);
				r->ver = atoi(tokNext(&t));
				r->desc = dstr(tokNext(&t));
				break;
			}
			case 'F': {
				Tok t; tokInit(&t, ln + 2, "\t");
				LField *f = &cur->fields[cur->nfields++];
				f->name = strdup0(tokNext(&t));
				f->enabled = (strcmp(tokNext(&t), "yes") == 0);
				(void)tokNext(&t); /* jstype */
				(void)tokNext(&t); /* fixed */
				(void)tokNext(&t); /* op */
				(void)tokNext(&t); /* ver */
				f->desc = dstr(tokNext(&t));
				break;
			}
			case 'X': {
				Tok t; tokInit(&t, ln + 2, "\t");
				LExtra *e = &cur->extras[cur->nextras++];
				e->letter = tokNext(&t)[0];
				e->name = strdup0(tokNext(&t));
				e->enabled = (strcmp(tokNext(&t), "yes") == 0);
				(void)tokNext(&t);
				e->ver = atoi(tokNext(&t));
				e->desc = dstr(tokNext(&t));
				break;
			}
			case 'T': {
				Tok t; tokInit(&t, ln + 2, "\t");
				Param *p = &cur->params[cur->nparams++];
				p->name = strdup0(tokNext(&t));
				p->desc = dstr(tokNext(&t));
				break;
			}
			case 'S': {
				Tok t; tokInit(&t, ln + 2, "\t");
				Sub *s = &cur->subs[cur->nsubs++];
				s->name = strdup0(tokNext(&t));
				s->base = strdup0(tokNext(&t));
				s->dir = dstr(tokNext(&t));
				break;
			}
			}
		}
	}
	return 0;
}

Parser *findParser(const char *name) {
	for (int i = 0; i < gNParsers; i++)
		if (strcmp(gParsers[i]->name, name) == 0) return gParsers[i];
	return NULL;
}
Parser *langByIdx(int i) { return (i >= 0 && i < gNParsers) ? gParsers[i] : NULL; }
int langIndex(const char *name) {
	for (int i = 0; i < gNParsers; i++)
		if (strcmp(gParsers[i]->name, name) == 0) return i;
	return -1;
}

/* ---------------- listing machinery ---------------- */
static int listMachinable = 0;
static int listHeader = 1;

typedef struct {
	int ncol;
	const char *label[12];
	int nrows, rcap;
	const char **vals;		/* nrows * ncol */
	int withlang;			/* whether first column is language */
} ListT;

static ListT lcur;

static void lbegin(int ncol, ...) {
	va_list_dummy:;
	/* implemented via helper macros below */
}

#include <stdarg.h>

static void lStart(int ncol, const char **labels) {
	lcur.ncol = ncol;
	for (int i = 0; i < ncol; i++) lcur.label[i] = labels[i];
	lcur.nrows = 0;
	if (lcur.vals == NULL) {
		lcur.rcap = 4096;
		lcur.vals = malloc(sizeof(char *) * 12 * lcur.rcap);
	}
	memset(lcur.vals, 0, sizeof(char *) * 12 * 4096);
}

static void lAdd(int ncol, const char **v) {
	if (lcur.nrows >= lcur.rcap) return;
	for (int i = 0; i < ncol; i++)
		lcur.vals[lcur.nrows * 12 + i] = v[i];
	lcur.nrows++;
}

static void lPrint(void) {
	int n = lcur.ncol;
	int mv[12];
	for (int i = 0; i < n; i++) {
		mv[i] = 0;
		for (int r = 0; r < lcur.nrows; r++) {
			const char *v = lcur.vals[r * 12 + i];
			if (v) {
				int l = strlen(v);
				if (l > mv[i]) mv[i] = l;
			}
		}
	}
	int w[12], rw[12];
	for (int i = 0; i < n; i++)
		w[i] = (int)strlen(lcur.label[i]) > mv[i] ? (int)strlen(lcur.label[i]) + 1 : mv[i] + 1;
	for (int i = 0; i < n; i++) rw[i] = w[i];
	rw[0] = w[0] + 1;
	if (n >= 4) {
		rw[n - 3] = w[n - 3] + 2;
		rw[n - 2] = 2;
	}
	if (listHeader) {
		if (listMachinable) {
			for (int i = 0; i < n; i++)
				printf("%s%s", i == 0 ? "#" : "", lcur.label[i]),
				       putchar(i == n - 1 ? '\n' : '\t');
		} else {
			printf("#");
			for (int i = 0; i < n; i++)
				printf("%-*s", i == n - 1 ? 0 : w[i], lcur.label[i]);
			putchar('\n');
		}
	}
	for (int r = 0; r < lcur.nrows; r++) {
		if (listMachinable) {
			for (int i = 0; i < n; i++) {
				const char *v = lcur.vals[r * 12 + i];
				fputs(v ? v : "", stdout);
				putchar(i == n - 1 ? '\n' : '\t');
			}
		} else {
			for (int i = 0; i < n; i++) {
				const char *v = lcur.vals[r * 12 + i];
				if (i == n - 1) fputs(v ? v : "", stdout);
				else printf("%-*s", rw[i], v ? v : "");
			}
			putchar('\n');
		}
	}
}

