void listMaps(const char *lang) {
	Parser *sp = NULL;
	int all = langArgParser(lang, &sp) == 1;
	if (langArgParser(lang, &sp) == -1) {
		fprintf(stderr, "executable: Unknown language \"%s\" in \"list-maps\" option\n", lang);
		exit(1);
	}
	if (all) {
		for (int i = 0; i < gNParsers; i++) {
			Parser *p = gParsers[i];
			if (p->hidden) continue;
			if (p->nmaps == 0 && strcmp(p->name, "Unknown") == 0) {
				printf("%-8s\n", p->name);
				continue;
			}
			if (p->nmaps == 0) continue;
			printf("%-8s", p->name);
			for (int j = 0; j < p->nmaps; j++) {
				Map *m = &p->maps[j];
				if (m->type == 'r') printf(" %%%s%%", m->pat);
				else printf(" %s", m->pat);
			}
			putchar('\n');
		}
	} else {
		printf("%-8s", sp->name);
		for (int j = 0; j < sp->nmaps; j++) {
			Map *m = &sp->maps[j];
			if (m->type == 'r') printf(" %%%s%%", m->pat);
			else printf(" %s", m->pat);
		}
		putchar('\n');
	}
}

