/* parse a roles spec: [lang][.{kindspec}]; kindspec may be letters/names with wildcards */
static int kindMatchesSpec(const Kind *k, const char *spec) {
	if (!spec || spec[0] == 0 || strcmp(spec, "*") == 0) return 1;
	/* spec is a comma separated list of letters or {names} */
	char buf[512];
	strncpy(buf, spec, sizeof(buf) - 1);
	buf[sizeof(buf) - 1] = 0;
	char *save = NULL;
	char *tok = strtok_r(buf, ",", &save);
	while (tok) {
		if (tok[0] == '{') {
			char *e = strchr(tok, '}');
			char nm[256];
			int l = 0;
			for (char *q = tok + 1; q < e && q; q++) nm[l++] = *q;
			nm[l] = 0;
			if (strcmp(nm, "*") == 0) return 1;
			if (strcmp(nm, k->name) == 0) return 1;
		} else if (strchr(tok, '*') || strchr(tok, '?')) {
			char lb[2] = { k->letter, 0 };
			if (fnmatch(tok, lb, 0) == 0) return 1;
		} else if (tok[0] == k->letter && tok[1] == 0) return 1;
		tok = strtok_r(NULL, ",", &save);
	}
	return 0;
}

void listRoles(const char *spec) {
	Parser *sp = NULL;
	char kindspec[512];
	kindspec[0] = 0;
	const char *langname = spec;
	if (spec) {
		const char *dot = strchr(spec, '.');
		if (dot) {
			size_t l = dot - spec;
			char tmp[256];
			if (l >= sizeof(tmp)) l = sizeof(tmp) - 1;
			memcpy(tmp, spec, l);
			tmp[l] = 0;
			langname = tmp;
			strncpy(kwargspec, dot + 1, sizeof(kwargspec) - 1);
			kindspec[sizeof(kwargspec) - 1] = 0;
		}
	}
	int all = !langname || strcmp(langname, "all") == 0;
	if (langname && !all) {
		sp = findParser(langname);
		if (!sp) {
			fprintf(stderr, "executable: Unknown language \"%s\" in \"list-roles\" option\n", langname);
			exit(1);
		}
	}
	char buf[8][64];
	if (all && !kindspec[0]) {
		const char *labels[6] = { "LANGUAGE", "KIND(L/N)", "NAME", "ENABLED", "VER", "DESCRIPTION" };
		lStart(6, labels);
		for (int i = 0; i < gNParsers; i++) {
			Parser *p = gParsers[i];
			if (p->hidden) continue;
			int order[128], n = 0;
			for (int j = 0; j < p->nkinds; j++) order[n++] = j;
			Kind *sorted[128];
			for (int j = 0; j < n; j++) sorted[j] = &p->kinds[order[j]];
			qsort(sorted, n, sizeof(Kind *), kindCmpLetter);
			for (int j = 0; j < n; j++) {
				Kind *k = sorted[j];
				for (int r = 0; r < p->nroles; r++) {
					Role *ro = &p->roles[r];
					if (ro->kind != k) continue;
					sprintf(buf[0], "%c/%s", k->letter, k->name);
					sprintf(buf[1], "%d", ro->ver);
					const char *v[6] = { p->name, buf[0], ro->name,
							     ro->enabled ? "on" : "off", buf[1], ro->desc };
					lAdd(6, v);
				}
			}
		}
	} else if (all && kindspec[0]) {
		const char *labels[6] = { "LANGUAGE", "KIND(L/N)", "NAME", "ENABLED", "VER", "DESCRIPTION" };
		lStart(6, labels);
		for (int i = 0; i < gNParsers; i++) {
			Parser *p = gParsers[i];
			if (p->hidden) continue;
			int order[128], n = 0;
			for (int j = 0; j < p->nkinds; j++) order[n++] = j;
			Kind *sorted[128];
			for (int j = 0; j < n; j++) sorted[j] = &p->kinds[order[j]];
			qsort(sorted, n, sizeof(Kind *), kindCmpLetter);
			for (int j = 0; j < n; j++) {
				Kind *k = sorted[j];
				if (!kindMatchesSpec(k, kindspec)) continue;
				for (int r = 0; r < p->nroles; r++) {
					Role *ro = &p->roles[r];
					if (ro->kind != k) continue;
					sprintf(buf[0], "%c/%s", k->letter, k->name);
					sprintf(buf[1], "%d", ro->ver);
					const char *v[6] = { p->name, buf[0], ro->name,
							     ro->enabled ? "on" : "off", buf[1], ro->desc };
					lAdd(6, v);
				}
			}
		}
	} else if (!all) {
		const char *labels[5] = { "KIND(L/N)", "NAME", "ENABLED", "VER", "DESCRIPTION" };
		lStart(5, labels);
		Kind *sorted[128];
		int n = sp->nkinds;
		for (int j = 0; j < n; j++) sorted[j] = &sp->kinds[j];
		qsort(sorted, n, sizeof(Kind *), kindCmpLetter);
		for (int j = 0; j < n; j++) {
			Kind *k = sorted[j];
			if (kindspec[0] && !kindMatchesSpec(k, kindspec)) continue;
			for (int r = 0; r < sp->nroles; r++) {
				Role *ro = &sp->roles[r];
				if (ro->kind != k) continue;
				sprintf(buf[0], "%c/%s", k->letter, k->name);
				sprintf(buf[1], "%d", ro->ver);
				const char *v[5] = { buf[0], ro->name, ro->enabled ? "on" : "off", buf[1], ro->desc };
				lAdd(5, v);
			}
		}
	}
	lPrint();
}

void describeLanguage(const char *name) {
	Parser *p = findParser(name);
	if (!p || p->hidden) {
		fprintf(stderr, "executable: Unknown language \"%s\" in \"describe-language\"\n", name);
		exit(1);
	}
	printf("About %s language\n", p->name);
	printf("=======================================================\n");
	printf("enabled: %s\n", p->enabled ? "yes" : "no");
	printf("version: %s\n", p->ver);
	printf("\n");
	printf("Mappings/rexprs\n");
	printf("-------------------------------------------------------\n");
	for (int i = 0; i < p->nmaps; i++)
		if (p->maps[i].type == 'r')
			printf(" %%%s%%\n", p->maps[i].pat);
	printf("\n");
	printf("Mappings/patterns\n");
	printf("-------------------------------------------------------\n");
	for (int i = 0; i < p->nmaps; i++)
		if (p->maps[i].type == 'p')
			printf(" %s\n", p->maps[i].pat);
	printf("\n");
	printf("Mappings/extensions\n");
	printf("-------------------------------------------------------\n");
	for (int i = 0; i < p->nmaps; i++)
		if (p->maps[i].type == 'e')
			printf(" *.%s\n", p->maps[i].pat + 2);
	printf("\n");
	printf("Aliases\n");
	printf("-------------------------------------------------------\n");
	printf("#ALIAS\n");
	for (int i = 0; i < p->naliases; i++)
		printf("%s\n", p->aliases[i].pat);
	printf("\n");
	printf("Kinds\n");
	printf("-------------------------------------------------------\n");
	printf("#LETTER NAME       ENABLED REFONLY NROLES MASTER VER DESCRIPTION\n");
	{
		Kind *sorted[128];
		int n = p->nkinds;
		for (int j = 0; j < n; j++) sorted[j] = &p->kinds[j];
		qsort(sorted, n, sizeof(Kind *), kindCmpLetter);
		for (int j = 0; j < n; j++) {
			Kind *k = sorted[j];
			printf("%-8c%-11s%-8s%-8s%-7d%-9s%-2d %s\n", k->letter, k->name,
			       k->enabled ? "yes" : "no", k->refonly ? "yes" : "no", k->nroles,
			       k->master ? k->master : "NONE", k->ver, k->desc);
		}
	}
	printf("\n");
	printf("Roles\n");
	printf("-------------------------------------------------------\n");
	printf("#KIND(L/N)  NAME        ENABLED VER DESCRIPTION\n");
	{
		Kind *sorted[128];
		int n = p->nkinds;
		for (int j = 0; j < n; j++) sorted[j] = &p->kinds[j];
		qsort(sorted, n, sizeof(Kind *), kindCmpLetter);
		for (int j = 0; j < n; j++) {
			Kind *k = sorted[j];
			for (int r = 0; r < p->nroles; r++) {
				Role *ro = &p->roles[r];
				if (ro->kind != k) continue;
				printf("%-12s%-12s%-10s%-2d %s\n", bufKind());
			}
		}
	}
	printf("\n");
	printf("Fields\n");
	printf("-------------------------------------------------------\n");
	printf("#LETTER NAME       ENABLED LANGUAGE JSTYPE FIXED OP VER DESCRIPTION\n");
	for (int j = 0; j < p->nfields; j++) {
		LField *f = &p->fields[j];
		printf("%-8s%-11s%-8s%-9s%-7s%-6s%-5s%-2d %s\n", "-", f->name,
		       f->enabled ? "yes" : "no", p->name, "s--", "no", "--", 0, f->desc);
	}
	printf("\n");
	printf("Extras\n");
	printf("-------------------------------------------------------\n");
	printf("#LETTER NAME ENABLED LANGUAGE FIXED VER DESCRIPTION\n");
	for (int j = 0; j < p->nextras; j++) {
		LExtra *e = &p->extras[j];
		printf("%-8s%-5s%-8s%-9s%-8s%-2d %s\n", "-", e->name, e->enabled ? "yes" : "no",
		       p->name, e->fixed ? "yes" : "no", e->ver, e->desc);
	}
	printf("\n");
	printf("Parameters\n");
	printf("-------------------------------------------------------\n");
	printf("#NAME DESCRIPTION\n");
	for (int j = 0; j < p->nparams; j++)
		printf("%-9s%s\n", p->params[j].name, p->params[j].desc);
	printf("\n");
	printf("Sub parsers stacked on this parser\n");
	printf("-------------------------------------------------------\n");
	printf("#NAME BASEPARSER DIRECTIONS\n");
	for (int i = 0; i < gNSubRows; i++)
		if (strcmp(gSubRows[i].base, p->name) == 0)
			printf("%-6s%-11s%s\n", gSubRows[i].name, gSubRows[i].base, gSubRows[i].dir);
	printf("\n");
	printf("Implementation specific status\n");
	printf("-------------------------------------------------------\n");
	printf("allow null tags: %s\n", p->nulltag ? "yes" : "no");
}

