static char *strdup0(const char *s) {
	size_t l = strlen(s) + 1;
	char *r = malloc(l);
	memcpy(r, s, l);
	return r;
}

/* simple splitter over a mutable string */
typedef struct {
	char *p;
	const char *sep;
} Tok;

static void tokInit(Tok *t, char *p, const char *sep) {
	t->p = p;
	t->sep = sep;
}
static char *tokNext(Tok *t) {
	char *r = t->p;
	if (!r) return NULL;
	char *q = strstr(r, t->sep);
	if (q) { *q = 0; t->p = q + strlen(t->sep); }
	else t->p = NULL;
	return r;
}

static const char *LANGDATA_END = NULL;

static char *nextLine(void) {
	static char *cur = NULL;
	if (!cur) {
		cur = (char *)LANGDATA;
	}
	if (cur >= LANGDATA_END) return NULL;
	char *nl = memchr(cur, '\n', LANGDATA_END - cur);
	if (!nl) { char *r = cur; cur = LANGDATA_END; return r; }
	char *r = cur;
	*nl = 0;
	cur = nl + 1;
	return r;
}

static int unescapeInto(char *dst, const char *src) {
	/* handles \t, \\ , \" and \n produced by the generator */
	int n = 0;
	while (*src) {
		if (*src == '\\' && src[1]) {
			char c = src[1];
			if (c == 't') { dst[n++] = '\t'; src += 2; }
			else if (c == 'n') { dst[n++] = '\n'; src += 2; }
			else { dst[n++] = c; src += 2; }
		} else dst[n++] = *src++;
	}
	dst[n] = 0;
	return n;
}

static char *dstr(const char *s) {
	char buf[8192];
	int n = unescapeInto(buf, s);
	char *r = malloc(n + 1);
	memcpy(r, buf, n + 1);
	return r;
}

