				       putchar(i == n - 1 ? '\n' : '\t');
		} else {
			printf("#");
			for (int i = 0; i < n; i++)
				printf("%-*s", i == n - 1 ? 0 : w[i], lcur.label[i]);
			putchar('\n');
		}
	}
	for (int r = 0; r < lcur.nrows; r++) {
		if (listMachinable) {
			for (int i = 0; i < n; i++) {
				const char *v = lcur.vals[r * 12 + i];
				fputs(v ? v : "", stdout);
				putchar(i == n - 1 ? '\n' : '\t');
