{"command": "cat > /workspace/src/option.c <<'CEOF'
#include "ctags.h"

Options opt;
static int optidx;			/* index of first non option argument */

int opt_index_after(void) { return optidx; }

void setDefaults(void) {
	memset(&opt, 0, sizeof(opt));
	opt.sort = 1;
	opt.excmd = 2;			/* mix */
	opt.format = 2;
	opt.output_format = -1;		/* u-ctags */
	opt.tag_relative = 0;
	opt.links = 1;
	opt.recurse = 0;
	opt.maxdepth = -1;
	opt.filter = 0;
	opt.filter_terminator = "";
	opt.tagfile = NULL;
	opt.pattern_length_limit = 96;
	opt.put_field_prefix = 0;
	opt.quiet = 0;
	opt.verbose = 0;
	opt.totals = 0;
	opt.line_directives = 0;
	opt.if0 = 0;
	opt.list_header = 1;
	opt.list_machinable = 0;
	opt.language_force = NULL;
	opt.etags_include = NULL;
	/* default fields: f k s  (plus always-on N F P T) */
	unsigned int f = 0;
	for (int i = 0; i < gNFields; i++)
		if (gFields[i].enabled) f |= (1u << i);
	opt.fields = f;
	/* default extras */
	for (int i = 0; i < gNExtras; i++)
		if (gExtras[i].enabled) opt.extras |= (1u << i);
	for (int i = 0; i < gNParsers; i++) {
		unsigned int m = 0;
		for (int j = 0; j < gParsers[i]->nextras; j++)
			if (gParsers[i]->extras[j].enabled) m |= (1u << j);
		opt.extras_lang[i] = (int)m;
	}
	/* default pseudo tags */
	opt.pseudo_tags = 0;
	for (int i = 0; i < gNPseudoTags; i++)
		if (gPseudoTags[i].enabled) opt.pseudo_tags |= (1u << i);
	/* language enabled flags */
	for (int i = 0; i < gNParsers; i++)
		gParsers[i]->regidx = gParsers[i]->regidx;	/* keep */
	langEnabledInit();
}

/* ------------------ value parsing helpers ------------------ */
static int parseYesNo(const char *v, int defval) {
	if (!v || !*v) return defval;
	if (strcmp(v, "yes") == 0 || strcmp(v, "true") == 0 || strcmp(v, "on") == 0 ||
	    strcmp(v, "1") == 0) return 1;
	if (strcmp(v, "no") == 0 || strcmp(v, "false") == 0 || strcmp(v, "off") == 0 ||
	    strcmp(v, "0") == 0) return 0;
	return -1;
}

static void warn(const char *fmt, ...) {
	va_list ap;
	va_start(ap, fmt);
	char buf[1024];
	vsnprintf(buf, sizeof(buf), fmt, ap);
	va_end(ap);
	fprintf(stderr, "executable: Warning: %s\n", buf);
}

static void errExit(const char *fmt, ...) {
	va_list ap;
	va_start(ap, fmt);
	char buf[1024];
	vsnprintf(buf, sizeof(buf), fmt, ap);
	va_end(ap);
	fprintf(stderr, "executable: %s\n", buf);
	exit(1);
}

/* fields / extras / kinds spec handling */
static void applyFieldFlags(const char *spec) {
	int mode = 0;			/* +1 add, -1 remove, 0 set */
	const char *p = spec;
	if (*p == '+') { mode = 1; p++; }
	else if (*p == '-') { mode = -1; p++; }
	if (strcmp(p, "*") == 0) {
		if (mode >= 0) {
			for (int i = 0; i < gNFields; i++) opt.fields |= (1u << i);
		} else {
			for (int i = 0; i < gNFields; i++) opt.fields &= ~(1u << i);
		}
		return;
	}
	for (; *p; p++) {
		int idx = -1;
		for (int i = 0; i < gNFields; i++)
			if (gFields[i].letter == *p) { idx = i; break; }
		if (idx < 0) { warn("Unsupported parameter '%c' for \"fields\" option", *p); continue; }
		if (mode >= 0) opt.fields |= (1u << idx);
		else opt.fields &= ~(1u << idx);
	}
}

static void applyExtraFlags(const char *spec) {
	int mode = 0;
	const char *p = spec;
	if (*p == '+') { mode = 1; p++; }
	else if (*p == '-') { mode = -1; p++; }
	if (strcmp(p, "*") == 0) {
		if (mode >= 0) for (int i = 0; i < gNExtras; i++) opt.extras |= (1u << i);
		else for (int i = 0; i < gNExtras; i++) opt.extras &= ~(1u << i);
		return;
	}
	for (; *p; p++) {
		int idx = -1;
		for (int i = 0; i < gNExtras; i++)
			if (gExtras[i].letter == *p) { idx = i; break; }
		if (idx < 0) { warn("Unsupported parameter '%c' for \"extras\" option", *p); continue; }
		if (mode >= 0) opt.extras |= (1u << idx);
		else opt.extras &= ~(1u << idx);
	}
}

void applyKindsSpec(Parser *p, const char *spec) {
	int mode = 0;
	const char *s = spec;
	if (*s == '+') { mode = 1; s++; }
	else if (*s == '-') { mode = -1; s++; }
	if (strcmp(s, "*") == 0) {
		for (int i = 0; i < p->nkinds; i++) p->kinds[i].enabled = (mode >= 0);
		return;
	}
	for (; *s; s++) {
		int found = 0;
		for (int i = 0; i < p->nkinds; i++)
			if (p->kinds[i].letter == *s) {
				p->kinds[i].enabled = (mode >= 0);
				found = 1;
			}
		if (!found) warn("Unsupported parameter '%c' for \"kinds-%s\" option", *s, p->name);
	}
}

static void applyExcmd(const char *v) {
	if (strcmp(v, "number") == 0) opt.excmd = 0;
	else if (strcmp(v, "pattern") == 0) opt.excmd = 1;
	else if (strcmp(v, "mix") == 0) opt.excmd = 2;
	else if (strcmp(v, "combine") == 0) opt.excmd = 3;
	else errExit("Invalid value for \"excmd\" option: %s", v);
}

static void applySort(const char *v) {
	if (!v || !*v || strcmp(v, "yes") == 0) opt.sort = 1;
	else if (strcmp(v, "no") == 0) opt.sort = 0;
	else if (strcmp(v, "foldcase") == 0) opt.sort = 2;
	else errExit("Invalid value for \"sort\" option");
}

static void applyTagRelative(const char *v) {
	if (!v || !*v) { opt.tag_relative = (opt.etags_mode ? 1 : 0); return; }
	if (strcmp(v, "yes") == 0) opt.tag_relative = 1;
	else if (strcmp(v, "no") == 0) opt.tag_relative = 0;
	else if (strcmp(v, "always") == 0) opt.tag_relative = 2;
	else if (strcmp(v, "never") == 0) opt.tag_relative = 3;
	else errExit("Invalid value for \"tag-relative\" option");
}

static void applyFormat(const char *v) {
	if (strcmp(v, "1") == 0) opt.format = 1;
	else if (strcmp(v, "2") == 0) opt.format = 2;
	else errExit("Unsupported value for \"format\" option");
}

static void applyOutputFormat(const char *v) {
	for (int i = 0; i < gNOutFormats; i++) {
		if (strcmp(gOutFormats[i].name, v) == 0) {
			if (!gOutFormats[i].avail)
				errExit("unsupported output format name supplied for \"output-format=%s\"", v);
			opt.output_format = i;
			return;
		}
	}
	errExit("unknown output format name supplied for \"output-format=%s\"", v);
}

static void applyLangSpec(const char *prefix, const char *value, const char *oname) {
	/* prefix: e.g. "kinds-C" style: name=<lang>, value=spec */
	char tmp[256];
	strncpy(tmp, prefix, sizeof(tmp) - 1);
	tmp[sizeof(tmp) - 1] = 0;
	(void)value;
	(void)oname;
}

/* process a long option with its value (value may be NULL) */
int processLongOption(const char *name, const char *value) {
	/* listing options */
	if (strcmp(name, "list-languages") == 0) { listLanguages(); return 1; }
	if (strcmp(name, "list-features") == 0) { listFeatures(); return 1; }
	if (strcmp(name, "list-excludes") == 0) { listExcludes(); return 1; }
	if (strcmp(name, "list-aliases") == 0) { listAliases(value); return 1; }
	if (strcmp(name, "list-map-extensions") == 0) { listMapExt(value); return 1; }
	if (strcmp(name, "list-map-patterns") == 0) { listMapPat(value); return 1; }
	if (strcmp(name, "list-map-rexprs") == 0) { listMapRex(value); return 1; }
	if (strcmp(name, "list-maps") == 0) { listMaps(value); return 1; }
	if (strcmp(name, "list-params") == 0) { listParams(value); return 1; }
	if (strcmp(name, "list-subparsers") == 0) { listSubparsers(value); return 1; }
	if (strcmp(name, "list-pseudo-tags") == 0) { listPseudoTags(); return 1; }
	if (strcmp(name, "list-output-formats") == 0) { listOutFormats(); return 1; }
	if (strcmp(name, "list-regex-flags") == 0) { listRegexFlags(0); return 1; }
	if (strcmp(name, "list-mline-regex-flags") == 0) { listRegexFlags(1); return 1; }
	if (strcmp(name, "list-kinds") == 0) { listKinds(value); return 1; }
	if (strcmp(name, "list-kinds-full") == 0) { listKindsFull(value); return 1; }
	if (strcmp(name, "list-fields") == 0) { listFields(value); return 1; }
	if (strcmp(name, "list-extras") == 0) { listExtras(value); return 1; }
	if (strcmp(name, "list-roles") == 0) { listRoles(value); return 1; }
	if (strcmp(name, "machinable") == 0) {
		int v = parseYesNo(value, 1);
		if (v < 0) errExit("Invalid value for \"machinable\" option");
		listMachinable = v;
		return 0;
	}
	if (strcmp(name, "with-list-header") == 0) {
		int v = parseYesNo(value, 1);
		if (v < 0) errExit("Invalid value for \"with-list-header\" option");
		listHeader = v;
		return 0;
	}
	if (strcmp(name, "describe-language") == 0) {
		if (!value) errExit("No language specified for \"describe-language\" option");
		describeLanguage(value);
		return 1;
	}
	if (strcmp(name, "version") == 0) {
		if (value) versionOf(value);
		else printVersion();
		return 1;
	}
	if (strcmp(name, "license") == 0) { printLicense(); return 1; }
	if (strcmp(name, "help") == 0) { printHelp(0); exit(0); }
	if (strcmp(name, "help-full") == 0) { printHelp(1); exit(0); }
	if (strcmp(name, "print-language") == 0) {
		int v = parseYesNo(value, 1);
		if (v < 0) errExit("Invalid value for \"print-language\" option");
		opt.print_language = v;
		return 0;
	}
	if (strcmp(name, "quiet") == 0) {
		int v = parseYesNo(value, 1);
		if (v < 0) errExit("Invalid value for \"quiet\" option");
		opt.quiet = v;
		return 0;
	}
	if (strcmp(name, "verbose") == 0) {
		int v = parseYesNo(value, 1);
		if (v < 0) errExit("Invalid value for \"verbose\" option");
		opt.verbose = v;
		return 0;
	}
	if (strcmp(name, "totals") == 0) {
		int v = parseYesNo(value, 1);
		if (v < 0) errExit("Invalid value for \"totals\" option");
		opt.totals = v;
		return 0;
	}
	if (strcmp(name, "sort") == 0) { applySort(value); return 0; }
	if (strcmp(name, "excmd") == 0) { if (!value) errExit("Invalid value for \"excmd\" option"); applyExcmd(value); return 0; }
	if (strcmp(name, "format") == 0) { if (!value) errExit("Unsupported value for \"format\" option"); applyFormat(value); return 0; }
	if (strcmp(name, "output-format") == 0) { if (!value) errExit("no output format name supplied for \"output-format\""); applyOutputFormat(value); return 0; }
	if (strcmp(name, "tag-relative") == 0) { applyTagRelative(value); return 0; }
	if (strcmp(name, "links") == 0) {
		int v = parseYesNo(value, 1);
		if (v < 0) errExit("Invalid value for \"links\" option");
		opt.links = v;
		return 0;
	}
	if (strcmp(name, "recurse") == 0) {
		int v = parseYesNo(value, 1);
		if (v < 0) errExit("Invalid value for \"recurse\" option");
		opt.recurse = v;
		return 0;
	}
	if (strcmp(name, "append") == 0) {
		int v = parseYesNo(value, 1);
		if (v < 0) errExit("Invalid value for \"append\" option");
		opt.append = v;
		return 0;
	}
	if (strcmp(name, "filter") == 0) {
		int v = parseYesNo(value, 1);
		if (v < 0) errExit("Invalid value for \"filter\" option");
		opt.filter = v;
		return 0;
	}
	if (strcmp(name, "filter-terminator") == 0) {
		if (!value) errExit("No terminator specified for \"filter-terminator\" option");
		opt.filter_terminator = value;
		return 0;
	}
	if (strcmp(name, "maxdepth") == 0) {
		if (!value || !isdigit((unsigned char)value[0])) errExit("-maxdepth: Invalid maximum recursion depth");
		opt.maxdepth = atoi(value);
		return 0;
	}
	if (strcmp(name, "pattern-length-limit") == 0) {
		if (!value || value[0] == '-' || !isdigit((unsigned char)value[0])) errExit("-pattern-length-limit: Invalid pattern length limit");
		opt.pattern_length_limit = atoi(value);
		return 0;
	}
	if (strcmp(name, "fields") == 0) { if (!value) errExit("No parameter specified for \"fields\" option"); applyFieldFlags(value); return 0; }
	if (strcmp(name, "extras") == 0) { if (!value) errExit("No parameter specified for \"extras\" option"); applyExtraFlags(value); return 0; }
	if (strcmp(name, "put-field-prefix") == 0) { opt.put_field_prefix = 1; return 0; }
	if (strcmp(name, "language-force") == 0) {
		if (!value || strcmp(value, "auto") == 0) { opt.language_force = NULL; return 0; }
		if (!findParser(value)) errExit("Unknown language \"%s\" in \"language-force\" option", value);
		opt.language_force = value;
		return 0;
	}
	if (strcmp(name, "guess-language-eagerly") == 0) { opt.guess_language_eagerly = 1; return 0; }
	if (strcmp(name, "exclude") == 0) {
		if (!value) errExit("No exclude pattern specified for \"exclude\" option");
		gExcludes[gNExcludes++] = strdup(value);
		return 0;
	}
	if (strcmp(name, "exclude-exception") == 0) return 0;
	if (strcmp(name, "etags-include") == 0) {
		if (!opt.etags_mode) errExit("Etags must be enabled to use \"etags-include\" option");
		opt.etags_include = value;
		return 0;
	}
	if (strcmp(name, "input-encoding") == 0) { opt.input_encoding_given = 1; return 0; }
	if (strcmp(name, "output-encoding") == 0) { opt.input_encoding_given = 1; return 0; }
	if (strcmp(name, "options") == 0 || strcmp(name, "options-maybe") == 0) return 0;
	if (strcmp(name, "optlib-dir") == 0) return 0;
	if (strcmp(name, "if0") == 0) {
		int v = parseYesNo(value, 1);
		if (v < 0) errExit("Invalid value for \"if0\" option");
		opt.if0 = v;
		return 0;
	}
	if (strcmp(name, "line-directives") == 0) {
		int v = parseYesNo(value, 1);
		if (v < 0) errExit("Invalid value for \"line-directives\" option");
		opt.line_directives = v;
		return 0;
	}
	/* pseudo tags */
	if (strcmp(name, "pseudo-tags") == 0) {
		if (!value) errExit("No pseudo tag specified for \"pseudo-tags\" option");
		int mode = 0;
		const char *s = value;
		if (*s == '+') { mode = 1; s++; }
		else if (*s == '-') { mode = -1; s++; }
		if (strcmp(s, "*") == 0) {
			if (mode >= 0) for (int i = 0; i < gNPseudoTags; i++) opt.pseudo_tags |= (1u << i);
			else for (int i = 0; i < gNPseudoTags; i++) opt.pseudo_tags &= ~(1u << i);
			return 0;
		}
		char buf[256];
		strncpy(buf, s, sizeof(buf) - 1);
		buf[sizeof(buf) - 1] = 0;
		char *save = NULL;
		for (char *tok = strtok_r(buf, ",", &save); tok; tok = strtok_r(NULL, ",", &save)) {
			int idx = -1;
			for (int i = 0; i < gNPseudoTags; i++)
				if (strcmp(gPseudoTags[i].name, tok) == 0) { idx = i; break; }
			if (idx < 0) { warn("Unknown pseudo tag \"%s\" (ignoring \"--pseudo-tags\")", tok); continue; }
			if (mode >= 0) opt.pseudo_tags |= (1u << idx);
			else opt.pseudo_tags &= ~(1u << idx);
		}
		return 0;
	}
	/* language specific: kinds-<LANG>, extras-<LANG>, fields-<LANG>, alias-<LANG>,
	   map-<LANG>, roles-<LANG>.<kind>, param-<LANG>.<name>, input-encoding-<LANG>,
	   langdef etc. */
	if (strncmp(name, "kinds-", 6) == 0) {
		Parser *p = findParser(name + 6);
		if (!p) { warn("Unknown language \"%s\" in \"%s\" option", name + 6, name); return 0; }
		if (!value) errExit("No kind specified for \"%s\" option", name);
		applyKindsSpec(p, value);
		return 0;
	}
	if (strncmp(name, "extras-", 7) == 0) {
		const char *ln = name + 7;
		int mode = 0;
		const char *s = value ? value : "";
		if (*s == '+') { mode = 1; s++; }
		else if (*s == '-') { mode = -1; s++; }
		if (strcmp(ln, "all") == 0) {
			if (strcmp(s, "*") == 0) {
				for (int i = 0; i < gNParsers; i++) {
					unsigned int m = 0;
					if (mode >= 0) m = (unsigned int)-1;
					opt.extras_lang[i] = (int)m;
				}
				return 0;
			}
			for (int i = 0; i < gNParsers; i++) {
				Parser *p = gParsers[i];
				for (int j = 0; j < p->nextras; j++) {
					int hit = 0;
					for (const char *q = s; *q; q++)
						if (p->extras[j].name[0] == *q) hit = 1;
					if (mode >= 0) { if (hit) opt.extras_lang[i] |= (1u << j); }
					else { if (hit) opt.extras_lang[i] &= ~(1u << j); }
				}
			}
			return 0;
		}
		Parser *p = findParser(ln);
		if (!p) { warn("Unknown language: %s (ignoring \"--%s\")", ln, name); return 0; }
		if (strcmp(s, "*") == 0) {
			unsigned int m = 0;
			if (mode >= 0) for (int j = 0; j < p->nextras; j++) m |= (1u << j);
			opt.extras_lang[langIndex(ln)] = (int)m;
			return 0;
		}
		unsigned int cur = (unsigned int)opt.extras_lang[langIndex(ln)];
		for (const char *q = s; *q; q++) {
			int found = 0;
			for (int j = 0; j < p->nextras; j++)
				if (p->extras[j].name[0] == *q) {
					if (mode >= 0) cur |= (1u << j);
					else cur &= ~(1u << j);
					found = 1;
				}
			if (!found) warn("Unknown extra \"%c\" (ignoring)", *q);
		}
		opt.extras_lang[langIndex(ln)] = (int)cur;
		return 0;
	}
	if (strncmp(name, "fields-", 7) == 0) return 0;
	if (strncmp(name, "roles-", 6) == 0) return 0;
	if (strncmp(name, "param-", 6) == 0) return 0;
	if (strncmp(name, "alias-", 6) == 0) return 0;
	if (strncmp(name, "map-", 4) == 0) return 0;
	if (strncmp(name, "langdef", 7) == 0) return 0;
	if (strncmp(name, "regex-", 6) == 0) return 0;
	if (strncmp(name, "mline-regex-", 12) == 0) return 0;
	if (strncmp(name, "kinddef-", 8) == 0) return 0;
	if (strncmp(name, "input-encoding-", 15) == 0) return 0;
	if (strncmp(name, "param-", 6) == 0) return 0;
	return 0;
}

int processShortOption(char c, const char *value, int *consumed) {
	switch (c) {
	case 'R': opt.recurse = 1; return 0;
	case 'a': opt.append = 1; return 0;
	case 'e': opt.etags_mode = 1; opt.tag_relative = 1; return 0;
	case 'x': opt.xref_mode = 1; return 0;
	case 'u': opt.sort = 0; return 0;
	case 'n': opt.excmd = 0; return 0;
	case 'N': opt.excmd = 1; return 0;
	case 'B': opt.excmd = 2; return 0;
	case 'F': opt.excmd = 3; return 0;
	case 'G': opt.guess_language_eagerly = 1; return 0;
	case 'V': opt.verbose = 1; return 0;
	case '?': printHelp(0); exit(0);
	case 'f': case 'o':
		if (!value) errExit("No file name specified for \"%c\" option", c);
		opt.tagfile = value;
		*consumed = 1;
		return 0;
	case 'L':
		if (!value) errExit("No list file specified for \"-L\" option");
		opt.listfile = value;
		*consumed = 1;
		return 0;
	case 'h': {
		/* header extensions list */
		return 0;
	}
	case 'D': return 0;
	case 'I': return 0;
	default:
		errExit("Unknown option: -%c", c);
	}
	return 0;
}
