/* ------------------ value parsing helpers ------------------ */
static int parseYesNo(const char *v, int defval) {
	if (!v || !*v) return defval;
	if (strcmp(v, "yes") == 0 || strcmp(v, "true") == 0 || strcmp(v, "on") == 0 ||
	    strcmp(v, "1") == 0) return 1;
	if (strcmp(v, "no") == 0 || strcmp(v, "false") == 0 || strcmp(v, "off") == 0 ||
	    strcmp(v, "0") == 0) return 0;
	return -1;
}

static void warn(const char *fmt, ...) {
	va_list ap;
	va_start(ap, fmt);
	char buf[1024];
	vsnprintf(buf, sizeof(buf), fmt, ap);
	va_end(ap);
	fprintf(stderr, "executable: Warning: %s\n", buf);
}

static void errExit(const char *fmt, ...) {
	va_list ap;
	va_start(ap, fmt);
	char buf[1024];
	vsnprintf(buf, sizeof(buf), fmt, ap);
	va_end(ap);
	fprintf(stderr, "executable: %s\n", buf);
	exit(1);
}

/* fields / extras / kinds spec handling */
static void applyFieldFlags(const char *spec) {
	int mode = 0;			/* +1 add, -1 remove, 0 set */
	const char *p = spec;
	if (*p == '+') { mode = 1; p++; }
	else if (*p == '-') { mode = -1; p++; }
	if (strcmp(p, "*") == 0) {
		if (mode >= 0) {
			for (int i = 0; i < gNFields; i++) opt.fields |= (1u << i);
		} else {
			for (int i = 0; i < gNFields; i++) opt.fields &= ~(1u << i);
		}
		return;
	}
	for (; *p; p++) {
		int idx = -1;
		for (int i = 0; i < gNFields; i++)
			if (gFields[i].letter == *p) { idx = i; break; }
		if (idx < 0) { warn("Unsupported parameter '%c' for \"fields\" option", *p); continue; }
		if (mode >= 0) opt.fields |= (1u << idx);
		else opt.fields &= ~(1u << idx);
	}
}

static void applyExtraFlags(const char *spec) {
	int mode = 0;
	const char *p = spec;
	if (*p == '+') { mode = 1; p++; }
	else if (*p == '-') { mode = -1; p++; }
	if (strcmp(p, "*") == 0) {
		if (mode >= 0) for (int i = 0; i < gNExtras; i++) opt.extras |= (1u << i);
		else for (int i = 0; i < gNExtras; i++) opt.extras &= ~(1u << i);
		return;
	}
	for (; *p; p++) {
		int idx = -1;
		for (int i = 0; i < gNExtras; i++)
			if (gExtras[i].letter == *p) { idx = i; break; }
		if (idx < 0) { warn("Unsupported parameter '%c' for \"extras\" option", *p); continue; }
		if (mode >= 0) opt.extras |= (1u << idx);
		else opt.extras &= ~(1u << idx);
	}
}

void applyKindsSpec(Parser *p, const char *spec) {
	int mode = 0;
	const char *s = spec;
	if (*s == '+') { mode = 1; s++; }
	else if (*s == '-') { mode = -1; s++; }
	if (strcmp(s, "*") == 0) {
		for (int i = 0; i < p->nkinds; i++) p->kinds[i].enabled = (mode >= 0);
		return;
	}
	for (; *s; s++) {
		int found = 0;
		for (int i = 0; i < p->nkinds; i++)
			if (p->kinds[i].letter == *s) {
				p->kinds[i].enabled = (mode >= 0);
				found = 1;
			}
		if (!found) warn("Unsupported parameter '%c' for \"kinds-%s\" option", *s, p->name);
	}
}

static void applyExcmd(const char *v) {
	if (strcmp(v, "number") == 0) opt.excmd = 0;
	else if (strcmp(v, "pattern") == 0) opt.excmd = 1;
	else if (strcmp(v, "mix") == 0) opt.excmd = 2;
	else if (strcmp(v, "combine") == 0) opt.excmd = 3;
	else errExit("Invalid value for \"excmd\" option: %s", v);
}

static void applySort(const char *v) {
	if (!v || !*v || strcmp(v, "yes") == 0) opt.sort = 1;
	else if (strcmp(v, "no") == 0) opt.sort = 0;
	else if (strcmp(v, "foldcase") == 0) opt.sort = 2;
	else errExit("Invalid value for \"sort\" option");
}

static void applyTagRelative(const char *v) {
	if (!v || !*v) { opt.tag_relative = (opt.etags_mode ? 1 : 0); return; }
	if (strcmp(v, "yes") == 0) opt.tag_relative = 1;
	else if (strcmp(v, "no") == 0) opt.tag_relative = 0;
	else if (strcmp(v, "always") == 0) opt.tag_relative = 2;
	else if (strcmp(v, "never") == 0) opt.tag_relative = 3;
	else errExit("Invalid value for \"tag-relative\" option");
}

static void applyFormat(const char *v) {
	if (strcmp(v, "1") == 0) opt.format = 1;
	else if (strcmp(v, "2") == 0) opt.format = 2;
	else errExit("Unsupported value for \"format\" option");
}

static void applyOutputFormat(const char *v) {
	for (int i = 0; i < gNOutFormats; i++) {
		if (strcmp(gOutFormats[i].name, v) == 0) {
			if (!gOutFormats[i].avail)
				errExit("unsupported output format name supplied for \"output-format=%s\"", v);
			opt.output_format = i;
			return;
		}
	}
	errExit("unknown output format name supplied for \"output-format=%s\"", v);
}

static void applyLangSpec(const char *prefix, const char *value, const char *oname) {
	/* prefix: e.g. "kinds-C" style: name=<lang>, value=spec */
	char tmp[256];
	strncpy(tmp, prefix, sizeof(tmp) - 1);
	tmp[sizeof(tmp) - 1] = 0;
	(void)value;
	(void)oname;
}

