import json
res=json.load(open('anon.json'))
M=1<<32
def h_fnv1a(s):
    h=2166136261
    for c in s.encode():
        h^=c; h=(h*16777619)%M
    return h
def h_fnv1(s):
    h=2166136261
    for c in s.encode():
        h=(h*16777619)%M; h^=c
    return h
def h_djb2(s):
    h=5381
    for c in s.encode(): h=(h*33+c)%M
    return h
def h_djb2x(s):
    h=5381
    for c in s.encode(): h=((h*33)^c)%M
    return h
def h_sdbm(s):
    h=0
    for c in s.encode(): h=(c+(h<<6)+(h<<16)-h)%M
    return h
def h_jenkins(s):
    h=0
    for c in s.encode():
        h=(h+c)%M; h=(h+(h<<10))%M; h^=(h>>6)
    h=(h+(h<<3))%M; h^=(h>>11); h=(h+(h<<15))%M
    return h%M
def h_crc(s):
    import zlib
    return zlib.crc32(s.encode())
def h_adler(s):
    import zlib
    return zlib.adler32(s.encode())
def h_31(s):
    h=0
    for c in s.encode(): h=(h*31+c)%M
    return h
def h_31rev(s):
    h=0
    for c in reversed(s.encode()): h=(h*31+c)%M
    return h
def h_131(s):
    h=0
    for c in s.encode(): h=(h*131+c)%M
    return h
def h_65599(s):
    h=0
    for c in s.encode(): h=(h*65599+c)%M
    return h
