/* ---------------- json ---------------- */
static void jsonEscape(char *out, const char *in) {
	while (*in) {
		switch (*in) {
		case '"': *out++ = '\\'; *out++ = '"'; break;
		case '\\': *out++ = '\\'; *out++ = '\\'; break;
		case '\t': *out++ = '\\'; *out++ = 't'; break;
		case '\n': *out++ = '\\'; *out++ = 'n'; break;
		case '\r': *out++ = '\\'; *out++ = 'r'; break;
		case '\b': *out++ = '\\'; *out++ = 'b'; break;
		case '\f': *out++ = '\\'; *out++ = 'f'; break;
		default: *out++ = *in;
		}
		in++;
	}
	*out = 0;
}

static void writeJsonEntry(const char *qualified, int isQualified, int inputFile) {
	char buf[65536];
