		else escapePattern(esc, cur.pattern);
		if (cur.patternComplete) sprintf(pat, "/^%s$/", esc);
		else sprintf(pat, "/^%s/", esc);
	} else {
		makePattern(pat);
		/* strip the leading /^ and trailing $/ for json */
	}
	char nameE[2048], fileE[2048], patE[8192];
	jsonEscape(nameE, cur.name);
	jsonEscape(fileE, curInputFile);
	jsonEscape(patE, pat);
	int p = sprintf(buf, "{\"_type\": \"tag\", \"name\": \"%s\", \"path\": \"%s\", \"pattern\": \"%s\"",
			nameE, fileE, patE);
	char tmp[4096];
	(void)qualified;
	if (cur.isfile) { p += sprintf(buf + p, ", \"file\": true"); }
	if (hasField(FID_LINE)) p += sprintf(buf + p, ", \"line\": %d", cur.line);
	if (hasField(FID_KIND_LONG)) { }
	/* kind long name passed via cur.scope? we use cur.role for kind name */
	if (cur.role[0]) p += sprintf(buf + p, ", \"kind\": \"%s\"", cur.role);
	if (cur.scope[0]) {
		const char *c = strchr(cur.scope, ':');
		if (hasField(FID_SCOPEKIND)) {
			char sk[256];
			int l = c ? (int)(c - cur.scope) : (int)strlen(cur.scope);
			memcpy(sk, cur.scope, l); sk[l] = 0;
			p += sprintf(buf + p, ", \"scopeKind\": \"%s\"", sk);
		}
		if (hasField(FID_SCOPE_PREFIX)) p += sprintf(buf + p, ", \"scope\": \"%s\"", c ? c + 1 : cur.scope);
	}
	if (cur.inherits[0]) p += sprintf(buf + p, ", \"inherits\": \"%s\"", cur.inherits);
	if (cur.access[0]) p += sprintf(buf + p, ", \"access\": \"%s\"", cur.access);
	if (cur.signature[0]) p += sprintf(buf + p, ", \"signature\": \"%s\"", cur.signature);
	if (cur.role[0] && cur.reference) p += sprintf(buf + p, ", \"roles\": \"%s\"", cur.role);
	if (cur.langfields[0]) {
		char lf2[2048];
		strcpy(lf2, cur.langfields);
		char *tok, *save = NULL;
		for (tok = strtok_r(lf2, "\t", &save); tok; tok = strtok_r(NULL, "\t", &save)) {
			char *c = strchr(tok, ':');
			if (!c) continue;
			*c = 0;
			char ke[512], ve[1024];
			jsonEscape(ke, tok);
			jsonEscape(ve, c + 1);
			p += sprintf(buf + p, ", \"%s\": \"%s\"", ke, ve);
		}
	}
	p += sprintf(buf + p, "}\n");
	addTagLine(buf);
}

/* entry point used by parsers */
void makeTagEntry(const Kind *kind, int qualified, int inputFile)
{
	if (opt.xref_mode) { writeXrefEntry(); return; }
	if (opt.etags_mode) { writeEtagsEntry(0); return; }
	if (opt.output_format >= 0 && strcmp(gOutFormats[opt.output_format].name, "json") == 0) {
		/* kind long name for json */
		char kn[256];
		strcpy(kn, cur.role);
		(void)kn;
		writeJsonEntry(NULL, qualified, inputFile);
		return;
	}
	writeCtagsEntry(NULL, qualified, inputFile);
	(void)kind;
}
