#include <stdarg.h>
#include "ctags.h"

/* ---------------- tag storage ---------------- */
typedef struct {
	char *line;
} TagRec;
static TagRec *tags;
static int ntags, tagscap;
int nTagsOut;

void addTagLine(const char *line) {
	if (ntags >= tagscap) {
		tagscap = tagscap ? tagscap * 2 : 4096;
		tags = realloc(tags, sizeof(TagRec) * tagscap);
	}
	tags[ntags++].line = strdup(line);
	nTagsOut++;
}

int tagCount(void) { return ntags; }
const char *tagLine(int i) { return tags[i].line; }

/* ---------------- current tag state ---------------- */
CurTag cur;
const char *curInputFile;
const char *curLangName;
int curInputLine;
char curLine[65536];
long curLineOffset;

static void escapePattern(char *out, const char *in) {
	while (*in) {
		if (*in == '\\') { *out++ = '\\'; *out++ = '\\'; }
		else if (*in == '/') { *out++ = '\\'; *out++ = '/'; }
		else *out++ = *in;
		in++;
	}
	*out = 0;
}

static int patternLimit(void) { return opt.pattern_length_limit; }

/* limit: total length of "<pattern>" inside the delimiters */
static void buildPattern(char *out, const char *text, int complete) {
	char esc[8192];
	escapePattern(esc, text);
	int lim = patternLimit();
	if (lim > 0) {
		int avail = lim - 4;
		if (avail < 0) avail = 0;
		if ((int)strlen(esc) > avail) esc[avail] = 0;
	}
	if (complete) sprintf(out, "/^%s$/", esc);
	else sprintf(out, "/^%s/", esc);
}

static void defaultPattern(char *out) {
	buildPattern(out, curLine, 1);
}

static int hasField(int id) { return (opt.fields & (1u << id)) != 0; }

static int extraOn(const char *nm, int qualified, int inputFile) {
	for (int i = 0; i < gNExtras; i++) {
		if (!(opt.extras & (1u << i))) continue;
		if (strcmp(gExtras[i].name, nm) == 0) return 1;
	}
	if (strcmp(nm, "fileScope") == 0) return 1;
	if (strcmp(nm, "qualified") == 0) return qualified;
	if (strcmp(nm, "inputFile") == 0) return inputFile;
	return 0;
}

static void extrasString(char *out, int qualified, int inputFile) {
	static const char *order[] = { "fileScope", "inputFile", "pseudo", "qualified",
				       "reference", "guest", "subparser", "anonymous", "nulltag" };
	int n = 0;
	out[0] = 0;
	for (unsigned i = 0; i < sizeof(order) / sizeof(order[0]); i++) {
		const char *nm = order[i];
		int on = 0;
		if (strcmp(nm, "fileScope") == 0) on = 1;
		else if (strcmp(nm, "inputFile") == 0) on = inputFile;
		else if (strcmp(nm, "qualified") == 0) on = qualified;
		if (!on) continue;
		if (!extraOn(nm, qualified, inputFile)) continue;
		if (n++) strcat(out, ",");
		strcat(out, nm);
	}
}

static const char *kindLongName(void) { return cur.kindName ? cur.kindName : ""; }

static void appendField(char *buf, int *p, const char *fmt, ...) {
	char tmp[8192];
	va_list ap;
	va_start(ap, fmt);
	vsnprintf(tmp, sizeof(tmp), fmt, ap);
	va_end(ap);
	int l = sprintf(buf + *p, "\t%s", tmp);
	*p += l;
}

/* ---------------- u-ctags / e-ctags ---------------- */
static void writeCtagsEntry(int qualified, int inputFile) {
	char buf[131072];
	char pat[8192];
	if (cur.pattern[0]) buildPattern(pat, cur.pattern, cur.patternComplete);
	else defaultPattern(pat);
	int p = sprintf(buf, "%s\t%s\t%s", cur.name, curInputFile, pat);
	if (opt.format == 2) p += sprintf(buf + p, ";\"");
	char tmp[8192];
