	if (hasField(FID_KIND_SHORT)) {
		if (opt.fields & (1u << FID_KIND_LONG)) {
			if (hasField(FID_KIND_LONG) == 0) {}
		}
		if (opt.fields & (1u << FID_KIND_PREFIX)) {
			if (opt.fields & (1u << FID_KIND_LONG))
				p += sprintf(buf + p, "\tkind:%s", kindLongName());
			else
				p += sprintf(buf + p, "\tkind:%c", cur.kindLetter);
		} else if (opt.fields & (1u << FID_KIND_LONG))
			p += sprintf(buf + p, "\t%s", kindLongName());
		else
			p += sprintf(buf + p, "\t%c", cur.kindLetter);
	}
	if (hasField(FID_LINE)) p += sprintf(buf + p, "\tline:%d", cur.line);
	if (hasField(FID_LANGUAGE) && curLangName) p += sprintf(buf + p, "\tlanguage:%s", curLangName);
	if (hasField(FID_SCOPE) && cur.scope[0]) {
