			p += sprintf(buf + p, "\t%s", cur.scope);
	}
	if (hasField(FID_INHERITS)) p += sprintf(buf + p, "\tinherits:%s", cur.inherits);
	if (hasField(FID_TYPEREF) && cur.typeref[0]) p += sprintf(buf + p, "\ttyperef:%s", cur.typeref);
	if (hasField(FID_FILE) && cur.isfile) p += sprintf(buf + p, "\tfile:");
	if (hasField(FID_ACCESS) && cur.access[0]) p += sprintf(buf + p, "\taccess:%s", cur.access);
