	if (hasField(FID_NTH) && cur.nth >= 0) p += sprintf(buf + p, "\tnth:%d", cur.nth);
	if (hasField(FID_COMPACT)) { }
	if (hasField(FID_XPATH) && cur.xpath[0]) p += sprintf(buf + p, "\txpath:%s", cur.xpath);
	if (cur.langfields[0]) {
		char lf2[4096];
		strcpy(lf2, cur.langfields);
		char *tok, *save = NULL;
		for (tok = strtok_r(lf2, "\t", &save); tok; tok = strtok_r(NULL, "\t", &save))
			p += sprintf(buf + p, "\t%s", tok);
	}
	sprintf(buf + p, "\n");
	addTagLine(buf);
}

/* ---------------- xref ---------------- */
static void writeXrefEntry(void) {
	char src[65536];
	char *s = curLine;
	while (*s == ' ' || *s == '\t') s++;
	strcpy(src, s);
	char *nl = strchr(src, '\n');
	if (nl) *nl = 0;
	printf("%-16s %-12s %3d %-16s %s\n", cur.name, kindLongName(), cur.line, curInputFile, src);
}

/* ---------------- etags ---------------- */
static void writeEtagsEntry(void) {
	const char *pt = cur.pattern[0] ? cur.pattern : curLine;
	char tmp[8192];
	size_t l = strlen(pt);
	if (l >= sizeof(tmp)) l = sizeof(tmp) - 1;
	memcpy(tmp, pt, l);
	tmp[l] = 0;
	char *nl = strchr(tmp, '\n');
	if (nl) *nl = 0;
	printf("%s\177%s\001%d,%ld\n", tmp, cur.name, cur.line, curLineOffset);
}

/* ---------------- json ---------------- */
static void jsonEscape(char *out, const char *in) {
	while (*in) {
		switch (*in) {
		case '"': *out++ = '\\'; *out++ = '"'; break;
		case '\\': *out++ = '\\'; *out++ = '\\'; break;
		case '\t': *out++ = '\\'; *out++ = 't'; break;
		case '\n': *out++ = '\\'; *out++ = 'n'; break;
		case '\r': *out++ = '\\'; *out++ = 'r'; break;
		case '\b': *out++ = '\\'; *out++ = 'b'; break;
		case '\f': *out++ = '\\'; *out++ = 'f'; break;
		default: *out++ = *in;
		}
		in++;
	}
	*out = 0;
}

static void writeJsonEntry(int qualified, int inputFile) {
	char buf[131072];
	char pat[8192];
	char nameE[4096], fileE[4096], patE[8192];
	if (cur.pattern[0]) buildPattern(pat, cur.pattern, cur.patternComplete);
	else if (cur.patternNoPattern) strcpy(pat, "");
	else defaultPattern(pat);
	jsonEscape(nameE, cur.name);
	jsonEscape(fileE, curInputFile);
	jsonEscape(patE, pat);
	int p = sprintf(buf, "{\"_type\": \"tag\", \"name\": \"%s\", \"path\": \"%s\"",
			nameE, fileE);
	if (cur.patternNoPattern) p += sprintf(buf + p, ", \"pattern\": false");
	else p += sprintf(buf + p, ", \"pattern\": \"%s\"", patE);
	if (cur.isfile) p += sprintf(buf + p, ", \"file\": true");
	if (hasField(FID_LANGUAGE) && curLangName) p += sprintf(buf + p, ", \"language\": \"%s\"", curLangName);
	if (hasField(FID_LINE)) p += sprintf(buf + p, ", \"line\": %d", cur.line);
	if (hasField(FID_TYPEREF) && cur.typeref[0]) {
		char te[2048];
		jsonEscape(te, cur.typeref);
		p += sprintf(buf + p, ", \"typeref\": \"%s\"", te);
	}
	if (opt.fields & ((1u << FID_KIND_SHORT) | (1u << FID_KIND_LONG)))
		p += sprintf(buf + p, ", \"kind\": \"%s\"", kindLongName());
	if (hasField(FID_ACCESS) && cur.access[0]) {
		char te[512];
