	if (hasField(FID_SCOPE) && cur.scope[0]) {
		const char *c = strchr(cur.scope, ':');
		char sk[512];
		int l = c ? (int)(c - cur.scope) : (int)strlen(cur.scope);
		memcpy(sk, cur.scope, l); sk[l] = 0;
		char te[1024];
		jsonEscape(te, c ? c + 1 : cur.scope);
		p += sprintf(buf + p, ", \"scope\": \"%s\"", te);
