			jsonEscape(te, sk);
			p += sprintf(buf + p, ", \"scopeKind\": \"%s\"", te);
		}
	}
	if (hasField(FID_INHERITS)) {
		char te[2048];
		jsonEscape(te, cur.inherits);
		p += sprintf(buf + p, ", \"inherits\": \"%s\"", te);
