			char te[2048];
			jsonEscape(te, es);
			p += sprintf(buf + p, ", \"extras\": \"%s\"", te);
		}
	}
	if (hasField(FID_END) && cur.endline > 0) p += sprintf(buf + p, ", \"end\": %d", cur.endline);
	if (hasField(FID_EPOCH) && cur.isfile) {
		struct stat st;
		if (stat(curInputFile, &st) == 0)
			p += sprintf(buf + p, ", \"epoch\": %ld", (long)st.st_mtime);
	}
	if (hasField(FID_NTH) && cur.nth >= 0) p += sprintf(buf + p, ", \"nth\": %d", cur.nth);
	if (hasField(FID_IMPL) && cur.impl[0]) {
