/* ---------------- language detection ---------------- */
static int isHeaderFile(const char *name);

static int matchMap(Map *m, const char *name, const char *ext) {
	if (m->type == 'e') {
		if (!ext) return 0;
		return strcmp(m->pat, ext) == 0;
	} else if (m->type == 'p') {
		return fnmatch(m->pat, name, FNM_PATHNAME) == 0;
	}
	return 0;
}

static const char *fileExtension(const char *name) {
	const char *b = strrchr(name, '/');
	const char *d = strrchr(b ? b : name, '.');
	if (!d || d == (b ? b : name)) return NULL;
	return d + 1;
}

typedef struct { Parser *p; int kind; const char *info; } Cand;

static Cand cands[64];
static int ncands;

static void collectCandidates(const char *name) {
	ncands = 0;
	const char *ext = fileExtension(name);
	for (int i = 0; i < gNParsers; i++) {
		Parser *p = gParsers[i];
		if (p->hidden || !p->langEnabled) continue;
		for (int j = 0; j < p->nmaps; j++) {
			Map *m = &p->maps[j];
			if (matchMap(m, name, ext)) {
				char info[512];
				if (m->type == 'e') sprintf(info, "extension: \"%s\"", ext);
				else sprintf(info, "pattern: \"%s\"", m->pat);
				cands[ncands].p = p;
				cands[ncands].kind = m->type;
				cands[ncands].info = strdup(info);
				ncands++;
				break;
			}
		}
	}
	/* aliases */
	for (int i = 0; i < gNParsers; i++) {
		Parser *p = gParsers[i];
		if (p->hidden || !p->langEnabled) continue;
		const char *b = strrchr(name, '/');
		b = b ? b + 1 : name;
		for (int j = 0; j < p->naliases; j++)
			if (fnmatch(p->aliases[j].pat, b, FNM_PATHNAME) == 0) {
				cands[ncands].p = p;
				cands[ncands].kind = 'a';
				char info[512];
				sprintf(info, "alias: \"%s\"", p->aliases[j].pat);
				cands[ncands].info = strdup(info);
				ncands++;
				break;
			}
	}
}

static int isExecutable(const char *name) {
	struct stat st;
	if (stat(name, &st) != 0) return 0;
	return (st.st_mode & S_IXUSR) != 0;
}

/* look for a shebang line and map it to a language */
static Parser *guessFromShebang(const char *name) {
	FILE *fp = fopen(name, "rb");
	if (!fp) return NULL;
	char buf[512];
	if (!fgets(buf, sizeof(buf), fp)) { fclose(fp); return NULL; }
	fclose(fp);
	if (strncmp(buf, "#!", 2) != 0) return NULL;
	char *p = buf + 2;
	while (*p == ' ' || *p == '\t') p++;
	/* "/usr/bin/env python3" or "/bin/bash" */
	char words[8][128];
	int nw = 0;
	char tmp[512];
	strncpy(tmp, p, sizeof(tmp) - 1);
	tmp[sizeof(tmp) - 1] = 0;
	char *nl = strchr(tmp, '\n');
	if (nl) *nl = 0;
	char *save = NULL;
	for (char *tok = strtok_r(tmp, " \t", &save); tok && nw < 8; tok = strtok_r(NULL, " \t", &save)) {
		strncpy(words[nw++], tok, 127);
		words[nw - 1][127] = 0;
	}
	const char *prog = NULL;
	if (nw >= 2 && strcmp(words[0], "/usr/bin/env") == 0) prog = words[1];
	else if (nw >= 1) { const char *sl = strrchr(words[0], '/'); prog = sl ? sl + 1 : words[0]; }
	if (!prog) return NULL;
	/* find a parser whose name/alias matches the program */
	for (int i = 0; i < gNParsers; i++) {
		Parser *q = gParsers[i];
		if (q->hidden || !q->langEnabled) continue;
		if (strcasecmp(q->name, prog) == 0) return q;
		for (int j = 0; j < q->naliases; j++) {
			const char *ap = q->aliases[j].pat;
			if (strchr(ap, '*') || strchr(ap, '?')) {
				if (fnmatch(ap, prog, 0) == 0) return q;
			} else if (strcasecmp(ap, prog) == 0) return q;
		}
	}
	/* python[23]* style */
	return NULL;
}

Parser *guessLanguage(const char *name) {
	if (opt.language_force) {
		Parser *p = findParser(opt.language_force);
		return p;
	}
	collectCandidates(name);
	if (ncands == 0) {
		if (opt.guess_language_eagerly || isExecutable(name)) {
			Parser *p = guessFromShebang(name);
			if (p) return p;
		}
		return NULL;
	}
	if (ncands == 1) {
		Parser *p = cands[0].p;
		if (opt.guess_language_eagerly || isExecutable(name)) {
			Parser *q = guessFromShebang(name);
			if (q) return q;
		}
		return p;
	}
	/* multiple candidates: try the shebang first */
	if (opt.guess_language_eagerly || isExecutable(name)) {
		Parser *q = guessFromShebang(name);
		if (q) {
			for (int i = 0; i < ncands; i++)
				if (cands[i].p == q) return q;
		}
	}
	/* XML family: use the generic XML parser if the content looks like XML */
	for (int i = 0; i < ncands; i++) {
		if (strcmp(cands[i].p->name, "XML") == 0) {
			FILE *fp = fopen(name, "rb");
			if (fp) {
				char b[64];
				size_t n = fread(b, 1, sizeof(b) - 1, fp);
				fclose(fp);
				b[n] = 0;
				const char *s = b;
				while (*s == ' ' || *s == '\t' || *s == '\n' || *s == '\r') s++;
				if (strncmp(s, "<?xml", 5) == 0) return cands[i].p;
			}
		}
	}
	return cands[0].p;
}

void guessAndPrintLanguage(const char *name) {
	Parser *p = guessLanguage(name);
	printf("%s: %s\n", name, p ? p->name : "NONE");
}

/* ---------------- input collection ---------------- */
typedef struct FileNode {
	char *name;
	struct FileNode *next;
} FileNode;
static FileNode *fileHead, *fileTail;
int nInputFiles;
int nSourceLines;
int nSourceFiles;
double startTime;
int nSortedTags;

void addInputFile(const char *name) {
	FileNode *n = malloc(sizeof(FileNode));
	n->name = strdup(name);
	n->next = NULL;
	if (fileTail) fileTail->next = n; else fileHead = n;
	fileTail = n;
	nInputFiles++;
}

int isLinkPath(const char *p) {
	struct stat st;
	return lstat(p, &st) == 0 && S_ISLNK(st.st_mode);
}

static int excludedBy(const char **pats, int n, const char *name) {
	for (int i = 0; i < n; i++)
		if (fnmatch(pats[i], name, FNM_PATHNAME) == 0) return 1;
	return 0;
}

static char *userExcludes[128];
static int nUserExcludes;
static char *userExcepts[128];
static int nUserExcepts;

static int matchesExclude(const char *name) {
	for (int i = 0; i < nUserExcepts; i++)
		if (fnmatch(userExcepts[i], name, FNM_PATHNAME) == 0) return 0;
	for (int i = 0; i < nUserExcludes; i++)
		if (fnmatch(userExcludes[i], name, FNM_PATHNAME) == 0) return 1;
	return excludedBy((const char **)gExcludes, gNExcludes, name);
}

static int isDirP(const char *p) {
	struct stat st;
	if (stat(p, &st) != 0) return 0;
	return S_ISDIR(st.st_mode);
}

static void scanDir(const char *dir, int depth) {
	DIR *d = opendir(dir);
	if (!d) return;
	struct dirent *e;
	while ((e = readdir(d)) != NULL) {
		if (strcmp(e->d_name, ".") == 0 || strcmp(e->d_name, "..") == 0) continue;
		if (matchesExclude(e->d_name)) continue;
		char buf[8192];
		snprintf(buf, sizeof(buf), "%s/%s", dir, e->d_name);
		if (isDirP(buf)) {
			if (opt.maxdepth < 0 || depth < opt.maxdepth) scanDir(buf, depth + 1);
		} else if (opt.links || !isLinkPath(buf)) {
			if (matchesExclude(e->d_name)) continue;
			addInputFile(buf);
		}
	}
	closedir(d);
}

static char **cmdFiles;
static int nCmdFiles, cmdFileCap;

static void addCmdFile(const char *name) {
	if (nCmdFiles >= cmdFileCap) {
		cmdFileCap = cmdFileCap ? cmdFileCap * 2 : 64;
		cmdFiles = realloc(cmdFiles, sizeof(char *) * cmdFileCap);
	}
	cmdFiles[nCmdFiles++] = strdup(name);
}

void collectFiles(int argc, char **argv) {
	int i = opt_index_after();
	for (; i < argc; i++) addCmdFile(argv[i]);
	if (opt.listfile) {
		FILE *fp = strcmp(opt.listfile, "-") == 0 ? stdin : fopen(opt.listfile, "r");
		if (fp) {
			char line[8192];
			while (fgets(line, sizeof(line), fp)) {
				size_t l = strlen(line);
				while (l && (line[l - 1] == '\n' || line[l - 1] == '\r')) line[--l] = 0;
				if (line[0]) addCmdFile(line);
			}
			if (fp != stdin) fclose(fp);
		}
	}
	for (int k = 0; k < nCmdFiles; k++) {
		const char *nm = cmdFiles[k];
		if (isDirP(nm)) {
			if (opt.recurse) {
				char buf[8192];
				snprintf(buf, sizeof(buf), "%s", nm);
				scanDir(buf, 1);
			}
		} else {
			addInputFile(nm);
		}
	}
}

/* ---------------- pseudo tags ---------------- */
static const char *progCwd;

void writePseudoTags(FILE *fp) {
	/* TAG_* pseudo tags; order as observed */
	if (opt.output_format >= 0 && strcmp(gOutFormats[opt.output_format].name, "json") == 0) {
		writeJsonPseudoTags(fp);
		return;
	}
	char pat[4096];
	if (opt.pseudo_tags & (1u << ptIdx("TAG_FILE_FORMAT"))) {
		fprintf(fp, "!_TAG_FILE_FORMAT\t%d\t/extended format; --format=1 will not append ;\" to lines/\n", opt.format);
	}
	if (opt.pseudo_tags & (1u << ptIdx("TAG_FILE_SORTED"))) {
		const char *v = opt.sort == 0 ? "0" : (opt.sort == 1 ? "1" : "2");
		fprintf(fp, "!_TAG_FILE_SORTED\t%s\t/0=unsorted, 1=sorted, 2=foldcase/\n", v);
	}
	if (opt.pseudo_tags & (1u << ptIdx("TAG_PROGRAM_AUTHOR")))
		fprintf(fp, "!_TAG_PROGRAM_AUTHOR\t%s\t//\n", PROGRAM_AUTHOR);
	if (opt.pseudo_tags & (1u << ptIdx("TAG_PROGRAM_NAME")))
		fprintf(fp, "!_TAG_PROGRAM_NAME\t%s\t/Derived from Exuberant Ctags/\n", PROGRAM_NAME);
	if (opt.pseudo_tags & (1u << ptIdx("TAG_PROGRAM_URL")))
		fprintf(fp, "!_TAG_PROGRAM_URL\t%s\t/official site/\n", PROGRAM_URL);
	if (opt.pseudo_tags & (1u << ptIdx("TAG_PROGRAM_VERSION")))
		fprintf(fp, "!_TAG_PROGRAM_VERSION\t%s\t/%s/\n", PROGRAM_VERSION, PROGRAM_COMMIT);
	/* field descriptions */
	for (int i = 0; i < gNFields; i++) {
		if (!(opt.fields & (1u << i))) continue;
		if (!gFields[i].name) continue;
		if (!(opt.pseudo_tags & (1u << ptIdx("TAG_FIELD_DESCRIPTION")))) break;
		char d[4096];
		escapeSlash(d, gFields[i].desc);
		fprintf(fp, "!_TAG_FIELD_DESCRIPTION\t%s\t/%s/\n", gFields[i].name, d);
	}
	/* extras descriptions */
	for (int i = 0; i < gNExtras; i++) {
		if (!(opt.extras & (1u << i))) continue;
		if (!(opt.pseudo_tags & (1u << ptIdx("TAG_EXTRA_DESCRIPTION")))) break;
		char d[4096];
		escapeSlash(d, gExtras[i].desc);
		fprintf(fp, "!_TAG_EXTRA_DESCRIPTION\t%s\t/%s/\n", gExtras[i].name, d);
	}
	if (opt.pseudo_tags & (1u << ptIdx("TAG_OUTPUT_MODE"))) {
		const char *m = "u-ctags";
		if (opt.etags_mode) m = "e-ctags";
		else if (opt.output_format >= 0) m = gOutFormats[opt.output_format].name;
		fprintf(fp, "!_TAG_OUTPUT_MODE\t%s\t/u-ctags or e-ctags/\n", m);
	}
	if (opt.pseudo_tags & (1u << ptIdx("TAG_OUTPUT_FILESEP")))
		fprintf(fp, "!_TAG_OUTPUT_FILESEP\tslash\t/slash or backslash/\n");
	if (opt.pseudo_tags & (1u << ptIdx("TAG_PATTERN_LENGTH_LIMIT")))
		fprintf(fp, "!_TAG_PATTERN_LENGTH_LIMIT\t%d\t/0 for no limit/\n", opt.pattern_length_limit);
	if (opt.pseudo_tags & (1u << ptIdx("TAG_PROC_CWD")))
		fprintf(fp, "!_TAG_PROC_CWD\t%s\t//\n", progCwd);
	if (opt.pseudo_tags & (1u << ptIdx("TAG_OUTPUT_EXCMD"))) {
		const char *v = opt.excmd == 0 ? "number" : (opt.excmd == 1 ? "pattern" :
			      (opt.excmd == 2 ? "mixed" : "combine"));
		fprintf(fp, "!_TAG_OUTPUT_EXCMD\t%s\t/number, pattern, mixed, or combineV2/\n", v);
	}
	if (opt.pseudo_tags & (1u << ptIdx("TAG_OUTPUT_VERSION")))
		fprintf(fp, "!_TAG_OUTPUT_VERSION\t%s\t/current.age/\n", OUTPUT_VERSION);
}

void escapeSlash(char *out, const char *in) {
	while (*in) {
		if (*in == '/') { *out++ = '\\'; *out++ = '/'; }
		else *out++ = *in;
		in++;
	}
	*out = 0;
}

int ptIdx(const char *name) {
	for (int i = 0; i < gNPseudoTags; i++)
		if (strcmp(gPseudoTags[i].name, name) == 0) return i;
	return -1;
}
