/* ---------------- messages ---------------- */
void verboseMsg(const char *fmt, ...) {
	if (!opt.verbose) return;
	va_list ap;
	va_start(ap, fmt);
	vfprintf(stderr, fmt, ap);
	va_end(ap);
	fputc('\n', stderr);
}
void noticeMsg(const char *fmt, ...) {
	if (opt.quiet) return;
	va_list ap;
	va_start(ap, fmt);
	vfprintf(stderr, fmt, ap);
	va_end(ap);
	fputc('\n', stderr);
