void warningMsg(const char *fmt, ...) {
	va_list ap;
	va_start(ap, fmt);
	vfprintf(stderr, fmt, ap);
	va_end(ap);
	fputc('\n', stderr);
}

void escapeSlash(char *out, const char *in) {
	while (*in) {
		if (*in == '/') { *out++ = '\\'; *out++ = '/'; }
		else *out++ = *in;
		in++;
	}
	*out = 0;
}

int ptIdx(const char *name) {
