	fputs(helpTextData, stdout);
}

/* ---------------- language detection ---------------- */
static const char *fileExtension(const char *name) {
	const char *b = strrchr(name, '/');
	const char *base = b ? b + 1 : name;
	const char *d = strrchr(base, '.');
	if (!d || d == base || d[1] == 0) return NULL;
	return d + 1;
}

static int isExecutable(const char *name) {
	struct stat st;
	if (stat(name, &st) != 0) return 0;
	return (st.st_mode & S_IXUSR) != 0;
}

typedef struct { Parser *p; char type; char info[512]; } Cand;
static Cand cands[256];
static int ncands;

static void collectCandidates(const char *name) {
	ncands = 0;
	const char *ext = fileExtension(name);
	for (int i = 0; i < gNParsers; i++) {
		Parser *p = gParsers[i];
		if (p->hidden || !p->langEnabled) continue;
		for (int j = 0; j < p->nmaps; j++) {
			Map *m = &p->maps[j];
			int hit = 0;
			if (m->type == 'e') hit = (ext && strcmp(m->pat, ext) == 0);
			else if (m->type == 'p') hit = (fnmatch(m->pat, name, FNM_PATHNAME) == 0);
			if (!hit) continue;
			if (m->type == 'e') snprintf(cands[ncands].info, sizeof(cands[ncands].info),
						     "extension: \"%s\"", ext);
			else snprintf(cands[ncands].info, sizeof(cands[ncands].info),
				      "pattern: \"%s\"", m->pat);
			cands[ncands].p = p;
			cands[ncands].type = m->type;
			ncands++;
			break;
		}
	}
	const char *b = strrchr(name, '/');
	b = b ? b + 1 : name;
	for (int i = 0; i < gNParsers; i++) {
		Parser *p = gParsers[i];
		if (p->hidden || !p->langEnabled) continue;
		for (int j = 0; j < p->naliases; j++) {
			if (fnmatch(p->aliases[j].pat, b, FNM_PATHNAME) == 0) {
				snprintf(cands[ncands].info, sizeof(cands[ncands].info),
					 "alias: \"%s\"", p->aliases[j].pat);
				cands[ncands].p = p;
				cands[ncands].type = 'a';
				ncands++;
				break;
			}
		}
	}
}

static Parser *guessFromShebang(const char *name) {
	FILE *fp = fopen(name, "rb");
	if (!fp) return NULL;
	char buf[1024];
	if (!fgets(buf, sizeof(buf), fp)) { fclose(fp); return NULL; }
	fclose(fp);
	if (strncmp(buf, "#!", 2) != 0) return NULL;
	char *p = buf + 2;
	while (*p == ' ' || *p == '\t') p++;
	char tmp[1024];
	strncpy(tmp, p, sizeof(tmp) - 1);
	tmp[sizeof(tmp) - 1] = 0;
	char *nl = strchr(tmp, '\n');
	if (nl) *nl = 0;
	char words[8][256];
	int nw = 0;
	char *save = NULL;
	for (char *tok = strtok_r(tmp, " \t", &save); tok && nw < 8; tok = strtok_r(NULL, " \t", &save)) {
		strncpy(words[nw], tok, 255); words[nw][255] = 0; nw++;
	}
	const char *prog = NULL;
	if (nw >= 2 && (strcmp(words[0], "/usr/bin/env") == 0 || strchr(words[0], '/') == NULL))
		prog = words[1];
	else if (nw >= 1) { const char *sl = strrchr(words[0], '/'); prog = sl ? sl + 1 : words[0]; }
	if (!prog) return NULL;
	for (int i = 0; i < gNParsers; i++) {
		Parser *q = gParsers[i];
		if (q->hidden || !q->langEnabled) continue;
		if (strcasecmp(q->name, prog) == 0) return q;
		for (int j = 0; j < q->naliases; j++) {
			const char *ap = q->aliases[j].pat;
			if (strchr(ap, '*') || strchr(ap, '?')) {
				if (fnmatch(ap, prog, 0) == 0) return q;
			} else if (strcasecmp(ap, prog) == 0) return q;
		}
	}
	return NULL;
}

Parser *guessLanguage(const char *name) {
	if (opt.language_force) return findParser(opt.language_force);
	collectCandidates(name);
	if (ncands == 0) {
		if (opt.guess_language_eagerly || isExecutable(name)) return guessFromShebang(name);
		return NULL;
	}
	if (opt.guess_language_eagerly || isExecutable(name)) {
		Parser *q = guessFromShebang(name);
		if (q) {
			for (int i = 0; i < ncands; i++)
				if (cands[i].p == q) return q;
		}
	}
	if (ncands > 1) {
		for (int i = 0; i < ncands; i++) {
			if (strcmp(cands[i].p->name, "XML") != 0) continue;
			FILE *fp = fopen(name, "rb");
			if (!fp) break;
			char b[128];
			size_t n = fread(b, 1, sizeof(b) - 1, fp);
			fclose(fp);
			b[n] = 0;
			const char *s = b;
			while (*s == ' ' || *s == '\t' || *s == '\n' || *s == '\r') s++;
			if (strncmp(s, "<?xml", 5) == 0) return cands[i].p;
		}
	}
	return cands[0].p;
}

void guessAndPrintLanguage(const char *name) {
	Parser *p = guessLanguage(name);
	printf("%s: %s\n", name, p ? p->name : "NONE");
}

/* ---------------- input collection ---------------- */
typedef struct FileNode {
	char *name;
	struct FileNode *next;
} FileNode;
static FileNode *fileHead, *fileTail;
int nInputFiles, nSourceFiles, nSourceLines;
static char *userExcludes[512];
static int nUserExcludes;
static char *userExcepts[512];
static int nUserExcepts;

void addInputFile(const char *name) {
	FileNode *n = malloc(sizeof(FileNode));
	n->name = strdup(name);
	n->next = NULL;
	if (fileTail) fileTail->next = n; else fileHead = n;
	fileTail = n;
	nInputFiles++;
}

int isLinkPath(const char *p) {
	struct stat st;
	return lstat(p, &st) == 0 && S_ISLNK(st.st_mode);
}

static int matchesExclude(const char *name) {
	for (int i = 0; i < nUserExcepts; i++)
		if (fnmatch(userExcepts[i], name, FNM_PATHNAME) == 0) return 0;
	for (int i = 0; i < nUserExcludes; i++)
		if (fnmatch(userExcludes[i], name, FNM_PATHNAME) == 0) return 1;
	for (int i = 0; i < gNExcludes; i++)
		if (fnmatch(gExcludes[i], name, FNM_PATHNAME) == 0) return 1;
	return 0;
}

static int isDirP(const char *p) {
	struct stat st;
	if (stat(p, &st) != 0) return 0;
	return S_ISDIR(st.st_mode);
}

static void scanDir(const char *dir, int depth) {
	DIR *d = opendir(dir);
	if (!d) return;
	struct dirent *e;
	while ((e = readdir(d)) != NULL) {
		if (strcmp(e->d_name, ".") == 0 || strcmp(e->d_name, "..") == 0) continue;
		if (matchesExclude(e->d_name)) continue;
		char buf[8192];
		snprintf(buf, sizeof(buf), "%s/%s", dir, e->d_name);
		if (isDirP(buf)) {
			if (opt.maxdepth < 0 || depth < opt.maxdepth) scanDir(buf, depth + 1);
		} else if (opt.links || !isLinkPath(buf)) {
			addInputFile(buf);
		}
	}
	closedir(d);
}

static char **cmdFiles;
static int nCmdFiles, cmdFileCap;

static void addCmdFile(const char *name) {
	if (nCmdFiles >= cmdFileCap) {
		cmdFileCap = cmdFileCap ? cmdFileCap * 2 : 64;
		cmdFiles = realloc(cmdFiles, sizeof(char *) * cmdFileCap);
	}
	cmdFiles[nCmdFiles++] = strdup(name);
}

void collectFiles(int argc, char **argv) {
	int i = opt_index_after();
	for (; i < argc; i++) addCmdFile(argv[i]);
	if (opt.listfile) {
		FILE *fp = strcmp(opt.listfile, "-") == 0 ? stdin : fopen(opt.listfile, "r");
		if (fp) {
			char line[8192];
			while (fgets(line, sizeof(line), fp)) {
				size_t l = strlen(line);
				while (l && (line[l - 1] == '\n' || line[l - 1] == '\r')) line[--l] = 0;
				if (line[0]) addCmdFile(line);
			}
			if (fp != stdin) fclose(fp);
		}
	}
	for (int k = 0; k < nCmdFiles; k++) {
		const char *nm = cmdFiles[k];
		if (isDirP(nm)) {
			if (opt.recurse) scanDir(nm, 1);
		} else addInputFile(nm);
	}
}

void setUserExclude(const char *pat) { userExcludes[nUserExcludes++] = strdup(pat); }
void setUserExcept(const char *pat) { userExcepts[nUserExcepts++] = strdup(pat); }

/* ---------------- pseudo tags ---------------- */
static const char *progCwd;

static void jsonPseudoTag(FILE *fp, const char *name, const char *value,
			  const char *pattern, const char *parserName, const char *kindName) {
	char ne[256], ve[4096], pe[8192], pne[128], kne[128];
	jsonEscapeStr(ne, name, sizeof(ne));
	jsonEscapeStr(ve, value, sizeof(ve));
	jsonEscapeStr(pe, pattern, sizeof(pe));
	fprintf(fp, "{\"_type\": \"ptag\", \"name\": \"%s\"", ne);
	if (parserName) {
		jsonEscapeStr(pne, parserName, sizeof(pne));
		fprintf(fp, ", \"parserName\": \"%s\"", pne);
		if (kindName) {
			jsonEscapeStr(kne, kindName, sizeof(kne));
			fprintf(fp, ", \"kindName\": \"%s\"", kne);
		}
	}
	if (value) fprintf(fp, ", \"path\": \"%s\"", ve);
	fprintf(fp, ", \"pattern\": \"%s\"}\n", pe);
}

void writePseudoTags(FILE *fp, Parser **langs, int nlangs) {
	int jsonMode = (opt.output_format >= 0 &&
			strcmp(gOutFormats[opt.output_format].name, "json") == 0);
	int pt = opt.pseudo_tags;
	if (jsonMode) {
		if (pt & (1u << ptIdx("JSON_OUTPUT_VERSION")))
			jsonPseudoTag(fp, "JSON_OUTPUT_VERSION", JSON_OUTPUT_VERSION, "in development", NULL, NULL);
		if (pt & (1u << ptIdx("TAG_FILE_SORTED")))
			jsonPseudoTag(fp, "TAG_FILE_SORTED",
				      opt.sort == 0 ? "0" : (opt.sort == 1 ? "1" : "2"),
				      "0=unsorted, 1=sorted, 2=foldcase", NULL, NULL);
		if (pt & (1u << ptIdx("TAG_PROGRAM_AUTHOR")))
			jsonPseudoTag(fp, "TAG_PROGRAM_AUTHOR", PROGRAM_AUTHOR, "", NULL, NULL);
		if (pt & (1u << ptIdx("TAG_PROGRAM_NAME")))
			jsonPseudoTag(fp, "TAG_PROGRAM_NAME", PROGRAM_NAME, "Derived from Exuberant Ctags", NULL, NULL);
		if (pt & (1u << ptIdx("TAG_PROGRAM_URL")))
			jsonPseudoTag(fp, "TAG_PROGRAM_URL", PROGRAM_URL, "official site", NULL, NULL);
		if (pt & (1u << ptIdx("TAG_PROGRAM_VERSION")))
			jsonPseudoTag(fp, "TAG_PROGRAM_VERSION", PROGRAM_VERSION, PROGRAM_COMMIT, NULL, NULL);
		if (pt & (1u << ptIdx("TAG_FIELD_DESCRIPTION"))) {
			for (int i = 0; i < gNFields; i++) {
				if (!(opt.fields & (1u << i))) continue;
				if (!gFields[i].name) continue;
				jsonPseudoTag(fp, "TAG_FIELD_DESCRIPTION", gFields[i].name, gFields[i].desc, NULL, NULL);
			}
		}
		if (pt & (1u << ptIdx("TAG_EXTRA_DESCRIPTION"))) {
			for (int i = 0; i < gNExtras; i++) {
				if (!(opt.extras & (1u << i))) continue;
				jsonPseudoTag(fp, "TAG_EXTRA_DESCRIPTION", gExtras[i].name, gExtras[i].desc, NULL, NULL);
			}
		}
		if (pt & (1u << ptIdx("TAG_OUTPUT_FILESEP")))
			jsonPseudoTag(fp, "TAG_OUTPUT_FILESEP", "slash", "slash or backslash", NULL, NULL);
		if (pt & (1u << ptIdx("TAG_PATTERN_LENGTH_LIMIT")))
			jsonPseudoTag(fp, "TAG_PATTERN_LENGTH_LIMIT", "96", "0 for no limit", NULL, NULL);
		if (pt & (1u << ptIdx("TAG_PROC_CWD")))
			jsonPseudoTag(fp, "TAG_PROC_CWD", progCwd, "", NULL, NULL);
		if (pt & (1u << ptIdx("TAG_OUTPUT_EXCMD")))
			jsonPseudoTag(fp, "TAG_OUTPUT_EXCMD",
				      opt.excmd == 0 ? "number" : (opt.excmd == 1 ? "pattern" :
				      (opt.excmd == 2 ? "mixed" : "combine")),
				      "number, pattern, mixed, or combineV2", NULL, NULL);
		if (pt & (1u << ptIdx("TAG_OUTPUT_VERSION")))
			jsonPseudoTag(fp, "TAG_OUTPUT_VERSION", OUTPUT_VERSION, "current.age", NULL, NULL);
	} else {
		if (pt & (1u << ptIdx("TAG_FILE_FORMAT")))
			fprintf(fp, "!_TAG_FILE_FORMAT\t%d\t/extended format; --format=1 will not append ;\" to lines/\n",
				opt.format);
		if (pt & (1u << ptIdx("TAG_FILE_SORTED")))
			fprintf(fp, "!_TAG_FILE_SORTED\t%c\t/0=unsorted, 1=sorted, 2=foldcase/\n",
				opt.sort == 0 ? '0' : (opt.sort == 1 ? '1' : '2'));
		if (pt & (1u << ptIdx("TAG_PROGRAM_AUTHOR")))
			fprintf(fp, "!_TAG_PROGRAM_AUTHOR\t%s\t//\n", PROGRAM_AUTHOR);
		if (pt & (1u << ptIdx("TAG_PROGRAM_NAME")))
			fprintf(fp, "!_TAG_PROGRAM_NAME\t%s\t/Derived from Exuberant Ctags/\n", PROGRAM_NAME);
		if (pt & (1u << ptIdx("TAG_PROGRAM_URL")))
			fprintf(fp, "!_TAG_PROGRAM_URL\t%s\t/official site/\n", PROGRAM_URL);
		if (pt & (1u << ptIdx("TAG_PROGRAM_VERSION")))
			fprintf(fp, "!_TAG_PROGRAM_VERSION\t%s\t/%s/\n", PROGRAM_VERSION, PROGRAM_COMMIT);
		if (pt & (1u << ptIdx("TAG_FIELD_DESCRIPTION"))) {
			for (int i = 0; i < gNFields; i++) {
				if (!(opt.fields & (1u << i))) continue;
				if (!gFields[i].name) continue;
				char d[4096];
				escapeSlash(d, gFields[i].desc);
				fprintf(fp, "!_TAG_FIELD_DESCRIPTION\t%s\t/%s/\n", gFields[i].name, d);
			}
		}
		if (pt & (1u << ptIdx("TAG_EXTRA_DESCRIPTION"))) {
			for (int i = 0; i < gNExtras; i++) {
				if (!(opt.extras & (1u << i))) continue;
				char d[4096];
				escapeSlash(d, gExtras[i].desc);
				fprintf(fp, "!_TAG_EXTRA_DESCRIPTION\t%s\t/%s/\n", gExtras[i].name, d);
			}
		}
		if (pt & (1u << ptIdx("TAG_OUTPUT_MODE"))) {
			const char *m = "u-ctags";
			if (opt.etags_mode) m = "e-ctags";
			else if (opt.output_format >= 0) m = gOutFormats[opt.output_format].name;
			fprintf(fp, "!_TAG_OUTPUT_MODE\t%s\t/u-ctags or e-ctags/\n", m);
		}
		if (pt & (1u << ptIdx("TAG_OUTPUT_FILESEP")))
			fprintf(fp, "!_TAG_OUTPUT_FILESEP\tslash\t/slash or backslash/\n");
		if (pt & (1u << ptIdx("TAG_PATTERN_LENGTH_LIMIT")))
			fprintf(fp, "!_TAG_PATTERN_LENGTH_LIMIT\t%d\t/0 for no limit/\n", opt.pattern_length_limit);
		if (pt & (1u << ptIdx("TAG_PROC_CWD")))
			fprintf(fp, "!_TAG_PROC_CWD\t%s\t//\n", progCwd);
		if (pt & (1u << ptIdx("TAG_OUTPUT_EXCMD")))
			fprintf(fp, "!_TAG_OUTPUT_EXCMD\t%s\t/number, pattern, mixed, or combineV2/\n",
				opt.excmd == 0 ? "number" : (opt.excmd == 1 ? "pattern" :
				(opt.excmd == 2 ? "mixed" : "combine")));
		if (pt & (1u << ptIdx("TAG_OUTPUT_VERSION")))
			fprintf(fp, "!_TAG_OUTPUT_VERSION\t%s\t/current.age/\n", OUTPUT_VERSION);
	}
	/* per language */
	for (int li = 0; li < nlangs; li++) {
		Parser *p = langs[li];
		if (jsonMode) {
			if (pt & (1u << ptIdx("TAG_KIND_DESCRIPTION")))
				for (int j = 0; j < p->nkinds; j++) {
					if (!p->kinds[j].enabled) continue;
					char kv[512];
					snprintf(kv, sizeof(kv), "%c,%s", p->kinds[j].letter, p->kinds[j].name);
					jsonPseudoTag(fp, "TAG_KIND_DESCRIPTION", kv, p->kinds[j].desc, p->name, NULL);
				}
			if (pt & (1u << ptIdx("TAG_FIELD_DESCRIPTION")))
				for (int j = 0; j < p->nfields; j++) {
					if (!(langFieldEnabled(p, j))) continue;
					jsonPseudoTag(fp, "TAG_FIELD_DESCRIPTION", p->fields[j].name,
						      p->fields[j].desc, p->name, NULL);
				}
			if (pt & (1u << ptIdx("TAG_ROLE_DESCRIPTION")))
				for (int j = 0; j < p->nkinds; j++) {
					Kind *k = &p->kinds[j];
					for (int r = 0; r < p->nroles; r++) {
						Role *ro = &p->roles[r];
						if (ro->kind != k) continue;
						if (!roleEnabled(ro)) continue;
						jsonPseudoTag(fp, "TAG_ROLE_DESCRIPTION", ro->name, ro->desc, p->name, k->name);
					}
				}
			if (pt & (1u << ptIdx("TAG_PARSER_VERSION")))
				jsonPseudoTag(fp, "TAG_PARSER_VERSION", p->ver, "current.age", p->name, NULL);
		} else {
			if (pt & (1u << ptIdx("TAG_KIND_DESCRIPTION")))
				for (int j = 0; j < p->nkinds; j++) {
					if (!p->kinds[j].enabled) continue;
					char d[4096];
					escapeSlash(d, p->kinds[j].desc);
					fprintf(fp, "!_TAG_KIND_DESCRIPTION!%s\t%c,%s\t/%s/\n",
						p->name, p->kinds[j].letter, p->kinds[j].name, d);
				}
			if (pt & (1u << ptIdx("TAG_FIELD_DESCRIPTION")))
				for (int j = 0; j < p->nfields; j++) {
					if (!(langFieldEnabled(p, j))) continue;
					char d[4096];
					escapeSlash(d, p->fields[j].desc);
					fprintf(fp, "!_TAG_FIELD_DESCRIPTION!%s\t%s\t/%s/\n",
						p->name, p->fields[j].name, d);
				}
			if (pt & (1u << ptIdx("TAG_ROLE_DESCRIPTION")))
				for (int j = 0; j < p->nkinds; j++) {
					Kind *k = &p->kinds[j];
					for (int r = 0; r < p->nroles; r++) {
						Role *ro = &p->roles[r];
						if (ro->kind != k) continue;
						if (!roleEnabled(ro)) continue;
						char d[4096];
						escapeSlash(d, ro->desc);
						fprintf(fp, "!_TAG_ROLE_DESCRIPTION!%s!%s\t%s\t/%s/\n",
							p->name, k->name, ro->name, d);
					}
				}
			if (pt & (1u << ptIdx("TAG_PARSER_VERSION")))
				fprintf(fp, "!_TAG_PARSER_VERSION!%s\t%s\t/current.age/\n", p->name, p->ver);
		}
	}
	/* language specific extras */
	for (int li = 0; li < nlangs; li++) {
		Parser *p = langs[li];
		if (!(pt & (1u << ptIdx("TAG_EXTRA_DESCRIPTION")))) break;
		for (int j = 0; j < p->nextras; j++) {
			if (!(langExtraEnabled(p, j))) continue;
			char d[4096];
			escapeSlash(d, p->extras[j].desc);
			if (jsonMode)
				jsonPseudoTag(fp, "TAG_EXTRA_DESCRIPTION", p->extras[j].name, p->extras[j].desc, p->name, NULL);
			else
				fprintf(fp, "!_TAG_EXTRA_DESCRIPTION!%s\t%s\t/%s/\n", p->name, p->extras[j].name, d);
		}
	}
}

void setCwd(const char *cwd) { progCwd = cwd; }
