/* ---------------- option parsing ---------------- */
static void errExit(const char *fmt, ...) {
	va_list ap;
	va_start(ap, fmt);
	char buf[2048];
	vsnprintf(buf, sizeof(buf), fmt, ap);
	va_end(ap);
	fprintf(stderr, "executable: %s\n", buf);
	exit(1);
}

static int parseYesNo(const char *v, int defval) {
	if (!v || !*v) return defval;
	if (strcmp(v, "yes") == 0 || strcmp(v, "true") == 0 || strcmp(v, "on") == 0 ||
	    strcmp(v, "1") == 0) return 1;
	if (strcmp(v, "no") == 0 || strcmp(v, "false") == 0 || strcmp(v, "off") == 0 ||
	    strcmp(v, "0") == 0) return 0;
	return -1;
}

static void setOutputFormatDefault(void) {
	if (opt.output_format < 0) {
		if (opt.etags_mode) {
			for (int i = 0; i < gNOutFormats; i++)
				if (strcmp(gOutFormats[i].name, "etags") == 0) opt.output_format = i;
		} else if (opt.xref_mode) {
			for (int i = 0; i < gNOutFormats; i++)
				if (strcmp(gOutFormats[i].name, "xref") == 0) opt.output_format = i;
		} else {
			for (int i = 0; i < gNOutFormats; i++)
				if (gOutFormats[i].def) opt.output_format = i;
		}
	}
}

static int argi;
static char **gargv;

/* returns 1 if the argument was consumed as an option */
static int handleArg(char *arg) {
	if (arg[0] != '-' || arg[1] == 0) return 0;
	if (arg[1] == '-') {
		char namebuf[512];
		const char *value = NULL;
		const char *eq = strchr(arg + 2, '=');
		if (eq) {
			size_t l = (size_t)(eq - (arg + 2));
			if (l >= sizeof(namebuf)) l = sizeof(namebuf) - 1;
			memcpy(namebuf, arg + 2, l);
			namebuf[l] = 0;
			value = eq + 1;
		} else strcpy(namebuf, arg + 2);
		int consumed = processLongOption(namebuf, value);
		if (consumed < 0) errExit("Unknown option: %s", arg);
		return consumed;
	}
	/* short options, possibly several */
	int k = 1;
	while (arg[k]) {
		char c = arg[k];
		const char *value = NULL;
		int cons = 0;
		if (arg[k + 1]) { value = arg + k + 1; cons = 1; }
		int r = processShortOption(c, value, &cons);
		if (r < 0) errExit("Unknown option: -%c", c);
		k++;
		if (cons) break;
	}
	return 1;
}

static void parseCommandLine(int argc, char **argv) {
	argi = 1;
	gargv = argv;
	while (argi < argc) {
		char *a = argv[argi];
		if (handleArg(a)) {
			/* options that take a separate argument */
			if (opt_take_next_arg()) argi++;
			argi++;
			continue;
		}
		break;
	}
}

int main(int argc, char **argv) {
	langdb_load();
	langEnabledInit();
	setDefaults();
	/* cwd */
	char cwdbuf[8192];
	if (getcwd(cwdbuf, sizeof(cwdbuf))) {
		size_t l = strlen(cwdbuf);
		if (l && cwdbuf[l - 1] != '/') { cwdbuf[l] = '/'; cwdbuf[l + 1] = 0; }
		setCwd(cwdbuf);
	} else setCwd("./");
	parseCommandLine(argc, argv);
	setOutputFormatDefault();
	/* remaining args are files */
	collectFiles(argc, argv);
	if (nInputFiles == 0 && !opt.filter) {
		fprintf(stderr, "executable: No files specified. Try \"executable --help\".\n");
		return 1;
	}
	/* output */
	outIsStdout = 0;
	if (opt.tagfile && strcmp(opt.tagfile, "-") == 0) {
		outfp = stdout;
		outIsStdout = 1;
	} else if (opt.xref_mode || opt.print_language) {
		outfp = stdout;
		outIsStdout = 1;
	} else {
		const char *nm = opt.tagfile;
		if (!nm) nm = opt.etags_mode ? "TAGS" : "tags";
		snprintf(outPath, sizeof(outPath), "%s", nm);
		if (opt.append) outfp = fopen(nm, "a");
		else outfp = fopen(nm, "w");
		if (!outfp) {
			fprintf(stderr, "executable: cannot open tag file \"%s\"\n", nm);
			return 1;
		}
		if (strcmp(nm, "tags") != 0 && strcmp(nm, "TAGS") != 0 && !outIsStdout) {
			/* u-ctags refuses to overwrite files that do not look like tag files */
			if (!opt.append) {
				FILE *chk = fopen(nm, "r");
				if (chk) {
					char b[4096];
					size_t n = fread(b, 1, sizeof(b) - 1, chk);
					fclose(chk);
					b[n] = 0;
					int ok = 0;
					if (strstr(b, "!_TAG_") || strstr(b, "\177") || strstr(b, "\f\n")) ok = 1;
					if (!ok) {
						fprintf(stderr, "executable: \"%s\" doesn't look like a tag file; I refuse to overwrite it.\n", nm);
						return 1;
					}
				}
			}
		}
		outIsStdout = 0;
	}
	/* parse */
	if (opt.print_language) {
		for (FileNode *f = fileHead; f; f = f->next)
			guessAndPrintLanguage(f->name);
		return 0;
	}
	for (FileNode *f = fileHead; f; f = f->next)
		parseFile(f->name);
	finishOutput();
	return 0;
}
