/* returns 1 if the argument was consumed as an option */
static int handleArg(char *arg) {
	if (arg[0] != '-' || arg[1] == 0) return 0;
	if (arg[1] == '-') {
		char namebuf[512];
		const char *value = NULL;
		const char *eq = strchr(arg + 2, '=');
		if (eq) {
			size_t l = (size_t)(eq - (arg + 2));
			if (l >= sizeof(namebuf)) l = sizeof(namebuf) - 1;
			memcpy(namebuf, arg + 2, l);
			namebuf[l] = 0;
			value = eq + 1;
		} else strcpy(namebuf, arg + 2);
		int consumed = processLongOption(namebuf, value);
		if (consumed < 0) errExit("Unknown option: %s", arg);
		return consumed;
	}
	/* short options, possibly several */
	int k = 1;
	while (arg[k]) {
		char c = arg[k];
		const char *value = NULL;
		int cons = 0;
		if (arg[k + 1]) { value = arg + k + 1; cons = 1; }
		int r = processShortOption(c, value, &cons);
		if (r < 0) errExit("Unknown option: -%c", c);
		k++;
		if (cons) break;
	}
	return 1;
}

static void parseCommandLine(int argc, char **argv) {
	argi = 1;
	gargv = argv;
	while (argi < argc) {
