void jsonEscapeStr(char *out, const char *in, size_t n) {
	size_t o = 0;
	while (*in && o + 8 < n) {
		switch (*in) {
		case '"': out[o++] = '\\'; out[o++] = '"'; break;
		case '\\': out[o++] = '\\'; out[o++] = '\\'; break;
		case '\t': out[o++] = '\\'; out[o++] = 't'; break;
		case '\n': out[o++] = '\\'; out[o++] = 'n'; break;
		case '\r': out[o++] = '\\'; out[o++] = 'r'; break;
		default: out[o++] = *in;
		}
		in++;
	}
	out[o] = 0;
}
