	return 1;
}

static void closeInput(void) {
	free(src.buf);
	free(src.loff);
	src.buf = NULL;
}

/* line number of a position */
static int lineOf(size_t p) {
	int lo = 0, hi = src.nloff - 1;
	while (lo < hi) {
		int mid = (lo + hi + 1) / 2;
		if ((size_t)src.loff[mid] <= p) lo = mid;
		else hi = mid - 1;
	}
	return lo + 1;
}

/* ---------------- lexer ---------------- */
#define T_EOF 0
#define T_ID 1
#define T_NUM 2
#define T_STR 3
#define T_CHR 4
#define T_PUNCT 5

static char tokText[8192];
static int tokLine;
static int tokIsEOL;

static void skipWs(void) {
	while (src.pos < src.len) {
		char c = src.buf[src.pos];
		if (c == ' ' || c == '\t' || c == '\r' || c == '\n' || c == '\v' || c == '\f') {
			src.pos++;
			continue;
		}
		if (c == '/' && src.pos + 1 < src.len && src.buf[src.pos + 1] == '/') {
			while (src.pos < src.len && src.buf[src.pos] != '\n') src.pos++;
			continue;
		}
		if (c == '/' && src.pos + 1 < src.len && src.buf[src.pos + 1] == '*') {
			src.pos += 2;
			while (src.pos + 1 < src.len &&
			       !(src.buf[src.pos] == '*' && src.buf[src.pos + 1] == '/')) {
				if (src.buf[src.pos] == '\n') src.line++;
				src.pos++;
			}
			if (src.pos + 1 < src.len) src.pos += 2;
			continue;
		}
		if (c == '\\' && src.pos + 1 < src.len && src.buf[src.pos + 1] == '\n') {
			src.pos += 2;
			src.line++;
			continue;
		}
		break;
	}
}

/* read the next token; returns type; tokText holds the text */
static int nextTok(void) {
	skipWs();
	if (src.pos >= src.len) { tokText[0] = 0; tokLine = src.line; return T_EOF; }
	tokLine = lineOf(src.pos);
	char c = src.buf[src.pos];
	if (isalpha((unsigned char)c) || c == '_' || c == '$') {
		int n = 0;
		while (src.pos < src.len) {
			char d = src.buf[src.pos];
			if (isalnum((unsigned char)d) || d == '_' || d == '$') {
				if (n < (int)sizeof(tokText) - 1) tokText[n++] = d;
				src.pos++;
			} else break;
		}
		tokText[n] = 0;
		return T_ID;
	}
	if (isdigit((unsigned char)c)) {
		int n = 0;
		while (src.pos < src.len) {
			char d = src.buf[src.pos];
			if (isalnum((unsigned char)d) || d == '.' || d == '_') {
				if (n < (int)sizeof(tokText) - 1) tokText[n++] = d;
				src.pos++;
			} else break;
		}
		tokText[n] = 0;
		return T_NUM;
	}
	if (c == '"' || c == '\'') {
		char q = c;
		int n = 0;
		tokText[n++] = q;
		src.pos++;
		while (src.pos < src.len) {
			char d = src.buf[src.pos];
			if (d == '\\' && src.pos + 1 < src.len) {
				tokText[n++] = d;
				src.pos++;
				if (n < (int)sizeof(tokText) - 1) tokText[n++] = src.buf[src.pos];
				src.pos++;
				continue;
			}
			if (d == q) { tokText[n++] = d; src.pos++; break; }
			if (d == '\n') { tokLine++; break; }
			if (n < (int)sizeof(tokText) - 1) tokText[n++] = d;
			src.pos++;
		}
		tokText[n] = 0;
		return q == '"' ? T_STR : T_CHR;
	}
	/* punctuation */
	int n = 0;
	tokText[n++] = c;
	src.pos++;
	if (strchr("+-*/%&|^!<>=?:.,;(){}[]#", c)) {
		char cands3[8];
		cands3[0] = c;
		while (src.pos < src.len && n < 3) {
			char d = src.buf[src.pos];
			/* only combine operator characters */
			if ((strchr("<>=+-*/%&|^!?:", c) && strchr("<>=+-*/%&|^!:", d)) ||
			    (c == '#' && d == '#')) {
				cands3[n] = d;
				/* verify the combination is a real operator */
				char tmp[4];
				memcpy(tmp, cands3, n + 1);
				tmp[n + 1] = 0;
				if (!isOp(tmp)) break;
				tokText[n++] = d;
				src.pos++;
			} else break;
		}
	}
	tokText[n] = 0;
	return T_PUNCT;
}
