static void strncat2(char *dst, const char *src, size_t n) {
	size_t l = strlen(dst);
	size_t i = 0;
	while (src[i] && l + i < n - 1) { dst[l + i] = src[i]; i++; }
	dst[l + i] = 0;
}
#define strncat strncat2

static const char *scopeKindStr(char k) {
	switch (k) {
	case 's': return "struct";
	case 'u': return "union";
	case 'g': return "enum";
	case 'c': return "class";
	case 'n': return "namespace";
	case 'i': return "interface";
	}
	return "";
}

/* ---------------- preprocessor ---------------- */
static void handleDirective(void) {
	/* tokText starts with '#' */
	int startLine = tokLine;
	int savepos = (int)src.pos;
	/* read the directive name */
	int t = nextTok();
	if (t != T_ID) {
		/* skip to end of line */
		while (src.pos < src.len && src.buf[src.pos] != '\n') src.pos++;
		src.line++;
		return;
	}
	char dir[64];
	strcpy(dir, tokText);
	if (strcmp(dir, "define") == 0) {
		int t2 = nextTok();
		if (t2 == T_ID) {
			char name[1024];
			strcpy(name, tokText);
			int defLine = tokLine;
			/* pattern: line up to and including the char after the name */
			const char *ls = src.buf + src.loff[defLine - 1];
			const char *le = memchr(ls, '\n', src.len - (size_t)(ls - src.buf));
			size_t llen = le ? (size_t)(le - ls) : strlen(ls);
			if (llen >= sizeof(tokbuf_tmp)) llen = sizeof(tokbuf_tmp) - 1;
			memcpy(tokbuf_tmp, ls, llen);
			tokbuf_tmp[llen] = 0;
			/* find the name in the line and cut after it */
			char *hit = strstr(tokbuf_tmp, name);
			char pat[8192];
			if (hit) {
				size_t cut = (size_t)(hit - tokbuf_tmp) + strlen(name);
				if (cut < llen) cut++;
				else cut = llen;
				size_t l2 = cut;
				if (l2 >= sizeof(pat) - 4) l2 = sizeof(pat) - 5;
				memcpy(pat, tokbuf_tmp, l2);
				pat[l2] = 0;
			} else strcpy(pat, tokbuf_tmp);
			/* skip the rest of the directive */
			while (src.pos < src.len && src.buf[src.pos] != '\n') src.pos++;
			src.line++;
			if (kindIsEnabled(kindByLetter(curParser, 'd')))
