{"command": "cd /workspace && cat > src/parse.c <<'CEOF'
#include <stdarg.h>
#include "ctags.h"

/* ================= source buffer ================= */
typedef struct {
	char *buf;
	size_t len;
	size_t pos;
	int line;
	long *loff;
	int nloff;
	char *falseCond;		/* per line: 1 if inside a skipped conditional */
} Src;
static Src src;
Parser *curParser;
static unsigned long anonHash;
static int anonCount;
static char tokText[8192];
static int tokLine;

void anonName(char *out, size_t n) {
	anonCount++;
	snprintf(out, n, "__anon%08lx%04lx", anonHash, (unsigned long)(anonCount * 0x100 + 8));
}

static char *readWhole(const char *name, long *plen, int *pnlines, long **loffs) {
	FILE *fp = fopen(name, "rb");
	if (!fp) return NULL;
	fseek(fp, 0, SEEK_END);
	long sz = ftell(fp);
	fseek(fp, 0, SEEK_SET);
	char *buf = malloc((size_t)sz + 2);
	size_t n = fread(buf, 1, (size_t)sz, fp);
	fclose(fp);
	buf[n] = 0;
	*plen = (long)n;
	int cap = 64, nl = 0;
	long *lo = malloc(sizeof(long) * cap);
	lo[nl++] = 0;
	for (size_t i = 0; i < n; i++)
		if (buf[i] == '\n') {
			if (nl >= cap) { cap *= 2; lo = realloc(lo, sizeof(long) * cap); }
			lo[nl++] = (long)(i + 1);
		}
	*pnlines = nl;
	*loffs = lo;
	return buf;
}

static int openInput(const char *name) {
	long plen;
	int nl;
	long *lo;
	char *b = readWhole(name, &plen, &nl, &lo);
	if (!b) return 0;
	src.buf = b;
	src.len = (size_t)plen;
	src.pos = 0;
	src.line = 1;
	src.loff = lo;
	src.nloff = nl;
	src.falseCond = calloc((size_t)nl + 2, 1);
	unsigned long h = 5381;
	for (const char *s = name; *s; s++) h = (h * 33 + (unsigned char)*s) & 0xffffffffUL;
	anonHash = h;
	anonCount = 0;
	return 1;
}

static void closeInput(void) {
	free(src.buf);
	free(src.loff);
	free(src.falseCond);
	memset(&src, 0, sizeof(src));
}

static int lineOfPos(size_t p) {
	int lo = 0, hi = src.nloff - 1;
	while (lo < hi) {
		int mid = (lo + hi + 1) / 2;
		if ((size_t)src.loff[mid] <= p) lo = mid;
		else hi = mid - 1;
	}
	return lo + 1;
}

/* get the text of line n (1-based) without the trailing newline */
static char *lineText(int n) {
	static char buf[65536];
	if (n < 1 || n > src.nloff) { buf[0] = 0; return buf; }
	const char *s = src.buf + src.loff[n - 1];
	const char *e = memchr(s, '\n', src.len - (size_t)(s - src.buf));
	size_t l = e ? (size_t)(e - s) : strlen(s);
	if (l >= sizeof(buf)) l = sizeof(buf) - 1;
	memcpy(buf, s, l);
	buf[l] = 0;
	return buf;
}

/* ================= preprocessor pass ================= */
static void preprocPass(void) {
	int depth = 0;
	int falsenest[128];
	int top = 0;
	for (int i = 1; i <= src.nloff; i++) {
		char *l = lineText(i);
		char *p = l;
		while (*p == ' ' || *p == '\t') p++;
		if (*p != '#') {
			if (top > 0 && !falsenest[top - 1]) src.falseCond[i] = 0;
			else if (top > 0) src.falseCond[i] = 1;
			continue;
		}
		p++;
		while (*p == ' ' || *p == '\t') p++;
		char dir[32];
		int n = 0;
		while (isalpha((unsigned char)*p) && n < 31) dir[n++] = *p++;
		dir[n] = 0;
		int skipRest = 0;
		if (strcmp(dir, "if") == 0) {
			int v = 1;
			if (strncmp(p, "0", 1) == 0) v = 0;
			if (top < 128) { falsenest[top++] = v ? 0 : 1; }
			skipRest = 1;
		} else if (strcmp(dir, "ifdef") == 0 || strcmp(dir, "ifndef") == 0) {
			if (top < 128) falsenest[top++] = 0;
			skipRest = 1;
		} else if (strcmp(dir, "else") == 0 || strcmp(dir, "elif") == 0) {
			if (top > 0) falsenest[top - 1] = !falsenest[top - 1];
			skipRest = 1;
		} else if (strcmp(dir, "endif") == 0) {
			if (top > 0) top--;
			skipRest = 1;
		} else skipRest = 1;
		if (top > 0) src.falseCond[i] = falsenest[top - 1];
		(void)skipRest;
	}
	/* directives themselves are not skipped */
}

/* ================= lexer ================= */
#define T_EOF 0
#define T_ID 1
#define T_NUM 2
#define T_STR 3
#define T_CHR 4
#define T_PUNCT 5

static const char *gOps[] = {
	"<<=", ">>=", "...", "<=>", "->*", "::", "->", "++", "--", "<<", ">>",
	"<=", ">=", "==", "!=", "&&", "||", "+=", "-=", "*=", "/=", "%=",
	"&=", "|=", "^=", "##", NULL
};

static void skipWs(void) {
	while (src.pos < src.len) {
		char c = src.buf[src.pos];
		if (c == ' ' || c == '\t' || c == '\r' || c == '\n' || c == '\v' || c == '\f') {
			src.pos++;
			if (c == '\n') src.line++;
			continue;
		}
		if (c == '/' && src.pos + 1 < src.len && src.buf[src.pos + 1] == '/') {
			while (src.pos < src.len && src.buf[src.pos] != '\n') src.pos++;
			continue;
		}
		if (c == '/' && src.pos + 1 < src.len && src.buf[src.pos + 1] == '*') {
			src.pos += 2;
			while (src.pos + 1 < src.len &&
			       !(src.buf[src.pos] == '*' && src.buf[src.pos + 1] == '/')) {
				if (src.buf[src.pos] == '\n') src.line++;
				src.pos++;
			}
			if (src.pos + 1 < src.len) src.pos += 2;
			continue;
		}
		if (c == '\\' && src.pos + 1 < src.len && src.buf[src.pos + 1] == '\n') {
			src.pos += 2;
			src.line++;
			continue;
		}
		break;
	}
}

static int nextTok(void) {
	for (;;) {
		skipWs();
		if (src.pos >= src.len) { tokText[0] = 0; tokLine = src.line; return T_EOF; }
		if (src.falseCond && src.falseCond[lineOfPos(src.pos)]) {
			/* skip to the next line */
			while (src.pos < src.len && src.buf[src.pos] != '\n') src.pos++;
			continue;
		}
		break;
