		tmp[n] = d;
		tmp[n + 1] = 0;
		int ok = 0;
		for (int i = 0; gOps[i]; i++)
			if (strcmp(gOps[i], tmp) == 0) { ok = 1; break; }
		if (!ok) break;
		tokText[n++] = d;
		src.pos++;
	}
	tokText[n] = 0;
	return T_PUNCT;
}

