		while (*p == ' ' || *p == '\t') p++;
		if (*p != '#') {
			if (top > 0 && !falsenest[top - 1]) src.falseCond[i] = 0;
			else if (top > 0) src.falseCond[i] = 1;
			continue;
		}
		p++;
		while (*p == ' ' || *p == '\t') p++;
		char dir[32];
		int n = 0;
		while (isalpha((unsigned char)*p) && n < 31) dir[n++] = *p++;
		dir[n] = 0;
		int skipRest = 0;
		if (strcmp(dir, "if") == 0) {
			int v = 1;
			if (strncmp(p, "0", 1) == 0) v = 0;
			if (top < 128) { falsenest[top++] = v ? 0 : 1; }
			skipRest = 1;
		} else if (strcmp(dir, "ifdef") == 0 || strcmp(dir, "ifndef") == 0) {
			if (top < 128) falsenest[top++] = 0;
			skipRest = 1;
		} else if (strcmp(dir, "else") == 0 || strcmp(dir, "elif") == 0) {
			if (top > 0) falsenest[top - 1] = !falsenest[top - 1];
			skipRest = 1;
		} else if (strcmp(dir, "endif") == 0) {
			if (top > 0) top--;
			skipRest = 1;
		} else skipRest = 1;
		if (top > 0) src.falseCond[i] = falsenest[top - 1];
		(void)skipRest;
	}
