	unsigned long h = 5381;
	for (const char *s = name; *s; s++) h = (h * 33 + (unsigned char)*s) & 0xffffffffUL;
	anonHash = h;
	anonCount = 0;
	return 1;
}

static void closeInput(void) {
	free(src.buf);
	free(src.loff);
	free(src.falseCond);
	memset(&src, 0, sizeof(src));
}

static int lineOfPos(size_t p) {
	int lo = 0, hi = src.nloff - 1;
	while (lo < hi) {
		int mid = (lo + hi + 1) / 2;
		if ((size_t)src.loff[mid] <= p) lo = mid;
		else hi = mid - 1;
	}
	return lo + 1;
}

/* get the text of line n (1-based) without the trailing newline */
static char *lineText(int n) {
	static char buf[65536];
	if (n < 1 || n > src.nloff) { buf[0] = 0; return buf; }
	const char *s = src.buf + src.loff[n - 1];
	const char *e = memchr(s, '\n', src.len - (size_t)(s - src.buf));
	size_t l = e ? (size_t)(e - s) : strlen(s);
	if (l >= sizeof(buf)) l = sizeof(buf) - 1;
	memcpy(buf, s, l);
	buf[l] = 0;
	return buf;
}

/* ================= preprocessor pass ================= */
static void preprocPass(void) {
	int depth = 0;
	int falsenest[128];
	int top = 0;
	for (int i = 1; i <= src.nloff; i++) {
		char *l = lineText(i);
		char *p = l;
		while (*p == ' ' || *p == '\t') p++;
		if (*p != '#') {
			if (top > 0 && !falsenest[top - 1]) src.falseCond[i] = 0;
			else if (top > 0) src.falseCond[i] = 1;
			continue;
		}
		p++;
		while (*p == ' ' || *p == '\t') p++;
		char dir[32];
		int n = 0;
		while (isalpha((unsigned char)*p) && n < 31) dir[n++] = *p++;
		dir[n] = 0;
		int skipRest = 0;
		if (strcmp(dir, "if") == 0) {
			int v = 1;
			if (strncmp(p, "0", 1) == 0) v = 0;
			if (top < 128) { falsenest[top++] = v ? 0 : 1; }
			skipRest = 1;
		} else if (strcmp(dir, "ifdef") == 0 || strcmp(dir, "ifndef") == 0) {
			if (top < 128) falsenest[top++] = 0;
			skipRest = 1;
		} else if (strcmp(dir, "else") == 0 || strcmp(dir, "elif") == 0) {
			if (top > 0) falsenest[top - 1] = !falsenest[top - 1];
			skipRest = 1;
		} else if (strcmp(dir, "endif") == 0) {
			if (top > 0) top--;
			skipRest = 1;
		} else skipRest = 1;
		if (top > 0) src.falseCond[i] = falsenest[top - 1];
		(void)skipRest;
	}
	/* directives themselves are not skipped */
}

/* ================= lexer ================= */
#define T_EOF 0
#define T_ID 1
#define T_NUM 2
#define T_STR 3
#define T_CHR 4
#define T_PUNCT 5

static const char *gOps[] = {
	"<<=", ">>=", "...", "<=>", "->*", "::", "->", "++", "--", "<<", ">>",
	"<=", ">=", "==", "!=", "&&", "||", "+=", "-=", "*=", "/=", "%=",
	"&=", "|=", "^=", "##", NULL
};

static void skipWs(void) {
	while (src.pos < src.len) {
		char c = src.buf[src.pos];
		if (c == ' ' || c == '\t' || c == '\r' || c == '\n' || c == '\v' || c == '\f') {
			src.pos++;
			if (c == '\n') src.line++;
			continue;
		}
		if (c == '/' && src.pos + 1 < src.len && src.buf[src.pos + 1] == '/') {
			while (src.pos < src.len && src.buf[src.pos] != '\n') src.pos++;
			continue;
		}
		if (c == '/' && src.pos + 1 < src.len && src.buf[src.pos + 1] == '*') {
			src.pos += 2;
			while (src.pos + 1 < src.len &&
			       !(src.buf[src.pos] == '*' && src.buf[src.pos + 1] == '/')) {
				if (src.buf[src.pos] == '\n') src.line++;
				src.pos++;
			}
			if (src.pos + 1 < src.len) src.pos += 2;
			continue;
		}
		if (c == '\\' && src.pos + 1 < src.len && src.buf[src.pos + 1] == '\n') {
			src.pos += 2;
			src.line++;
			continue;
		}
		break;
	}
}

static int nextTok(void) {
	for (;;) {
		skipWs();
		if (src.pos >= src.len) { tokText[0] = 0; tokLine = src.line; return T_EOF; }
		if (src.falseCond && src.falseCond[lineOfPos(src.pos)]) {
			/* skip to the next line */
			while (src.pos < src.len && src.buf[src.pos] != '\n') src.pos++;
			continue;
		}
		break;
	}
	tokLine = lineOfPos(src.pos);
	char c = src.buf[src.pos];
	if (isalpha((unsigned char)c) || c == '_' || c == '$') {
		int n = 0;
		while (src.pos < src.len) {
			char d = src.buf[src.pos];
			if (isalnum((unsigned char)d) || d == '_' || d == '$') {
				if (n < (int)sizeof(tokText) - 1) tokText[n++] = d;
				src.pos++;
			} else break;
		}
		tokText[n] = 0;
		return T_ID;
	}
	if (isdigit((unsigned char)c)) {
		int n = 0;
		while (src.pos < src.len) {
			char d = src.buf[src.pos];
			if (isalnum((unsigned char)d) || d == '.' || d == '_') {
				if (n < (int)sizeof(tokText) - 1) tokText[n++] = d;
				src.pos++;
			} else break;
		}
		tokText[n] = 0;
		return T_NUM;
	}
	if (c == '"' || c == '\'') {
		char q = c;
		int n = 0;
		tokText[n++] = q;
		src.pos++;
		int l0 = tokLine;
		while (src.pos < src.len) {
			char d = src.buf[src.pos];
			if (d == '\\' && src.pos + 1 < src.len) {
				tokText[n++] = d;
				src.pos++;
				if (n < (int)sizeof(tokText) - 1) tokText[n++] = src.buf[src.pos];
				src.pos++;
				continue;
			}
			if (d == q) { tokText[n++] = d; src.pos++; break; }
			if (d == '\n') { tokLine++; break; }
			if (n < (int)sizeof(tokText) - 1) tokText[n++] = d;
			src.pos++;
		}
		tokText[n] = 0;
		tokLine = l0;
		return q == '"' ? T_STR : T_CHR;
	}
	int n = 0;
	tokText[n++] = c;
	src.pos++;
	for (;;) {
		char tmp[8];
		memcpy(tmp, tokText, (size_t)n);
		tmp[n] = 0;
		int can = 0;
		for (int i = 0; gOps[i]; i++)
			if (strlen(gOps[i]) > (size_t)n && strncmp(gOps[i], tmp, (size_t)n) == 0) { can = 1; break; }
		if (!can || src.pos >= src.len) break;
		char d = src.buf[src.pos];
		tmp[n] = d;
		tmp[n + 1] = 0;
		int ok = 0;
		for (int i = 0; gOps[i]; i++)
			if (strcmp(gOps[i], tmp) == 0) { ok = 1; break; }
		if (!ok) break;
		tokText[n++] = d;
		src.pos++;
	}
	tokText[n] = 0;
	return T_PUNCT;
}

static void skipLine(void) {
	while (src.pos < src.len && src.buf[src.pos] != '\n') src.pos++;
	if (src.pos < src.len) { src.pos++; src.line++; }
}

/* ================= tag helpers ================= */
static const Kind *kindByLetter(Parser *p, char c) {
	for (int i = 0; i < p->nkinds; i++)
		if (p->kinds[i].letter == c) return &p->kinds[i];
	return NULL;
}
static int kindIsEnabled(const Kind *k) { return k && k->enabled; }
static int kindRoleEnabled(const Kind *k, const char *role) {
	Parser *p = curParser;
	for (int i = 0; i < p->nroles; i++) {
		Role *r = &p->roles[i];
		if (r->kind == k && strcmp(r->name, role) == 0)
			return r->enabled && roleEnabledIdx(p, i);
	}
	return 0;
}
static void resetCur(void) {
	cur.name[0] = 0;
	cur.scope[0] = 0;
	cur.typeref[0] = 0;
	cur.signature[0] = 0;
	cur.access[0] = 0;
	cur.impl[0] = 0;
	cur.inherits[0] = 0;
	cur.role[0] = 0;
	cur.langfields[0] = 0;
	cur.pattern[0] = 0;
	cur.patternComplete = 0;
	cur.patternNoPattern = 0;
	cur.endline = 0;
	cur.nth = -1;
	cur.isfile = 0;
	cur.reference = 0;
	cur.qualified = 0;
	cur.inputFile = 0;
	cur.xpath[0] = 0;
	cur.anon = 0;
}
static void setKind(char letter) {
	const Kind *k = kindByLetter(curParser, letter);
	cur.kindLetter = letter;
	cur.kindName = k ? k->name : "";
}
static void mkTag(char letter, const char *name, int line) {
	if (!name || !*name) return;
	if (!kindIsEnabled(kindByLetter(curParser, letter))) return;
	resetCur();
	snprintf(cur.name, sizeof(cur.name), "%s", name);
	setKind(letter);
	cur.line = line;
	cur.patternComplete = 1;
	makeTagEntry();
}
static void mkTagP(char letter, const char *name, int line, const char *pattern) {
	if (!name || !*name) return;
	if (!kindIsEnabled(kindByLetter(curParser, letter))) return;
	resetCur();
	snprintf(cur.name, sizeof(cur.name), "%s", name);
	setKind(letter);
	cur.line = line;
	snprintf(cur.pattern, sizeof(cur.pattern), "%s", pattern);
	makeTagEntry();
}

/* ================= scope stack ================= */
typedef struct { char kind; char name[1024]; int depth; } ScopeEnt;
static ScopeEnt scopeStack[256];
static int nScope;
static void scopePush(char kind, const char *name, int depth) {
	if (nScope >= 256) return;
	scopeStack[nScope].kind = kind;
	snprintf(scopeStack[nScope].name, sizeof(scopeStack[nScope].name), "%s", name);
	scopeStack[nScope].depth = depth;
	nScope++;
}
static void scopePopTo(int depth) {
	while (nScope > 0 && scopeStack[nScope - 1].depth >= depth) nScope--;
}
static void scopeStr(char *out, size_t n) {
	out[0] = 0;
	if (nScope == 0) return;
	const char *ks = "";
	switch (scopeStack[nScope - 1].kind) {
	case 's': ks = "struct"; break;
	case 'u': ks = "union"; break;
	case 'g': ks = "enum"; break;
	case 'c': ks = "class"; break;
	case 'n': ks = "namespace"; break;
	case 'i': ks = "interface"; break;
	}
	snprintf(out, n, "%s:", ks);
	for (int i = 0; i < nScope; i++) {
		if (i) strncat(out, "::", n);
		strncat(out, scopeStack[i].name, n);
	}
}
static void scopeNameStr(char *out, size_t n) {
	out[0] = 0;
	for (int i = 0; i < nScope; i++) {
		if (i) strncat(out, "::", n);
		strncat(out, scopeStack[i].name, n);
	}
}
static void strncat2(char *dst, const char *sr, size_t n) {
	size_t l = strlen(dst);
	size_t i = 0;
	while (sr[i] && l + i < n - 1) { dst[l + i] = sr[i]; i++; }
	dst[l + i] = 0;
}
