		switch (scopeStack[nScope - 1].kind) {
		case 's': ks = "struct"; break;
		case 'u': ks = "union"; break;
		case 'g': ks = "enum"; break;
		case 'c': ks = "class"; break;
		case 'n': ks = "namespace"; break;
		}
		snprintf(out, sizeof(out), "%s:", ks);
		for (int i = 0; i < nScope; i++) {
			if (i) strncat(out, "::", sizeof(out));
			strncat(out, scopeStack[i].name, sizeof(out));
		}
	}
