							if (i) strncat(outer, "::", sizeof(outer));
							strncat(outer, scopeStack[i].name, sizeof(outer));
						}
					}
					resetCur();
					snprintf(cur.name, sizeof(cur.name), "%s", tk[nameIdx]);
					setKind('p');
					cur.line = tkL[nameIdx];
					cur.patternComplete = 1;
					if (outer[0]) snprintf(cur.scope, sizeof(cur.scope), "%s", outer);
					char s2[2048];
					s2[0] = 0;
					for (int i = open + 1; i < close; i++) {
						if (i > open + 1) strncat(s2, " ", sizeof(s2));
						strncat(s2, tk[i], sizeof(s2));
					}
					snprintf(cur.signature, sizeof(cur.signature), "%s", s2);
					makeTagEntry();
				}
				return;
			}
		}
		/* variable declaration(s) */
		{
			int from = 0;
			while (from < ntk && (isStorageWord(tk[from]) || strcmp(tk[from], "struct") == 0 ||
			       strcmp(tk[from], "union") == 0 || strcmp(tk[from], "enum") == 0 ||
			       strcmp(tk[from], "class") == 0 || isTypeIdWord(tk[from]) ||
			       strcmp(tk[from], "typename") == 0)) from++;
			if (from >= ntk) return;
			/* declarator list */
			int i = from;
			int tstart = from;
			int d = 0;
			int ndecl = 0;
			while (i <= ntk) {
				if (i == ntk || (strcmp(tk[i], ",") == 0 && d == 0)) {
					int j = i - 1;
					int ni = findDeclaratorName(j);
					if (ni >= tstart) {
						char tr[2048];
						makeTyperef(tr, sizeof(tr), tstart, ni - 1 >= tstart ? ni - 1 : tstart);
						int isfn = 0;
						for (int q = tstart; q < i; q++) if (strcmp(tk[q], "(") == 0) isfn = 1;
						char letter = isfn ? 'x' : 'v';
						if (kindIsEnabled(kindByLetter(curParser, letter))) {
							resetCur();
							snprintf(cur.name, sizeof(cur.name), "%s", tk[ni]);
							setKind(letter);
							cur.line = tkL[ni];
							cur.patternComplete = 1;
							snprintf(cur.typeref, sizeof(cur.typeref), "%s", tr);
							if (nScope > 0) {
								char sc[2048];
								scopeStr(sc, sizeof(sc));
								snprintf(cur.scope, sizeof(cur.scope), "%s", sc);
								cur.nth = ndecl;
							} else {
								cur.isfile = (depth == 0 && !curParserIsHeader() &&
								      (isStorageWord(tk[0]) || nScope > 0));
							}
							makeTagEntry();
						}
					}
					ndecl++;
					tstart = i + 1;
					i++;
					continue;
				}
				if (strcmp(tk[i], "(") == 0) d++;
				else if (strcmp(tk[i], ")") == 0) d--;
				i++;
			}
		}
		return;
	}
	if (stopper == '}') {
		if (nScope > 0 && scopeStack[nScope-1].depth == depth) {
			int wasTypedef = scopeIsTypedef[nScope - 1];
			char kindc = scopeStack[nScope-1].kind;
			char name[1024];
			strcpy(name, scopeStack[nScope-1].name);
			int dn = depth;
			scopePopTo(depth);
			if (wasTypedef) {
				/* next tokens up to ';' name the typedef */
				int t;
				char names[16][256];
				int nn = 0;
				int lvl = 0;
				while ((t = nextTok()) != T_EOF) {
					if (t == T_PUNCT) {
						if (strcmp(tokText, "(") == 0) lvl++;
						else if (strcmp(tokText, ")") == 0) lvl--;
						else if (strcmp(tokText, ";") == 0 && lvl == 0) break;
						else if (strcmp(tokText, ",") == 0 && lvl == 0) continue;
						else if (strcmp(tokText, "{") == 0 || strcmp(tokText, "}") == 0) break;
						continue;
					}
					if (t == T_ID && nn < 16) strcpy(names[nn++], tokText);
				}
				for (int i = 0; i < nn; i++) {
					if (!kindIsEnabled(kindByLetter(curParser, 't'))) continue;
					resetCur();
					snprintf(cur.name, sizeof(cur.name), "%s", names[i]);
					setKind('t');
					cur.line = tkL[0];
					cur.patternComplete = 1;
					char tr[2048];
					if (kindc == 's') snprintf(tr, sizeof(tr), "struct:%s", name);
					else if (kindc == 'u') snprintf(tr, sizeof(tr), "union:%s", name);
					else if (kindc == 'g') snprintf(tr, sizeof(tr), "enum:%s", name);
					else snprintf(tr, sizeof(tr), "class:%s", name);
					snprintf(cur.typeref, sizeof(cur.typeref), "%s", tr);
					cur.isfile = (dn == 1 && !curParserIsHeader());
					makeTagEntry();
				}
			}
		}
		return;
	}
