/* pending typedef names for scopes that were typedef'd */
static int scopeIsTypedef[256];

static void emitTypeTag(char kindc, const char *tagname, int line, int anon, int isTypedef,
			int ti, int depth)
{
	Parser *p = curParser;
	char outer[2048];
	int saveN = nScope;
	/* build the enclosing scope string */
	int sn = 0;
	char out[4096];
	out[0] = 0;
	const char *ks = "";
	if (nScope > 0) {
		switch (scopeStack[nScope - 1].kind) {
		case 's': ks = "struct"; break;
		case 'u': ks = "union"; break;
		case 'g': ks = "enum"; break;
		case 'c': ks = "class"; break;
		case 'n': ks = "namespace"; break;
		}
		snprintf(out, sizeof(out), "%s:", ks);
		for (int i = 0; i < nScope; i++) {
			if (i) strncat(out, "::", sizeof(out));
			strncat(out, scopeStack[i].name, sizeof(out));
		}
	}
	if (!kindIsEnabled(kindByLetter(p, kindc))) return;
	resetCur();
	snprintf(cur.name, sizeof(cur.name), "%s", tagname);
	setKind(kindc);
	cur.line = line;
	cur.patternComplete = 1;
	cur.anon = anon;
	if (out[0]) snprintf(cur.scope, sizeof(cur.scope), "%s", out);
	/* end line unknown yet; filled in after the body */
	cur.endline = 0;
	cur.isfile = depth == 0 && !curParserIsHeader();
	makeTagEntry();
}

int curParserIsHeader(void);

/* parse the body of a type; returns the line of the closing brace */
static void parseTypeBody(char kindc, const char *tagname, int anon, int depth, int isTypedef);

static void analyzeDecl(int stopper, int depth)
{
	if (ntk == 0) return;
	int isTypedef = (strcmp(tk[0], "typedef") == 0);
