		    strcmp(tk[i], "enum") == 0 || strcmp(tk[i], "class") == 0) { ti = i; break; }
	int isNamespace = (ti < 0 && ntk > 0 && strcmp(tk[0], "namespace") == 0);

	if (stopper == '{') {
