			if (nameIdx >= 0) snprintf(tagname, sizeof(tagname), "%s", tk[nameIdx]);
			else { anonName(tagname, sizeof(tagname)); anon = 1; }
			emitTypeTag(kindc, tagname, tkL[ti], anon, isTypedef, ti, depth);
			int mydepth = depth + 1;
			scopePush(kindc, tagname, mydepth);
