static void skipBalancedBraces(void) {
	int lvl = 1;
	int t;
	while ((t = nextTok()) != T_EOF) {
		if (t == T_PUNCT) {
			if (strcmp(tokText, "{") == 0) lvl++;
			else if (strcmp(tokText, "}") == 0) { lvl--; if (lvl == 0) return; }
		}
	}
}

static int isControlKeyword(const char *s) {
	static const char *kw[] = { "if", "else", "for", "while", "do", "switch", "try",
				    "catch", "return", "case", "default", NULL };
	for (int i = 0; kw[i]; i++) if (strcmp(s, kw[i]) == 0) return 1;
	return 0;
}

static void parseEnumEnumerators(int depth) {
	/* current scope is an enum: tokens are IDENT (, IDENT)* ; */
	if (nScope == 0 || scopeStack[nScope-1].kind != 'g') return;
	char scopebuf[4096];
	scopeStr(scopebuf, sizeof(scopebuf));
	int i = 0;
	int nth = 0;
	while (i < ntk) {
		if (tk[i][0] == 0) break;
		if (strcmp(tk[i], ",") == 0) { i++; continue; }
		if (strcmp(tk[i], "=") == 0) { i++; continue; }
		if (!(isalpha((unsigned char)tk[i][0]) || tk[i][0] == '_')) { i++; continue; }
		if (isTypeIdWord(tk[i]) && strcmp(tk[i], "bool") != 0) { i++; continue; }
		const Kind *k = kindByLetter(curParser, 'e');
