{"command": "cd /workspace && cat >> src/main.c <<'CEOF'

/* ---------------- output flushing ---------------- */
static char *etagBuf = NULL;
static size_t etagLen = 0, etagCap = 0;

void etagAdd(const char *s) {
	size_t l = strlen(s);
	if (etagLen + l + 1 > etagCap) {
		etagCap = etagCap ? etagCap * 2 : 65536;
		etagBuf = realloc(etagBuf, etagCap);
	}
	memcpy(etagBuf + etagLen, s, l);
	etagLen += l;
	etagBuf[etagLen] = 0;
}

void etagFlush(const char *fname) {
	if (!etagBuf || etagLen == 0) { etagLen = 0; return; }
	fprintf(outfp, "\f\n%s,%zu\n", fname, etagLen);
	fwrite(etagBuf, 1, etagLen, outfp);
	etagLen = 0;
}

static int cmpTags(const void *a, const void *b) {
	const char *x = *(const char *const *)a, *y = *(const char *const *)b;
	if (opt.sort == 2) {
		while (*x && *y) {
			int cx = tolower((unsigned char)*x), cy = tolower((unsigned char)*y);
			if (cx != cy) return cx - cy;
			x++; y++;
		}
		return (unsigned char)*x - (unsigned char)*y;
	}
	return strcmp(x, y);
}

void finishOutput(void) {
	if (opt.etags_mode) return;	/* etags output is flushed per file */
	/* pseudo tags are only written to a real tag file */
	if (!outIsStdout && opt.output_format >= 0 &&
	    strcmp(gOutFormats[opt.output_format].name, "json") != 0) {
		/* they will be prepended by the caller through addTagLine before sorting */
	}
	int n = tagCount();
	const char **arr = malloc(sizeof(char *) * (n + 1));
	for (int i = 0; i < n; i++) arr[i] = tagLine(i);
	if (opt.sort != 0) {
		qsort(arr, n, sizeof(char *), cmpTags);
		/* stable-ish: qsort is not stable; emulate sort -u behaviour */
	}
	/* write */
	long last = -1;
	for (int i = 0; i < n; i++) {
		if (opt.sort != 0 && last >= 0 && strcmp(arr[last], arr[i]) == 0) continue;
		fputs(arr[i], outfp);
		last = i;
	}
	/* pseudo tags first (already added by caller if not stdout) */
	if (opt.totals) {
		double secs = 0.0;
		fprintf(stderr, "%d file%s, %d line%s (%d kB) scanned in %.1f seconds (%d kB/s)\n",
			nSourceFiles, nSourceFiles == 1 ? "" : "s", nSourceLines,
