{"command": "cd /workspace && cat > tools/gen.py <<'PYEOF'
#!/usr/bin/env python3
"""Build src/langdata.c from the captured reference outputs in /tmp/ref."""
import os, re, json, sys

REF = '/tmp/ref'
def rd(name):
    return open(os.path.join(REF, name)).read()

def mrows(name):
    out = rd('m-%s.tsv' % name)
    return [l.split('\t') for l in out.rstrip('\n').split('\n') if l]

def rows(name):
    out = rd('%s.txt' % name)
    ls = [l for l in out.rstrip('\n').split('\n') if l]
    if ls and ls[0].startswith('#'):
        ls = ls[1:]
    return ls

langs_raw = rd('languages.txt')
langs = [l.split(' ')[0] for l in langs_raw.strip().split('\n')]
disabled = set(l.split(' ')[0] for l in langs_raw.strip().split('\n') if '[disabled]' in l)

verbose = rd('verbose0.err')
m = re.search(r'^Installing parsers:(.*)$', verbose, re.M)
reg = [nm.strip() for nm in m.group(1).split(',')]

maps_ext = mrows("map-extensions")
maps_pat = mrows("map-patterns")
maps_rex = mrows("map-rexprs")
aliases = mrows("aliases")
kinds = mrows("kinds-full")
roles = mrows("roles")
fields = mrows("fields")
extras = mrows("extras")
params = mrows("params")
subs = mrows("subparsers")
pseudo = mrows("pseudo-tags")
oforms = mrows("output-formats")
rflags = rows("regex-flags")
mflags = rows("mline-regex-flags")
excludes = rows("excludes")
features = rows("features")

nulltags = {}
for l in open(os.path.join(REF, 'nulltags.txt')):
    nm, _, v = l.strip().partition('|')
    nulltags[nm] = 'yes' in v
versions = {}
for l in open(os.path.join(REF, 'versions.txt')):
    nm, _, v = l.strip().partition('|')
    mm = re.search(r'version: (\S+)', v)
    versions[nm] = mm.group(1)

def group_by(rs, idx):
    d = {}
    for r in rs:
        d.setdefault(r[idx], []).append(r)
    return d

g_ext = group_by(maps_ext, 0)
g_pat = group_by(maps_pat, 0)
g_rex = group_by(maps_rex, 0)
g_ali = group_by(aliases, 0)
g_kin = group_by(kinds, 0)
g_fld = group_by(fields, 3)
g_exx = group_by(extras, 3)

# kind declaration order per language: from --list-kinds=<lang>
kind_order = {}
kl = rd('listkinds.txt') if os.path.exists(os.path.join(REF,'listkinds.txt')) else None
roleorder = json.load(open(os.path.join(REF, 'roleorder.json')))
role_reg = roleorder

# rebuild kind declaration order from the kinds data + roleorder/kinds list
# (captured separately in kinds_order.txt)
korder = {}
kf = rd('kinds_order.txt')
cur = None
for l in kf.rstrip('\n').split('\n'):
    if l.startswith('###'):
        cur = l[3:]; korder[cur] = []
    elif cur and l.strip():
        korder[cur].append(l.split(' ')[0])
kind_order = korder

out = []
out.append('/* Generated by tools/gen.py from captured reference data. */\n')
out.append('static const char *LANGDATA =\n')
def add(s):
    out.append('\t"%s\\n"\n' % s.replace('\\', '\\\\').replace('"', '\\"'))

add("@REG\t" + "\t".join(reg))
add("@LIST\t" + "\t".join(langs))
for nm in langs:
    ver = versions.get(nm, "0.0")
    en = "0" if nm in disabled else "1"
    nt = "1" if nulltags.get(nm) else "0"
    add("@LANG\t%s\t%s\t%s\t%s" % (nm, ver, en, nt))
    for r in g_ext.get(nm, []): add("E\t" + r[1])
    for r in g_pat.get(nm, []): add("P\t" + r[1])
    for r in g_rex.get(nm, []): add("R\t%s\t%s" % (r[1], r[2]))
    for r in g_ali.get(nm, []): add("A\t" + r[1])
    kls = kind_order.get(nm, [])
    seen = set()
    ordered = []
    for k in kls:
        for r in g_kin.get(nm, []):
            if r[1] == k and id(r) not in seen:
                ordered.append(r); seen.add(id(r))
    for r in g_kin.get(nm, []):
        if id(r) not in seen:
            ordered.append(r); seen.add(id(r))
    for r in ordered:
        add("K\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s" % (r[1], r[2], r[3], r[4], r[5], r[6], r[7], r[8]))
    allroles = []
    for r in roles:
        if r[0] != nm: continue
        kn = r[1].split('/')[1]
        kl2 = ''
        for k in g_kin.get(nm, []):
            if k[2] == kn: kl2 = k[1]; break
        allroles.append((kl2, kn, r[2], r[3], r[4], r[5]))
    used = [False] * len(allroles)
    out_roles = []
    for kl2 in kls:
        idxs = [i for i in range(len(allroles)) if allroles[i][0] == kl2 and not used[i]]
        byname = {allroles[i][2]: i for i in idxs}
        knset = set(allroles[i][1] for i in idxs)
        for (kn2, rn) in role_reg.get(nm, []):
            if kn2 in knset and rn in byname and rn not in byname and False:
                pass
        emitted = set()
        for (kn2, rn) in role_reg.get(nm, []):
            if kn2 in knset and rn in byname and rn not in emitted:
                out_roles.append(allroles[byname[rn]]); emitted.add(rn); used[byname[rn]] = True
        for i in idxs:
            if not used[i]:
                out_roles.append(allroles[i]); used[i] = True
    for rr in out_roles:
        kl2, kn, rn, en2, ver2, desc = rr
        add("Q\t%s\t%s\t%s\t%s\t%s\t%s" % (kl2, kn, rn, en2, ver2, desc))
    for r in g_fld.get(nm, []):
        add("F\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s" % (r[0], r[1], r[2], r[4], r[5], r[6], r[7], r[8]))
    for r in g_exx.get(nm, []):
        add("X\t%s\t%s\t%s\t%s\t%s\t%s" % (r[0], r[1], r[2], r[4], r[5], r[6]))
    for r in params:
        if r[0] == nm: add("T\t%s\t%s" % (r[1], r[2]))
    for r in subs:
        if r[1] == nm:
            add("S\t%s\t%s\t%s" % (r[0], r[2], r[3] if len(r) > 3 else ''))

for f in fields:
    if f[0] != '-':
        add("@F\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s" % (f[0], f[1], f[2], f[4], f[5], f[6], f[7], f[8]))
