		if (sp) { *sp = 0; ds = sp + 1; while (*ds == ' ') ds++; }
		lAdd(2, (const char *[]){ nm, ds });
	}''')
# F line: consume letter
l=l.replace('''				LField *f = &cur->fields[cur->nfields++];
				f->name = strdup0(tokNext(&t));''','''				LField *f = &cur->fields[cur->nfields++];
				(void)tokNext(&t); /* letter */
				f->name = strdup0(tokNext(&t));''')
# output formats header
l=l.replace('''void listOutFormats(void) {
	for (int i = 0; i < gNOutFormats; i++) {''','''void listOutFormats(void) {
	printf("#OFORMAT DEFAULT AVAILABLE NULLTAG \\n");
	for (int i = 0; i < gNOutFormats; i++) {''')
# kinds-full and roles: byte order of languages
l=l.replace('''static int kindCmpLetter(const void *a, const void *b) {''','''static int langCmpName(const void *a, const void *b) {
	const Parser *x = *(Parser *const *)a, *y = *(Parser *const *)b;
	return strcmp(x->name, y->name);
}

static int kindCmpLetter(const void *a, const void *b) {''')
l=l.replace('''		const char *labels[9] = { "LANGUAGE", "LETTER", "NAME", "ENABLED", "REFONLY", "NROLES", "MASTER", "VER", "DESCRIPTION" };
		lStart(9, labels);
		for (int i = 0; i < gNParsers; i++) {
			Parser *p = gParsers[i];
			if (p->hidden) continue;
			Kind *sorted[128];''','''		const char *labels[9] = { "LANGUAGE", "LETTER", "NAME", "ENABLED", "REFONLY", "NROLES", "MASTER", "VER", "DESCRIPTION" };
		lStart(9, labels);
		Parser *ps[512];
		int np = 0;
		for (int i = 0; i < gNParsers; i++)
			if (!gParsers[i]->hidden && gParsers[i]->nkinds > 0) ps[np++] = gParsers[i];
		qsort(ps, np, sizeof(Parser *), langCmpName);
		for (int i = 0; i < np; i++) {
			Parser *p = ps[i];
			Kind *sorted[128];''')
l=l.replace('''		const char *labels[6] = { "LANGUAGE", "KIND(L/N)", "NAME", "ENABLED", "VER", "DESCRIPTION" };
		lStart(6, labels);
		for (int i = 0; i < gNParsers; i++) {
			Parser *p = gParsers[i];
			if (p->hidden) continue;
			int order[128], n = 0;
			for (int j = 0; j < p->nkinds; j++) order[n++] = j;
			Kind *sorted[128];
			for (int j = 0; j < n; j++) sorted[j] = &p->kinds[order[j]];
			qsort(sorted, n, sizeof(Kind *), kindCmpLetter);''','''		const char *labels[6] = { "LANGUAGE", "KIND(L/N)", "NAME", "ENABLED", "VER", "DESCRIPTION" };
		lStart(6, labels);
		Parser *ps[512];
		int np = 0;
		for (int i = 0; i < gNParsers; i++)
			if (!gParsers[i]->hidden && gParsers[i]->nroles > 0) ps[np++] = gParsers[i];
		qsort(ps, np, sizeof(Parser *), langCmpName);
		for (int i = 0; i < np; i++) {
			Parser *p = ps[i];
			int order[128], n = 0;
			for (int j = 0; j < p->nkinds; j++) order[n++] = j;
			Kind *sorted[128];
			for (int j = 0; j < n; j++) sorted[j] = &p->kinds[order[j]];
			qsort(sorted, n, sizeof(Kind *), kindCmpLetter);''')
open('src/langdb.c','w').write(l)
PY
./compile.sh 2>&1|grep -E "error"|head -3; for o in languages features pseudo-tags extras excludes aliases map-extensions map-patterns map-rexprs params subparsers output-formats regex-flags mline-regex-flags kinds-full fields roles; do
 if diff <(./executable --list-$o 2>/dev/null) /tmp/ref/$o.txt >/dev/null 2>&1; then echo "OK  $o"; else echo "DIFF $o: $(diff <(./executable --list-$o 2>/dev/null) /tmp/ref/$o.txt|head -4|tr '\n' '|')"; fi
done"}

