        }
        if (strcmp(tk[i], "<") == 0 && lastId >= 0) angle++;
        else if (strcmp(tk[i], ">") == 0 && angle > 0) angle--;
        else if (strcmp(tk[i], "(") == 0) paren++;
        else if (strcmp(tk[i], ")") == 0) { if (paren) paren--; }
        else if (strcmp(tk[i], "[") == 0) brack++;
        else if (strcmp(tk[i], "]") == 0) { if (brack) brack--; }
