import sys,subprocess
syms=[]
for l in sys.stdin:
    p=l.split()
    if len(p)==2:
        try: syms.append((int(p[0],16),p[1]))
        except: pass
syms.sort()
# get ras from a fresh run of the same binary
o=subprocess.run(['/tmp/pt/../../workspace/executable','-o','-','--sort=no','/tmp/pt/a.c'],capture_output=True,text=True,cwd='/tmp/pt')
" ; CTDBG=1 CTDBG2=1 ./executable -o - --sort=no /tmp/pt/a.c 2>&1 >/dev/null | grep -o "ra=0x[0-9a-f]*"|sort -u > /tmp/ras.txt; cat /tmp/ras.txt; python3 - <<'PY'
import subprocess
syms=[]
for l in subprocess.run(['nm','-C','/workspace/executable'],capture_output=True,text=True).stdout.split('\n'):
    p=l.split()
    if len(p)==3 and p[1] in 'tT':
        try: syms.append((int(p[0],16),p[2]))
        except: pass
syms.sort()
ras=[int(l.strip(),16) for l in open('/tmp/ras.txt') if l.startswith('0x')]
# find base: for the ra that appears in collectTokens... brute force over symbol starts
best=None
for addr,name in syms:
    b = ras[0] - addr
    ok=0
    for r in ras:
        off = r - b
        # find containing symbol
        lo=0
        for i in range(len(syms)-1,-1,-1):
            if syms[i][0]<=off:
                lo=i; break
        else:
            lo=-1
        if lo>=0 and off - syms[lo][0] < 4000: ok+=1
    if ok==len(ras):
        best=(b,name); break
print("base guess:", best)
if best:
    b=best[0]
    for r in ras:
        off=r-b
        nm2=None
        for i in range(len(syms)-1,-1,-1):
            if syms[i][0]<=off: nm2=(syms[i][1], off-syms[i][0]); break
        print(hex(r), nm2)
PY"}

