# 1) Replace preprocPass with a version that also records directive info
old_start = p.index("/* ================= preprocessor pass ================= */")
old_end = p.index("/* ================= lexer ================= */")
new = r'''/* ================= preprocessor pass ================= */
typedef struct {
	char type;			/* 0 none, 'd' define, 'u' undef, 'i' include */
	char name[1024];
	char pattern[8192];
	int complete;
	int isSystem;
} DirInfo;
static DirInfo *dirInfo;

static void preprocPass(void) {
	int depth = 0;
	int falsenest[128];
	int top = 0;
	dirInfo = calloc((size_t)src.nloff + 2, sizeof(DirInfo));
	for (int i = 1; i <= src.nloff; i++) {
		char *l = lineText(i);
		char *p = l;
		while (*p == ' ' || *p == '\t') p++;
		int isdir = (*p == '#');
		if (top > 0) src.falseCond[i] = falsenest[top - 1];
		if (!isdir) continue;
		p++;
		while (*p == ' ' || *p == '\t') p++;
		char dir[32];
		int n = 0;
		while (isalpha((unsigned char)*p) && n < 31) dir[n++] = *p++;
		dir[n] = 0;
		if (strcmp(dir, "if") == 0) {
			int v = 1;
			const char *q = p;
			while (*q == ' ' || *q == '\t') q++;
			if (*q == '0' && !isalnum((unsigned char)q[1])) v = 0;
			if (top < 128) falsenest[top++] = v ? 0 : 1;
		} else if (strcmp(dir, "ifdef") == 0 || strcmp(dir, "ifndef") == 0) {
			if (top < 128) falsenest[top++] = 0;
		} else if (strcmp(dir, "else") == 0 || strcmp(dir, "elif") == 0) {
			if (top > 0) falsenest[top - 1] = !falsenest[top - 1];
		} else if (strcmp(dir, "endif") == 0) {
			if (top > 0) top--;
		}
		if (top > 0) src.falseCond[i] = falsenest[top - 1];
		if (src.falseCond[i]) continue;
		DirInfo *di = &dirInfo[i];
		if (strcmp(dir, "define") == 0) {
			char *q = p + n;
			while (*q == ' ' || *q == '\t') q++;
			int m = 0;
			while ((isalnum((unsigned char)*q) || *q == '_') && m < 1023) di->name[m++] = *q++;
			di->name[m] = 0;
			if (!m) continue;
			di->type = 'd';
			/* pattern: line up to and including the char after the name */
			size_t off = (size_t)(q - l);
			size_t cut = off;
			size_t llen = strlen(l);
			if (cut < llen) cut++;
			if (cut > llen) cut = llen;
			di->complete = (cut >= llen);
			size_t cl = cut;
			if (cl >= sizeof(di->pattern) - 4) { cl = sizeof(di->pattern) - 5; di->complete = 0; }
			memcpy(di->pattern, l, cl);
			di->pattern[cl] = 0;
		} else if (strcmp(dir, "undef") == 0) {
			char *q = p + n;
			while (*q == ' ' || *q == '\t') q++;
			int m = 0;
			while ((isalnum((unsigned char)*q) || *q == '_') && m < 1023) di->name[m++] = *q++;
			di->name[m] = 0;
			if (!m) continue;
			di->type = 'u';
		} else if (strcmp(dir, "include") == 0) {
			char *q = p + n;
			while (*q == ' ' || *q == '\t') q++;
			if (*q == '"') {
				q++;
				int m = 0;
				while (*q && *q != '"' && m < 1023) di->name[m++] = *q++;
				di->name[m] = 0;
				di->type = 'i';
				di->isSystem = 0;
			} else if (*q == '<') {
				q++;
				int m = 0;
				while (*q && *q != '>' && m < 1023) di->name[m++] = *q++;
				di->name[m] = 0;
				di->type = 'i';
				di->isSystem = 1;
			}
		}
	}
}

'''
p = p[:old_start] + new + p[old_end:]
open('src/parse.c','w').write(p)
