				else if (*q == '"' && !inS) inD = !inD;
				else if (*q == '#' && !inS && !inD) { *q = 0; break; }
				q++;
			}
		}
		/* indentation */
		int ind = 0;
		for (char *q = buf; *q == ' ' || *q == '\t'; q++) ind++;
