			char nm[512];
			const char *q = s + 1;
			int m = 0;
			while (*q && !isspace((unsigned char)*q) && m < 511) nm[m++] = *q++;
			nm[m] = 0;
			if (decorators[0]) strncatG(decorators, ",", sizeof(decorators));
			strncatG(decorators, nm, sizeof(decorators));
			continue;
		}
		int endline = 0;
		/* compute the end line for a block */
		{
			int j = i + 1;
			while (j <= src.nloff) {
				char *ll = lineText(j);
				char *qq = ll;
				while (*qq == ' ' || *qq == '\t') qq++;
				if (*qq == 0) { j++; continue; }
				int ind2 = 0;
				for (char *q = ll; *q == ' ' || *q == '\t'; q++) ind2++;
				if (ind2 > ind) { j++; continue; }
				break;
			}
			endline = j - 1;
			while (endline > i) {
				char *ll = lineText(endline);
				char *qq = ll;
				while (*qq == ' ' || *qq == '\t') qq++;
				if (*qq) break;
				endline--;
			}
		}
		if (strncmp(s, "class ", 6) == 0) {
			char nm[1024], bases[2048];
			const char *q = s + 6;
			int m = 0;
			while (*q && (isalnum((unsigned char)*q) || *q == '_') && m < 1023) nm[m++] = *q++;
			nm[m] = 0;
			bases[0] = 0;
			const char *pp = strchr(q, '(');
			if (pp) {
				const char *pe = strchr(pp, ')');
				if (pe) {
					size_t n = (size_t)(pe - pp) - 1;
					if (n >= sizeof(bases)) n = sizeof(bases) - 1;
					memcpy(bases, pp + 1, n);
					bases[n] = 0;
					/* normalise whitespace */
					char out[2048];
					int o = 0;
					for (size_t z = 0; z < n; z++) {
						char ch = bases[z];
						if (ch == ' ' || ch == '\t' || ch == '\n') continue;
						out[o++] = ch;
					}
					out[o] = 0;
					snprintf(bases, sizeof(bases), "%s", out);
				}
			}
			char scope[4096];
			scope[0] = 0;
			for (int z = 0; z < pyN; z++) {
				if (z) strncatG(scope, ".", sizeof(scope));
				strncatG(scope, pyStack[z].name, sizeof(scope));
			}
			if (pyN > 0 && scope[0]) {
				char sc2[4096];
				snprintf(sc2, sizeof(sc2), "class:%s", scope);
				pyEmit('c', nm, i, sc2, NULL, NULL, bases, NULL, decorators[0] ? decorators : NULL, endline, 0, 0);
			} else
				pyEmit('c', nm, i, NULL, NULL, NULL, bases, NULL, decorators[0] ? decorators : NULL, endline, 0, 0);
			if (pyN < 256) { pyStack[pyN].indent = ind; pyStack[pyN].kind = 'c'; strcpy(pyStack[pyN].name, nm); pyStack[pyN].defline = i; pyN++; }
			decorators[0] = 0;
			continue;
		}
		if (strncmp(s, "def ", 4) == 0 || strncmp(s, "async def ", 10) == 0) {
			const char *q = s + (strncmp(s, "async ", 6) == 0 ? 10 : 4);
			char nm[1024], sig[2048];
			int m = 0;
			while (*q && (isalnum((unsigned char)*q) || *q == '_') && m < 1023) nm[m++] = *q++;
			nm[m] = 0;
			sig[0] = 0;
			const char *pp = strchr(q, '(');
			if (pp) {
				const char *pe = strchr(pp, ')');
				if (pe) {
					size_t n = (size_t)(pe - pp) + 1;
					if (n >= sizeof(sig)) n = sizeof(sig) - 1;
					memcpy(sig, pp, n);
					sig[n] = 0;
					/* collapse whitespace, drop the space after ',' */
					char out[2048];
					int o = 0;
					int lastCom = 0;
					for (size_t z = 0; z < n; z++) {
						char ch = sig[z];
						if (ch == '\n' || ch == '\t' || ch == '\r') ch = ' ';
						if (ch == ' ' && o > 0 && (out[o-1] == ' ' || out[o-1] == ',')) continue;
						out[o++] = ch;
						lastCom = (ch == ',');
					}
					out[o] = 0;
					snprintf(sig, sizeof(sig), "%s", out);
				}
			}
			char scope[4096];
			scope[0] = 0;
			char kindc = 'f';
			for (int z = 0; z < pyN; z++) {
				if (z) strncatG(scope, ".", sizeof(scope));
				strncatG(scope, pyStack[z].name, sizeof(scope));
			}
			if (pyN > 0 && scope[0]) {
				char sc2[4096];
				snprintf(sc2, sizeof(sc2), "class:%s", scope);
				kindc = 'm';
				pyEmit(kindc, nm, i, sc2, NULL, sig, NULL, NULL, decorators[0] ? decorators : NULL, endline, 0, 0);
			} else
				pyEmit('f', nm, i, NULL, NULL, sig, NULL, NULL, decorators[0] ? decorators : NULL, endline, 0, 0);
			if (pyN < 256) { pyStack[pyN].indent = ind; pyStack[pyN].kind = 'f'; strcpy(pyStack[pyN].name, nm); pyStack[pyN].defline = i; pyN++; }
			decorators[0] = 0;
			continue;
		}
		/* imports */
		if (strncmp(s, "import ", 7) == 0) {
			char *q = s + 7;
			char *comma = q;
			while ((comma = strchr(comma, ',')) != NULL) {
				/* multiple imports on one line */
				char part[512];
				size_t n = (size_t)(comma - q);
				if (n >= sizeof(part)) n = sizeof(part) - 1;
				memcpy(part, q, n); part[n] = 0;
				pyImport(part, i);
				q = comma + 1;
				while (*q == ' ') q++;
				comma = q;
			}
			pyImport(q, i);
			continue;
		}
		if (strncmp(s, "from ", 5) == 0) {
			char mod[512], names[1024];
			const char *q = s + 5;
			int m = 0;
			while (*q && !isspace((unsigned char)*q) && m < 511) mod[m++] = *q++;
			mod[m] = 0;
			while (*q == ' ') q++;
			if (strncmp(q, "import ", 7) == 0) {
				q += 7;
				snprintf(names, sizeof(names), "%s", q);
				char *nl = strchr(names, '\n');
				if (nl) *nl = 0;
				if (strcmp(names, "*") == 0) {
					char sc[1024];
					snprintf(sc, sizeof(sc), "module:%s", mod);
					pyEmit('Y', "", i, sc, NULL, NULL, NULL, "namespace", NULL, 0, 1, 0);
				} else {
					char sc[1024];
					snprintf(sc, sizeof(sc), "module:%s", mod);
					pyEmit('i', mod, i, NULL, NULL, NULL, NULL, "namespace", NULL, 0, 1, 0);
					char *tok, *save = NULL;
					char buf2[1024];
					snprintf(buf2, sizeof(buf2), "%s", names);
					for (tok = strtok_r(buf2, ",", &save); tok; tok = strtok_r(NULL, ",", &save)) {
						while (*tok == ' ') tok++;
						char *nl = strchr(tok, '\n');
						if (nl) *nl = 0;
						char n1[512], n2[512];
						n1[0] = n2[0] = 0;
						char *as = strstr(tok, " as ");
						if (as) {
							size_t n = (size_t)(as - tok);
							if (n >= sizeof(n1)) n = sizeof(n1) - 1;
							memcpy(n1, tok, n); n1[n] = 0;
							snprintf(n2, sizeof(n2), "%s", as + 4);
							char *nl2 = strchr(n2, '\n');
							if (nl2) *nl2 = 0;
							char *e = n2 + strlen(n2);
							while (e > n2 && isspace((unsigned char)e[-1])) *--e = 0;
						} else snprintf(n1, sizeof(n1), "%s", tok);
						char *e = n1 + strlen(n1);
						while (e > n1 && isspace((unsigned char)e[-1])) *--e = 0;
						if (n1[0]) {
							pyEmit('Y', n1, i, sc, NULL, NULL, NULL, "imported", NULL, 0, 1, 0);
							if (n2[0] && strcmp(n1, n2) != 0)
								pyEmit('Y', n1, i, sc, NULL, NULL, NULL, "indirectlyImported", NULL, 0, 1, 0);
						}
					}
				}
			}
			continue;
		}
		/* assignment */
		{
			char nm[1024];
			const char *q = s;
			int m = 0;
			if (isalpha((unsigned char)*q) || *q == '_') {
				while (*q && (isalnum((unsigned char)*q) || *q == '_') && m < 1023) nm[m++] = *q++;
				nm[m] = 0;
				const char *r = q;
				while (*r == ' ') r++;
				if (*r == '=' && r[1] != '=') {
					/* lambda? */
					const char *lam = strstr(r, "lambda");
					char sig[1024];
					sig[0] = 0;
					if (lam) {
						const char *pp = strchr(lam, '(');
						if (pp) {
							const char *pe = strchr(pp, ')');
							if (pe) {
								size_t n = (size_t)(pe - pp) + 1;
								if (n >= sizeof(sig)) n = sizeof(sig) - 1;
								memcpy(sig, pp, n);
								sig[n] = 0;
							}
						}
					}
					char scope[4096];
					scope[0] = 0;
					char kindc = 'v';
					for (int z = 0; z < pyN; z++) {
						if (z) strncatG(scope, ".", sizeof(scope));
						strncatG(scope, pyStack[z].name, sizeof(scope));
					}
					if (pyN > 0 && scope[0]) {
						char sc2[4096];
						snprintf(sc2, sizeof(sc2), "class:%s", scope);
						if (lam[0]) {
							pyEmit('f', nm, i, sc2, NULL, sig, NULL, NULL, NULL, 0, 0, 0);
						} else
							pyEmit('v', nm, i, sc2, NULL, NULL, NULL, NULL, NULL, 0, 0, 0);
					} else if (lam[0])
						pyEmit('f', nm, i, NULL, NULL, sig, NULL, NULL, NULL, 0, 0, 0);
					else
						pyEmit('v', nm, i, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0);
				}
			}
		}
	}
}
CEOF
echo ok"}

