{"command": "cd /workspace && git add -A && git -c user.email=a@b -c user.name=a commit -q -m "python parser" && cat > src/parsers3.c <<'CEOF'
#include "ctags.h"

void pyEmit(char letter, const char *name, int line, const char *scope,
	    const char *typeref, const char *signature, const char *inherits,
	    const char *role, const char *nameref, const char *decorators,
	    int endline, int reference, int isfile);

/* =============== Java =============== */
typedef struct { char kind; char name[1024]; int tagidx; int endline; } JvScope;
static JvScope jvStack[128];
static int jvN;

static void jvEmit(char letter, const char *name, int line, const char *scope,
		   const char *typeref, const char *signature, const char *inherits,
		   const char *role, const char *access, int endline, int reference, int isfile)
{
	const Kind *k = kindByLetter(curParser, letter);
	if (!k || !k->enabled) return;
	resetCur();
	snprintf(cur.name, sizeof(cur.name), "%s", name);
	cur.kindLetter = letter;
	cur.kindName = k->name;
	cur.line = line;
	cur.patternComplete = 1;
	cur.endline = endline;
	cur.isfile = isfile;
	if (scope && scope[0]) snprintf(cur.scope, sizeof(cur.scope), "%s", scope);
	if (typeref && typeref[0]) snprintf(cur.typeref, sizeof(cur.typeref), "%s", typeref);
	if (signature && signature[0]) snprintf(cur.signature, sizeof(cur.signature), "%s", signature);
	if (inherits) snprintf(cur.inherits, sizeof(cur.inherits), "%s", inherits);
	if (role && role[0]) { snprintf(cur.role, sizeof(cur.role), "%s", role); cur.reference = 1; }
	if (access && access[0]) snprintf(cur.access, sizeof(cur.access), "%s", access);
	setSrcLine(cur.line);
	cur.qualName[0] = 0;
	if (jvN > 0) {
		char qn[4096];
		qn[0] = 0;
		for (int i = 0; i < jvN - 1; i++) {
			if (i) p2catJ(qn, ".", sizeof(qn));
			p2catJ(qn, jvStack[i].name, sizeof(qn));
		}
		if (qn[0]) snprintf(cur.qualName, sizeof(cur.qualName), "%s.%s", qn, name);
		else snprintf(cur.qualName, sizeof(cur.qualName), "%s", name);
	}
	makeTagEntry();
}

void javaParse(const char *name)
{
	(void)name;
	jvN = 0;
	int depth = 0;
	for (;;) {
		int stopper = collectTokensJ(0);
		if (stopper == T_EOF) break;
		if (stopper == '{') { depth++; continue; }
		if (stopper == '}') {
			depth--;
			while (jvN > 0 && jvStack[jvN-1].depth >= depth + 1) {
				if (jvStack[jvN-1].tagidx >= 0) patchTagEnd(jvStack[jvN-1].tagidx, gStopLineJ());
				jvN--;
			}
			continue;
		}
		if (ntkJ() == 0) continue;
		/* package / import */
		if (tokIsJ(0, "package")) {
			char nm[2048];
			nm[0] = 0;
			for (int i = 1; i < ntkJ(); i++) {
				if (strcmp(tokAtJ(i), ";") == 0) break;
				p2catJ(nm, tokAtJ(i), sizeof(nm));
			}
			jvEmit('p', nm, tokLineJ(0), NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0);
			continue;
		}
		if (tokIsJ(0, "import")) {
			char nm[2048];
			nm[0] = 0;
			for (int i = 1; i < ntkJ(); i++) {
				if (strcmp(tokAtJ(i), ";") == 0) break;
				if (strcmp(tokAtJ(i), "static") == 0) continue;
				p2catJ(nm, tokAtJ(i), sizeof(nm));
			}
			jvEmit('p', nm, tokLineJ(0), NULL, NULL, NULL, NULL, "imported", NULL, 0, 1, 0);
			continue;
		}
		/* type declarations */
		int ti = -1;
		for (int i = 0; i < ntkJ(); i++)
			if (tokIsJ(i, "class") || tokIsJ(i, "interface") || tokIsJ(i, "enum") ||
			    tokIsJ(i, "@interface")) { ti = i; break; }
		if (stopper == '{' && ti >= 0) {
			char nm[1024];
			nm[0] = 0;
			if (ti + 1 < ntkJ()) snprintf(nm, sizeof(nm), "%s", tokAtJ(ti + 1));
			char kindc = tokIsJ(ti, "interface") ? 'i' : (tokIsJ(ti, "enum") ? 'g' : 'c');
			/* inherits */
			char bases[2048];
			bases[0] = 0;
			for (int i = ti + 1; i < ntkJ(); i++) {
				if (tokIsJ(i, "extends") || tokIsJ(i, "implements")) {
					for (int j = i + 1; j < ntkJ(); j++) {
						if (tokIsJ(j, "{")) break;
						if (j > i + 1) p2catJ(bases, ",", sizeof(bases));
						p2catJ(bases, tokAtJ(j), sizeof(bases));
					}
					break;
				}
			}
			char scope[4096];
			scope[0] = 0;
			for (int z = 0; z < jvN; z++) {
				if (z) p2catJ(scope, ".", sizeof(scope));
				p2catJ(scope, jvStack[z].name, sizeof(scope));
			}
			const char *ks = (kindc == 'i') ? "interface" : (kindc == 'g') ? "enum" : "class";
			char sc2[4096];
			sc2[0] = 0;
			if (scope[0]) snprintf(sc2, sizeof(sc2), "%s:%s", ks, scope);
			int idx = jvEmit(kindc, nm, tokLineJ(ti), sc2[0] ? sc2 : NULL, NULL, NULL,
					 bases[0] ? bases : NULL, NULL, NULL, 0, 0, 0);
			if (jvN < 128) {
				jvStack[jvN].kind = kindc;
				strcpy(jvStack[jvN].name, nm);
				jvStack[jvN].tagidx = idx;
				jvStack[jvN].depth = depth + 1;
				jvN++;
			}
			continue;
		}
		/* enum constants */
		if (jvN > 0 && jvStack[jvN-1].kind == 'g') {
			for (int i = 0; i < ntkJ(); i++) {
				if (!(isalpha((unsigned char)tokAtJ(i)[0]) || tokAtJ(i)[0] == '_')) continue;
				if (tokIsJ(i, "enum")) continue;
				char sc[4096];
				sc[0] = 0;
				for (int z = 0; z < jvN; z++) {
					if (z) p2catJ(sc, ".", sizeof(sc));
					p2catJ(sc, jvStack[z].name, sizeof(sc));
				}
				char sc2[4096];
				snprintf(sc2, sizeof(sc2), "enum:%s", sc);
				jvEmit('e', tokAtJ(i), tokLineJ(i), sc2, NULL, NULL, NULL, NULL, "public", 0, 0, 0);
			}
			continue;
		}
		/* fields and methods */
		{
			int close = -1;
			for (int i = ntkJ() - 1; i >= 0; i--)
				if (tokIsJ(i, ")")) { close = i; break; }
			char access[64];
			access[0] = 0;
			int start = 0;
			if (tokIsJ(0, "public") || tokIsJ(0, "private") || tokIsJ(0, "protected")) {
				snprintf(access, sizeof(access), "%s", tokAtJ(0));
				start = 1;
			}
			if (close > 0) {
				int open = -1, d = 0;
				for (int i = close; i >= 0; i--) {
					if (tokIsJ(i, ")")) d++;
					else if (tokIsJ(i, "(")) { d--; if (d == 0) { open = i; break; } }
				}
				if (open > start) {
					int nameIdx = -1;
					for (int i = open - 1; i >= start; i--) {
						if (isalpha((unsigned char)tokAtJ(i)[0]) || tokAtJ(i)[0] == '_' ||
						    tokAtJ(i)[0] == '$') { nameIdx = i; break; }
					}
					if (nameIdx >= 0 && !tokIsJ(nameIdx, "if") && !tokIsJ(nameIdx, "for") &&
					    !tokIsJ(nameIdx, "while") && !tokIsJ(nameIdx, "switch") &&
					    !tokIsJ(nameIdx, "catch") && !tokIsJ(nameIdx, "synchronized") &&
					    !tokIsJ(nameIdx, "return") && !tokIsJ(nameIdx, "new")) {
						char sig[4096];
						{
							size_t s0 = tokPosJ(open);
							size_t e0 = tokPosJ(close) + strlen(tokAtJ(close));
							size_t o = 0;
							for (size_t q = s0; q < e0 && o + 1 < sizeof(sig); q++) {
								char ch = srcBufChar(q);
								if (ch == '\n' || ch == '\t' || ch == '\r') ch = ' ';
								if (ch == ' ' && o > 0 && (sig[o-1] == ' ' || sig[o-1] == ',')) continue;
								sig[o++] = ch;
							}
							sig[o] = 0;
						}
						char scope[4096];
						scope[0] = 0;
						const char *ks = NULL;
						if (jvN > 0) {
							for (int z = 0; z < jvN; z++) {
								if (z) p2catJ(scope, ".", sizeof(scope));
								p2catJ(scope, jvStack[z].name, sizeof(scope));
							}
							ks = (jvStack[jvN-1].kind == 'i') ? "interface" :
							     (jvStack[jvN-1].kind == 'g') ? "enum" : "class";
						}
						char sc2[4096];
						sc2[0] = 0;
						if (scope[0]) snprintf(sc2, sizeof(sc2), "%s:%s", ks, scope);
						/* return type */
						char tr[2048];
						tr[0] = 0;
						{
							int from = start;
							while (from < nameIdx && (tokIsJ(from, "static") || tokIsJ(from, "final") ||
							       tokIsJ(from, "abstract") || tokIsJ(from, "synchronized") ||
							       tokIsJ(from, "native") || tokIsJ(from, "default")))
								from++;
							if (from < nameIdx) {
								size_t s0 = tokPosJ(from);
								size_t e0 = tokPosJ(nameIdx - 1) + strlen(tokAtJ(nameIdx - 1));
								size_t o = 0;
								for (size_t q = s0; q < e0 && o + 1 < sizeof(tr); q++) {
									char ch = srcBufChar(q);
									if (ch == '\n' || ch == '\t' || ch == '\r') ch = ' ';
									if (ch == ' ' && o > 0 && tr[o-1] == ' ') continue;
									tr[o++] = ch;
								}
								tr[o] = 0;
							}
						}
						int isfile = 0;
						if (jvN > 0) isfile = jvIsFileScope();
						jvEmit('m', tokAtJ(nameIdx), tokLineJ(nameIdx),
						       sc2[0] ? sc2 : NULL, tr[0] ? tr : NULL, sig,
						       NULL, NULL, access[0] ? access : NULL, 0, 0, isfile);
						continue;
					}
				}
			}
			/* field declaration */
			{
				int lastId = -1;
				int typeEnd = -1;
				int ndecl = 0;
				int i = start;
				int angle = 0;
				while (i < ntkJ()) {
					if (angle == 0) {
						if (tokIsJ(i, "=")) {
							if (lastId >= 0) jvField(lastId, typeEnd, ndecl, access, start);
							ndecl++; lastId = -1;
							i++; continue;
						}
						if (tokIsJ(i, ",")) {
							if (lastId >= 0) jvField(lastId, typeEnd, ndecl, access, start);
							ndecl++; lastId = -1;
							i++; continue;
						}
						if (tokIsJ(i, ";")) break;
					}
					if (tokIsJ(i, "<")) angle++;
					else if (tokIsJ(i, ">")) { if (angle > 0) angle--; }
					else if (angle == 0) {
						if (isalpha((unsigned char)tokAtJ(i)[0]) || tokAtJ(i)[0] == '_' ||
						    tokAtJ(i)[0] == '$') {
							if (tokIsJ(i, "class") || tokIsJ(i, "interface") || tokIsJ(i, "enum") ||
							    tokIsJ(i, "static") || tokIsJ(i, "final") || tokIsJ(i, "public") ||
							    tokIsJ(i, "private") || tokIsJ(i, "protected") ||
							    tokIsJ(i, "transient") || tokIsJ(i, "volatile")) { i++; continue; }
							if (typeEnd < 0) typeEnd = i - 1;
							lastId = i;
						}
					}
